import type { Lang } from '../i18n/useLang'

/**
 * Brändiesittelyjen tekstit.
 *
 * 🔴 `profile` on kirjoitettu omin sanoin brändin omalta sivulta luetuista
 * tosiasioista, EI käännetty heidän markkinointitekstistään. Ks. perustelu
 * data/brands.ts:n kommentista.
 *
 * 🔴 Alkuperävaraukset ("vain sukat ja pipot", "suunnittelu Suomessa mutta
 * valmistus useassa maassa") ovat käännöksissä tarkoituksella kömpelöitä
 * silloin kun luonteva muotoilu olisi hävittänyt varauksen. Väärä
 * alkuperäväite on kuluttajansuoja-asia, sujuvuus ei.
 */
export interface BrandCopy {
  eyebrow: string
  founded: (year: string) => string
  officialSite: (name: string) => string
  productsH2: (name: string) => string
  /** Brändihakemiston otsikko, ingressi ja korttien tuotelaskuri. */
  indexH1: string
  indexIntro: string
  indexCount: (n: number) => string
  profile: Record<string, string>
}

export const BRAND_COPY: Record<Lang, BrandCopy> = {
  en: {
    eyebrow: 'Brand',
    founded: (y) => `Founded in ${y}`,
    officialSite: (n) => `${n}'s own site`,
    productsH2: (n) => `${n} in this shop`,
    indexH1: 'Brands we carry',
    indexIntro:
      'Who makes the things in this shop, and where. Every profile is written from what the brand publishes about itself, and links to their own site.',
    indexCount: (n) => `${n} products`,
    profile: {
      'aarikka':
        'Aarikka is a Finnish design house founded in 1954 by Kaija Aarikka and Erkki Ruokonen, known for wooden beads and jewellery, and owned by Martinex Oy since 2017. The brand credits Finland with design and with hand assembly of its wooden jewellery and wooden home products, but it does not present itself as a wholly Finnish-manufactured range. Its clothing carries explicit per-product manufacturing countries outside Finland, and some raw materials are sourced abroad.',
      'foodin':
        'Foodin is a family-owned Finnish organic food company based in Vaajakoski, Jyväskylä, which describes itself as manufacturing rather than only importing. Its raw chocolate line is stone-ground and hand-finished at the company\'s own Vaajakoski plant, with cocoa sourced from Criollo beans grown in the Peruvian Amazon. The same plant is also named as the production site for the company\'s protein bars.',
      'kuivalihakundi':
        'Kuivalihakundi (Dried Buddy Oy) is a Finnish jerky maker that dries, cuts and packs its meat at its own approved meat plant in Jokela, Tuusula, a roughly 1,500 m2 facility it moved into at the end of 2023. The manufacturing location is backed both by the brand\'s own pages and by the municipality\'s official food-establishment decision. The brand\'s own labelling says the beef is raised and slaughtered in the EU, so the raw meat itself is not confirmed to be Finnish.',
      'halti':
        'Halti is a Finnish outdoor brand founded in 1976 by Juhani Hyokyvaara, with design done at its Sipoo headquarters. The brand states on its own site that production is spread across several countries: China, Vietnam and Bangladesh for technical sportswear, plus European suppliers in Italy, Ukraine and Lithuania. By Halti\'s own account, only socks and beanies are made in Finland, so the brand should be described as Finnish-designed rather than Finnish-made.',
      'north-outdoor':
        'North Outdoor is a Finnish merino wool clothing brand operated by Pyka Oy, best known for the knitting mill it opened in the Rusko district of Oulu in 2021, reported by Yle as the largest wool sweater mill in Finland. The brand splits production across several countries and describes the split by product category rather than as a single origin. Its own published description of that split is internally inconsistent in English, so the per-category breakdown should not be repeated as settled fact.',
      'marttiini':
        'Marttiini is a Finnish knife brand that began in 1928, when blacksmith Janne Marttiini opened a puukko workshop in Rovaniemi. The catalogue today runs from hunting and fillet knives to kitchen knives, folding knives and traditional puukkos, with handles in curly birch or reindeer antler and blades carried in leather sheaths. The broad-bladed Lapinleuku and the fillet knives that carried the brand into export markets are its most recognisable shapes.',
      'kupilka':
        'Kupilka is a Finnish outdoor tableware brand run by the family company Plasthill Oy in Kontiolahti, North Karelia. Its cups, plates and cutlery are moulded from a proprietary Kareline natural fibre composite of roughly half Nordic softwood cellulose and half food-grade polyolefins, produced in-house at the Pyytivaara site on certified renewable electricity. The dishware origin is well documented by the brand, but the wider catalogue (knives and fire steels in particular) draws on outside suppliers.',
      'nordicbuddies':
        'Nordicbuddies is a Helsinki-based Finnish design company (registered as Oy Bisly Ltd) and an official licensee of Moomin, Pippi Longstocking and Mauri Kunnas, selling socks, shirts, caps, bags and other accessories. Design work is done in Helsinki, but the brand\'s own About Us page places manufacturing mainly in Europe and Eurasia with only part of production in Finland, and its cotton in the Anhui and Henan regions of China. Retailer-declared origin data points to China at product level, so the brand should be described as Finnish-designed, not Finnish-made.',
      'marimekko':
        'Marimekko was founded in Finland in 1951 and still runs its own textile printing factory in Helsinki, which prints over a million metres of fabric a year, including every fabric sold by the metre. The finished products themselves are sewn by a network of partner suppliers, and Marimekko names Finland, the Baltic countries, Portugal, China and Thailand among its manufacturing countries. In 2025, 54 percent of products were made in the EU and other European countries, so a Marimekko product cannot be assumed to be made in Finland without checking the individual item.',
      'rento':
        'Rento is a Finnish-designed sauna range owned by the Tampere family company Tammer Brands Oy. The brand designs in Finland and carries the Design from Finland mark widely, but production is split across Finland, other European countries and Amfori BSCI-audited factories, and the country of origin is decided per product rather than per brand. Several items sold as Rento are made outside Finland, so origin has to be checked product by product.',
      'lapuan-kankurit':
        'Lapuan Kankurit is a Finnish weaving company whose main mill is in Lapua and whose roots go back to 1917. By its own account it weaves 95% of its products in Lapua, while the remainder is made at a part-owned mill in Kaunas, Lithuania, and by European subcontractors. All raw materials originate outside Finland: flax from France, the Netherlands and Belgium, mohair from South Africa.',
      'iittala':
        'Iittala is a Finnish design brand built around the Iittala glass factory, founded in 1881 in Iittala village and now part of Fiskars Group. Its parent company describes the Hämeenlinna site as the only glass factory still operating in Finland, employing around 200 people, and Iittala states on its own site that Alvar Aalto vases and Ultima Thule glass are mouth-blown there. Its ceramics, however, are made by contract manufacturers abroad, so the Finnish-origin claim applies to the glassware only.',
      'arctic-warriors':
        'Arctic Warriors is a small Finnish natural-products company registered in the village of Narkaus near Rovaniemi in Lapland, founded in 2014. It sells berry and herb powders and glycerol-based herbal elixirs made from Lappish herbs and berries sourced from local smallholders and foragers. Its own product pages mark origin as Finland but do not state a production or packing location.',
      'makia':
        'Makia is a Helsinki-based clothing company founded in 2001 that designs in Finland and manufactures abroad. Its own pages name Türkiye as the main production country, with jackets and most accessories from China, socks from Portugal and Türkiye, and a small share of woollen accessories made in Finland. However, the brand\'s own pages disagree with each other on the full country list, so no precise per-category origin breakdown can be stated as verified.',
      'pentik':
        'Pentik is a Finnish homeware brand that began in Posio in 1971 and still runs a ceramics factory and an adjoining candle workshop there. The factory does not cover the whole range, though: by the brand\'s own sustainability reporting, roughly a quarter of its products were made in Finland in 2022, with the rest sourced elsewhere in Europe and Asia. Pentik has stated that it does not highlight country of manufacture on its products.',
      'arabia':
        'Arabia is a Finnish ceramics and tableware brand rooted in Helsinki\'s Arabianranta district and today owned by Fiskars Group. Its Helsinki ceramics factory stopped producing in spring 2016, and Fiskars states on its own brand pages that Arabia products now come from long-term contract manufacturers, mainly in Thailand and Romania. Design and product development still happen in Finland, and the Arabia quarter in Helsinki continues as a museum, store and design centre.',
      'fazer':
        'Fazer is a Finnish food company founded in Helsinki in 1891, best known for Karl Fazer milk chocolate, Geisha and Marianne. Beyond confectionery the group runs bakery, mill and restaurant businesses in several countries. Its production footprint is currently shifting: a new chocolate factory is being built in Lahti, and in summer 2026 Fazer bought confectionery factories in Sweden.',
      'moomin':
        'Moomin Characters Oy Ltd is the Helsinki family company that owns and supervises the rights to Tove Jansson\'s Moomin characters, which first appeared in the 1945 book The Moomins and the Great Flood. The company stopped making goods itself decades ago: every item sold as a Moomin product comes from a licensee, and the network runs to more than 800 of them worldwide. On the gift side the most recognisable line is Arabia\'s ceramic Moomin mugs, a series that began in 1990 and now covers over a hundred designs.',
      'wild-about-lapland':
        'Wild About Lapland is an activity operator based in Rovaniemi, with its office at Rovakatu 24. Every tour is capped at eight participants, and the programme runs year round: northern lights trips, snowmobile safaris and reindeer and husky visits in winter, canoeing and hiking in summer. Founder and lead guide Theo Turner is a former Royal Marines commando and outdoor instructor, and the company carries the Sustainable Travel Finland label.',
      'meritalo':
        'Meritalo is a Finnish family berry processor founded in 1995 by Susanna and Olavi Lindstedt, who moved from Helsinki to Ylonkyla in the Salo area of Southwest Finland. The company states that all of its products are made at its own premises there, using 100% Finnish berries and fruit bought from Finnish growers and picked in Finnish forests. The range is built around jams and jellies, juices and birch sap, and includes a 310 g sea buckthorn jam alongside strawberry, lingonberry and apple products.',
      'nordqvist':
        'Nordqvist is a Finnish tea company founded in 1979, which started as a Helsinki shop selling flavoured and loose-leaf teas and later moved into importing and wholesale. Its teas are flavoured and packed at the company\'s own 3,000 square metre factory in Nurmijärvi, opened in 2018. The range covers long-running blends such as Keisarin Morsian and Tiikerin Päiväuni alongside a Moomin-themed tea line sold in bags, loose leaf and tins.',
      'puhdistamo':
        'Puhdistamo is a Finnish wellness brand founded in 2009 that sells vitamins, minerals and other supplements alongside energy drinks, kombucha, protein and raw chocolate bars, and superfoods. The company runs its own factory in Lempäälä, Finland, where it makes most of its supplements and reports producing over 80 million capsules in a single year. The plant holds FSSC 22000 food safety certification, and the company states that its drinks are sweetened with stevia or organic cane sugar instead of aspartame, acesulfame K or sucralose.',
      'emendo':
        'Emendo Oy is a Finnish sauna and wellness company based in Vaasa, which states on its own site that it was founded in 1986. Its range covers sauna and loyly fragrances, sauna honeys, linen-cotton sauna textiles, ladles, soaps and skin care products, sold under two names, Emendo and KOLO Sauna. The company says it manufactures its fragrances, sauna honeys and face, body and foot care products in Finland, and its Moomin sauna items are licensed from Moomin Characters and based on Tove Jansson\'s original drawings.',
      'moomin-arabia':
        'Moomin Arabia is the Moomin range of the Finnish ceramics brand Arabia, founded in 1873 and today part of Fiskars Group. The first Moomin dishes appeared in the 1950s with illustrations by Tove Jansson, and the widely collected mug series began in the 1990s using Kaj Franck\'s Teema shape. Design work is done at the company\'s Espoo headquarters in Finland, while Fiskars Group states that Arabia products are made by contract manufacturers mainly in Thailand and Romania.',
      'kaino-drinks':
        'KAINO Drinks is a non-alcoholic sparkling drink range from Poikain Parhaat Oy, a food company based in Tampere, Finland. The spruce sprout drink is made by hand in Tampere from Finnish spruce sprouts, and the drinks are 0.0% alcohol, vegan and certified organic under FI-EKO-201. The range covers spruce sprout, rhubarb and rose, and blackcurrant leaf, sold in 0.75 litre and 0.2 litre bottles.',
      'omega7':
        'Omega7 is a Finnish sea buckthorn oil supplement brand whose first products reached the market in 1997. Its SBA24 double sea buckthorn oil combines berry oil and seed oil, and it is extracted with a solvent-free process at the company\'s factory in Tornio. The producer, Aromtech Oy, has run clinical studies with researchers and doctors from the University of Turku and Turku University Hospital, and it runs an organic sea buckthorn cultivation pilot in Tervola, Lapland.',
      'kaapa-mushrooms':
        'KÄÄPÄ Mushrooms is a Finnish functional mushroom producer founded in 2018 by Eric Puro, Otso Mursula and Seppo Riikonen. Its head office and production facility are in Karjalohja in southern Finland, where mushrooms are grown on birch substrate from FSC and PEFC certified Finnish forests and extracted with the company\'s own NordRelease ultrasonic method using purified spring water. The company holds FSSC 22000 food safety certification, makes its extracts from fruiting bodies rather than myceliated grain, and runs a forest chaga cultivation network through its KÄÄPÄ Forest division.',
      'halva':
        'Halva is a Finnish family confectionery company founded in 1931 by brothers Jean and Michael Karavokyros, who had moved to Finland from Greece. It is best known for licorice and salmiakki sweets, and the company states that its candy factory and packing plant are in Pitajanmaki, Helsinki. The business is now run by the third generation, and the sesame paste halva that gave the company its name is still in the range.',
      'kilpissafarit':
        'Kilpissafarit is a programme service company in Kilpisjarvi, founded in 1995 by border guard Hannu Rauhala and now run by his son Jussi Rauhala. It guides snowmobile safaris, snowshoe and hiking trips, northern lights outings and fishing trips in the Kasivarsi wilderness, including a snowmobile route to Halti, the highest point in Finland. The same base rents out snowmobiles, electric fatbikes, snowshoes, canoes and kayaks for people heading out on their own.',
      'kaavi-porcini':
        'Kaavi Porcini is the brand of Kaavin Herkkutattitehdas Oy, a Finnish company that dries wild forest mushrooms at its own factory in Tohmajärvi. The mushrooms are gathered in the forests of North Savo and North Karelia and dried on the day they are picked. The range covers porcini, chanterelle, funnel chanterelle and black trumpet, plus chaga collected in Kittilä and a porcini powder used as a seasoning.',
      'tammer':
        'Tammer Brands is a family-owned company from Tampere, founded in 1954 as Tammer-Tukku and renamed Tammer Brands Oy in 2019. It develops and distributes consumer products for the home, garden and leisure under a portfolio of more than 50 brands, among them the Rento sauna range, the Mustang grilling brand and Maku Kitchen Life. For Rento the company states that products are made in Finland, elsewhere in Europe or in amfori BSCI audited factories, with the country of manufacture given on each product card.',
      'finlayson':
        'Finlayson traces its start to 1820, when the Scot James Finlayson set up a machine workshop by the Tammerkoski rapids in Tampere. The cotton mill that grew around it became Finland\'s largest private employer by 1975, with 11 factories and 6,500 workers, and the company is still known for household names like the Elefantti pattern that Laina Koskela designed in 1969 and for putting the duvet cover on the Finnish market in 1963. Today Finlayson sells bed linen, towels, kitchen textiles and rugs, publishes its factory list, and weaves its Rasypala rugs in Finland from sheets returned by customers.',
      'finnish-flavours':
        'Finnish Flavours is a Finnish food brand run from Kerava. Its range centres on liquorice in two lines, Premium Palalaku pieces and chocolate-coated Premium Chocolaku, alongside lingonberry, blueberry and cloudberry jams, Finnish rainbow trout and dried reindeer meat. The brand states that its jams are made in Finland entirely from domestic berries, and its listed retailers run from Finnish K-stores and a Rovaniemi shop to importers in the United States, Canada, Switzerland, the United Kingdom and New Zealand.',
      'aurora-borealis':
        'Aurora Borealis is a house brand of Tammer Brands Oy, a family-owned Finnish brand and wholesale company headquartered in Tampere whose roots go back to 1954. The range covers decorative pieces, everyday items, accessories and flags built around Finnish nature motifs: forests, reindeer, huskies, the northern lights and the Finnish flag. Products carried under the name include wooden kuksa cups, plush reindeer and huskies, mugs, tote bags and playing cards.',
      'fiskars':
        'Fiskars began in 1649, when Peter Thorwöste was granted permission to set up a blast furnace and a blacksmith shop in a Finnish village of the same name. The brand is best known for its orange-handled scissors, launched in 1967 as the first scissors with plastic handles; the Classic model is still made at the company\'s Billnäs factory in Finland and every pair is tested by hand. Alongside scissors, Fiskars sells garden tools, axes and kitchen knives.',
      'arctic-power-berries':
        'Arctic Power Berries is a berry powder brand run by Anna and Eveliina, two childhood friends from Rovaniemi in Finnish Lapland who started the business after moving to London. The range is single-berry powders in 70g pouches: blueberry (bilberry), lingonberry, sea buckthorn, blackcurrant, cranberry, strawberry and raspberry, plus a mixed berry blend. The company says the wild berries are picked by hand in Finland, gently dried and ground, with roughly 700g of fresh berries behind each 70g pouch and nothing else added.',
      'golden-crown-levin-iglut':
        'Levin Iglut Golden Crown is a family-run glass igloo resort on the Utsuvaara fell next to Levi in Finnish Lapland. Tauno Mäkelä built the first four igloos in 2008, and the site now has 27 glass igloos, the six-person Northern Lights House villa and its own Restaurant Utsu, open from late August to early April. For gift buyers the relevant items are its gift cards for igloo stays and Utsu dinners, and the Golden Crown Shop at reception, which carries Finnish design and craft brands.',
      'sisu':
        'Sisu is a Finnish pastille brand launched in 1928. The recipe was worked out by chemist Johan Ponkamo in the cellar of the Seres confectionery factory in Turku, and the pastille is built on a gum arabic base with a salmiakki flavour. The brand now sits in Cloetta\'s portfolio and covers salmiakki, menthol and licorice pastilles, sugar-free and xylitol versions, and since 2022 also candy bags.',
      'kultakuume-com':
        'Kultakuume is a family-run business in Saariselkä, Finnish Lapland, which says it has operated in the area since 2008 and rented cabins since 2009. It sells guided gold panning days on its own claim, where visitors are taught hand panning, watch mechanised washing, and keep any gold they find. Alongside the trips it rents the Kultakelo log cabins on Kaunispää and sells a set of 18 canvas prints on gold panning themes, each 100 x 100 cm.',
      'muurla':
        'Muurla is a Finnish design company whose story began at a glass factory in Muurla, Southwest Finland, where the factory shop opened in spring 1974. It is known today for enamel mugs and tableware, glassware and birch veneer serving boards, and for its licensed Moomin collection. Muurla says all its products are designed in Finland, while the country of manufacture varies by product: birch veneer items are made in Finland, most enamelware in Europe, and glass in both Europe and Asia.',
      'novita':
        'Novita is a Finnish yarn company founded in 1928 by Ernst Gylfe, who learned worsted wool spinning in Bradford, England before starting production in Helsinki. The business is still family owned in its fourth generation and has run its spinning mill in Koria, Kouvola since 1974, where it says it produces about one million kilos of yarn a year. Its best known product is the 7 Veljestä sock yarn, spun from wool the company reports sourcing mainly from Europe, chiefly England.',
      'mikebon':
        'Mikebon Oy is a family-run textile printing and embroidery company founded in 1994 and based in Petikko, Vantaa. It handles design, graphic execution, production and logistics itself, and states on its own site that production takes place in Finland. Its main customers are souvenir and gift retailers, and it also runs a consumer webshop whose ranges include Lapland, Finland and Moomin themed shirts and hoodies.',
      'aromageddon':
        'Aromageddon is a sauna scent range from Aromageddon Oy, a company registered in Helsinki, which dates the idea to a sauna session in summer 2024. The line covers six 15 ml scents at 7.90 euros each plus three gift sets, and the themes come from drinks and sweets rather than forest or birch: whisky, beer, ice mint, peppermint candy, cinnamon and mint cocoa. The company publishes a CLP safety data sheet for every scent on its own site, and the drink-themed versions carry the flavour note without alcohol.',
      'leijona':
        'Leijona is a Finnish pastille brand owned by Cloetta, best known for Leijona Tervalakritsi, a sugar-coated liquorice pastille flavoured with tar. It was developed by pharmacist Yrjö Jalander, founder of the Oulu confectionery company Merijal, and reached the market in 1933. Alongside the 32 g pastille boxes the current range includes 180 g candy bags, and the brand is run by Cloetta Suomi Oy from Turku.',
    },
  },
  fi: {
    eyebrow: 'Brändi',
    founded: (y) => `Perustettu ${y}`,
    officialSite: (n) => `Omat sivut: ${n}`,
    productsH2: (n) => `${n} tässä kaupassa`,
    indexH1: 'Brändit',
    indexIntro:
      'Kuka tekee tämän kaupan tavarat ja missä. Jokainen esittely on kirjoitettu siitä, mitä brändi itse kertoo, ja linkittää brändin omille sivuille.',
    indexCount: (n) => `${n} tuotetta`,
    profile: {
      'aarikka':
        'Aarikka on suomalainen designtalo, jonka Kaija Aarikka ja Erkki Ruokonen perustivat vuonna 1954 ja joka on ollut Martinex Oy:n omistuksessa vuodesta 2017. Brändi kertoo suunnittelevansa Suomessa ja kokoavansa puukorunsa ja puiset kodintuotteensa käsin Suomessa, mutta se ei esitä koko mallistoaan Suomessa valmistettuna: vaatteille ilmoitetaan tuotekohtainen valmistusmaa Suomen ulkopuolelta.',
      'foodin':
        'Foodin on vaajakoskelainen perheyritys, joka valmistaa luomuruokaa ja luonnontuotteita omalla tehtaallaan Jyväskylässä. Raakasuklaat jauhetaan kivimyllyllä ja viimeistellään käsityönä Vaajakoskella, ja kaakao tulee Perun Amazonian Criollo-pavuista. Sama tehdas mainitaan myös proteiinipatukoiden valmistuspaikkana.',
      'kuivalihakundi':
        'Kuivalihakundi (Dried Buddy Oy) on suomalainen jerkyn valmistaja, joka kuivaa, leikkaa ja pakkaa lihansa omassa hyväksytyssä lihalaitoksessaan Jokelassa Tuusulassa. Yritys muutti noin 1 500 neliön tehtaaseen vuoden 2023 lopussa, ja valmistuspaikka löytyy sekä brändin omilta sivuilta että kunnan virallisesta laitospäätöksestä. Raaka-aineliha on brändin oman tuoteselosteen mukaan EU-alueelta, joten lihaa itseään ei voi kutsua vahvistetusti suomalaiseksi.',
      'halti':
        'Halti on vuonna 1976 perustettu suomalainen ulkoilubrändi, jonka suunnittelu tehdään Sipoon pääkonttorilla. Brändi kertoo omalla sivullaan valmistuttavansa tuotteita useassa maassa: teknisissä urheilutekstiileissä Kiinassa, Vietnamissa ja Bangladeshissa sekä eurooppalaisilla toimittajilla Italiassa, Ukrainassa ja Liettuassa. Haltin oman ilmoituksen mukaan Suomessa valmistetaan vain sukat ja pipot, joten kyse on suomalaisesta suunnittelusta eikä suomalaisesta valmistuksesta.',
      'north-outdoor':
        'North Outdoor on Pyka Oy:n merinovillavaatebrändi, joka avasi vuonna 2021 oman neulomon Oulun Ruskoon; Yle uutisoi sen Suomen suurimpana villapaitaneulomona. Brändin tuotanto jakautuu useaan maahan, ja brändi kuvaa jaon tuoteryhmittäin eikä yhtenä alkuperänä. Sen oma kuvaus tästä jaosta on englanniksi sisäisesti ristiriitainen, joten tuoteryhmäkohtaista erittelyä ei pidä toistaa varmana tietona.',
      'marttiini':
        'Marttiini on suomalainen puukkobrändi, jonka seppä Janne Marttiini perusti Rovaniemelle vuonna 1928. Mallisto ulottuu metsästys- ja fileointipuukoista keittiöveitsiin, taittoveitsiin ja perinnepuukkoihin; kahvoissa käytetään visakoivua ja poronsarvea, tupet ovat nahkaa. Tunnetuimpia muotoja ovat leveäteräinen lapinleuku ja kalastajille tehdyt fileeveitset.',
      'kupilka':
        'Kupilka on suomalainen retkiastiabrändi, jota pyörittää perheyritys Plasthill Oy Kontiolahdella Pohjois-Karjalassa. Kupit, lautaset ja aterimet muovataan omasta Kareline-luonnonkuitukomposiitista, jossa on suunnilleen puoliksi pohjoismaista havusellua ja puoliksi elintarvikelaatuista polyolefiinia. Astiaston alkuperä on brändin itsensä hyvin dokumentoima, mutta laajemmassa valikoimassa (etenkin puukoissa ja tulentekovälineissä) on ulkopuolisia toimittajia.',
      'nordicbuddies':
        'Nordicbuddies on helsinkiläinen suomalainen designyritys (Oy Bisly Ltd) ja virallinen Muumi-, Peppi Pitkätossu- ja Mauri Kunnas -lisenssinhaltija, joka myy sukkia, paitoja, lippiksiä, laukkuja ja muita asusteita. Suunnittelu tehdään Helsingissä, mutta brändin oma About Us -sivu sijoittaa valmistuksen pääosin Eurooppaan ja Euraasiaan ja puuvillan Kiinan Anhuin ja Henanin alueille – vain osa tuotannosta on Suomessa. Jälleenmyyjien ilmoittama alkuperämaa on tuotetasolla Kiina, joten brändi tulee kuvata suomalaisena suunnitteluna, ei suomalaisvalmisteisena.',
      'marimekko':
        'Marimekko on perustettu Suomessa 1951, ja sillä on yhä oma tekstiilipaino Helsingissä, jossa painetaan yli miljoona metriä kangasta vuodessa – muun muassa kaikki metritavarana myytävä kangas. Valmiit tuotteet ompelee kumppanitoimittajien verkosto, ja Marimekko nimeää valmistusmaikseen Suomen, Baltian maat, Portugalin, Kiinan ja Thaimaan. Vuonna 2025 tuotteista 54 % valmistui EU- ja muissa Euroopan maissa, joten yksittäisen tuotteen alkuperää ei voi päätellä brändin perusteella.',
      'rento':
        'Rento on tamperelaisen perheyrityksen Tammer Brands Oy:n omistama saunatuotesarja. Suunnittelu tehdään Suomessa ja Design from Finland -merkki on laajasti käytössä, mutta valmistus jakautuu Suomen, muun Euroopan ja Amfori BSCI -auditoitujen tehtaiden kesken. Valmistusmaa määräytyy tuotekohtaisesti eikä brändin tasolla, joten alkuperä on tarkistettava tuote kerrallaan.',
      'lapuan-kankurit':
        'Lapuan Kankurit on suomalainen kutomobrändi, jonka pääkutomo sijaitsee Lapualla ja jonka juuret ulottuvat vuoteen 1917. Yritys kertoo itse kutovansa Lapualla 95 % tuotteistaan, mutta loput syntyvät osaomisteisessa kutomossa Kaunasissa Liettuassa ja eurooppalaisilla alihankkijoilla. Raaka-aineet tulevat kokonaan Suomen ulkopuolelta: pellava Ranskasta, Alankomaista ja Belgiasta, mohair Etelä-Afrikasta.',
      'iittala':
        'Iittala on suomalainen designbrändi, jonka ydin on vuonna 1881 Iittalan kylään perustettu lasitehdas; omistaja on nykyään Fiskars Group. Emoyhtiön mukaan Hämeenlinnan tehdas on Suomen ainoa yhä toimiva lasitehdas ja työllistää noin 200 henkeä, ja Iittala kertoo omilla sivuillaan Alvar Aalto -maljakoiden ja Ultima Thulen syntyvän siellä suupuhaltamalla. Keramiikka sen sijaan valmistetaan sopimusvalmistajilla ulkomailla, joten suomalaisuusväite pätee vain lasituotteisiin.',
      'arctic-warriors':
        'Arctic Warriors on pieni suomalainen luonnontuoteyritys, joka on rekisteröity Narkauksen kylään Rovaniemen lähelle ja perustettu vuonna 2014. Se myy marja- ja yrttijauheita sekä kasviglyserolipohjaisia yrttieliksiirejä, joiden raaka-aineet tulevat lappilaisilta pienviljelijöiltä ja keräilijöiltä. Brändin omilla tuotesivuilla alkuperäksi merkitään Suomi, mutta valmistus- tai pakkauspaikkaa ei kerrota.',
      'makia':
        'Makia on vuonna 2001 perustettu helsinkiläinen vaatebrändi, joka suunnittelee Suomessa mutta valmistuttaa ulkomailla. Brändin omien sivujen mukaan päätuotantomaa on Turkki, takit ja suurin osa asusteista tulee Kiinasta, sukkia tehdään Portugalissa ja Turkissa, ja Suomessa valmistetaan vain pieni osa villa-asusteista. Tarkkaa tuoteryhmäkohtaista alkuperäjakaumaa ei voi kuitenkaan esittää vahvistettuna, koska brändin omat sivut ovat keskenään ristiriidassa maalistan osalta.',
      'pentik':
        'Pentik on vuonna 1971 Posiolla aloittanut suomalainen sisustusbrändi, jonka tunnetuin osa on paikkakunnalla yhä toimiva keramiikkatehdas ja sen yhteydessä oleva kynttiläpaja. Tehdas ei kuitenkaan kata koko valikoimaa: brändin oman vastuullisuusraportoinnin mukaan noin neljännes tuotteista valmistettiin Suomessa vuonna 2022, ja loput tulevat muualta Euroopasta ja Aasiasta. Pentik on itse kertonut, ettei se korosta valmistusmaata tuotteissaan.',
      'arabia':
        'Arabia on helsinkiläislähtöinen keramiikka- ja astiabrändi, joka kuuluu nykyään Fiskars Groupiin. Helsingin keramiikkatehtaan tuotanto päättyi keväällä 2016, ja Fiskars kertoo omilla brändisivuillaan, että Arabian tuotteet tulevat pitkäaikaisilta sopimusvalmistajilta pääasiassa Thaimaasta ja Romaniasta. Muotoilu ja tuotekehitys tehdään yhä Suomessa, ja Arabian kortteli Helsingissä toimii museona, myymälänä ja designkeskuksena.',
      'fazer':
        'Fazer on vuonna 1891 Helsingissä perustettu suomalainen elintarvikeyhtiö, jonka tunnetuimpia tuotteita ovat Karl Fazerin sininen maitosuklaa, Geisha ja Marianne. Konserni tekee makeisten lisäksi leipomo-, mylly- ja ravintolaliiketoimintaa useassa maassa. Tuotantoverkosto on juuri nyt murroksessa: Lahteen rakennetaan uutta suklaatehdasta.',
      'moomin':
        'Moomin Characters Oy Ltd on helsinkiläinen perheyhtiö, joka omistaa ja valvoo Tove Janssonin muumihahmojen oikeuksia; hahmot esiteltiin ensi kerran vuoden 1945 kirjassa Muumit ja suuri tuhotulva. Yhtiö ei valmista tuotteita itse, vaan kaikki muumituotteet tekevät lisenssinsaajat, joita on yli 800 eri puolilla maailmaa. Lahjatuotteista tunnetuimpia ovat Arabian keramiikkamukit, joiden sarja alkoi vuonna 1990.',
      'wild-about-lapland':
        'Wild About Lapland on rovaniemeläinen ohjelmapalveluyritys, jonka toimisto sijaitsee osoitteessa Rovakatu 24. Yritys rajaa jokaisen retken enintään kahdeksaan osallistujaan ja järjestää ohjelmaa ympäri vuoden: talvella revontuliretkiä, moottorikelkkasafareita sekä poro- ja huskyvierailuja, kesällä melontaa ja vaelluksia. Perustaja ja pääopas Theo Turner on entinen Royal Marines -kommando ja ulkoilualan ohjaaja, ja yrityksellä on Sustainable Travel Finland -merkki.',
      'meritalo':
        'Meritalo on suomalainen marjanjalostaja, jonka Susanna ja Olavi Lindstedt perustivat vuonna 1995 muutettuaan Helsingistä Ylönkylään Salon seudulle. Yritys kertoo valmistavansa kaikki tuotteensa omissa tiloissaan Ylönkylässä ja käyttävänsä sataprosenttisesti suomalaisia marjoja ja hedelmiä, jotka tulevat suomalaisilta viljelijöiltä ja metsistä. Valikoiman runko ovat hillot ja hyytelöt, mehut ja mahla.',
      'nordqvist':
        'Nordqvist on vuonna 1979 perustettu suomalainen teetalo, joka aloitti Helsingissä maustettuihin ja irtoteihin erikoistuneena myymälänä ja laajeni myöhemmin maahantuontiin ja tukkukauppaan. Teet maustetaan ja pakataan yhtiön omalla, vuonna 2018 käyttöön otetulla 3 000 neliön tehtaalla Nurmijärvellä. Valikoimassa ovat muun muassa klassikkosekoitukset Keisarin Morsian ja Tiikerin Päiväuni sekä Muumi-teemainen teesarja pusseina, irtoteenä ja teerasiassa.',
      'puhdistamo':
        'Puhdistamo on vuonna 2009 perustettu suomalainen hyvinvointibrändi, jonka valikoimaan kuuluu vitamiineja, kivennäisaineita ja muita ravintolisiä sekä energiajuomia, kombuchaa, proteiini- ja raakasuklaapatukoita ja superfoodeja. Yrityksellä on oma tehdas Lempäälässä, jossa valmistetaan suurin osa sen ravintolisistä; kapseleita kerrotaan syntyneen siellä yhden vuoden aikana yli 80 miljoonaa. Tehtaalla on FSSC 22000 -elintarviketurvallisuussertifikaatti, ja yritys ilmoittaa makeuttavansa juomansa stevialla tai luomuruokosokerilla eikä aspartaamilla, asesulfaami K:lla tai sukraloosilla.',
      'emendo':
        'Emendo Oy on vaasalainen sauna- ja hyvinvointialan yritys, joka kertoo omalla sivullaan perustamisvuodekseen 1986. Valikoimaan kuuluvat saunatuoksut ja löylytuoksut, saunahunajat, pellava-puuvillatekstiilit, kiulut, saippuat ja ihonhoitotuotteet kahdella tuotemerkillä, Emendo ja KOLO Sauna. Yritys ilmoittaa valmistavansa Suomessa tuoksut, saunahunajat sekä kasvojen-, vartalon- ja jalkojenhoitotuotteet, ja sen Muumi-saunatuotteet ovat Moomin Characters -lisenssituotteita, jotka pohjautuvat Tove Janssonin alkuperäispiirustuksiin.',
      'moomin-arabia':
        'Moomin Arabia on suomalaisen keramiikkabrändin Arabian muumisarja. Arabia perustettiin vuonna 1873 ja kuuluu nykyään Fiskars Groupiin; ensimmäiset muumiastiat tulivat 1950-luvulla Tove Janssonin kuvituksin, ja laajalti kerätty mukisarja alkoi 1990-luvulla Kaj Franckin Teema-muotoon pohjautuen. Suunnittelu tehdään Espoon pääkonttorilla, mutta Fiskars Groupin mukaan Arabian tuotteet valmistetaan sopimusvalmistajilla pääosin Thaimaassa ja Romaniassa.',
      'kaino-drinks':
        'KAINO Drinks on tamperelaisen Poikain Parhaat Oy:n alkoholittomien kuohujuomien sarja. Kuusenkerkkäjuoma valmistetaan suomalaisesta kuusenkerkästä käsityönä Tampereella, ja juomat ovat 0,0-prosenttisia, vegaanisia ja luomusertifioituja tunnuksella FI-EKO-201. Valikoimaan kuuluvat kuusenkerkkä, raparperi & ruusu sekä mustaherukanlehti, ja pullokoot ovat 0,75 litraa ja 0,2 litraa.',
      'omega7':
        'Omega7 on suomalainen tyrniöljyvalmisteiden tuotemerkki, jonka ensimmäiset tuotteet tulivat markkinoille vuonna 1997. Tuotteiden SBA24-kaksoistyrniöljy yhdistää tyrnin marjaöljyn ja siemenöljyn, ja se uutetaan liuotinvapaalla menetelmällä yhtiön tehtaalla Torniossa. Valmistaja Aromtech Oy on tehnyt kliinistä tutkimusta Turun yliopiston ja TYKSin tutkijoiden kanssa ja ylläpitää luomutyrnin viljelypilottia Tervolassa.',
      'kaapa-mushrooms':
        'KÄÄPÄ Mushrooms on suomalainen funktionaalisten sienten valmistaja, jonka perustivat vuonna 2018 Eric Puro, Otso Mursula ja Seppo Riikonen. Yrityksen pääkonttori ja tuotantolaitos ovat Karjalohjalla Etelä-Suomessa, ja sienet kasvatetaan FSC- ja PEFC-sertifioiduista suomalaisista metsistä peräisin olevalla koivualustalla. Uutteet tehdään yrityksen omalla NordRelease-ultraäänimenetelmällä puhdistetusta lähdevedestä, raaka-aineena käytetään itiemaljoja rihmastoviljan sijaan, ja yrityksellä on FSSC 22000 -elintarviketurvallisuussertifikaatti.',
      'halva':
        'Halva on vuonna 1931 perustettu suomalainen perheyritys, jonka perustivat Kreikasta Suomeen muuttaneet veljekset Jean ja Michael Karavokyros. Yritys tunnetaan ennen kaikkea lakritsi- ja salmiakkimakeisista, ja se kertoo makeistehtaansa ja pakkaamonsa sijaitsevan Helsingin Pitäjänmäessä. Yritystä luotsaa kolmas sukupolvi, ja valikoimassa on yhä seesamitahnasta tehty halva, joka antoi yritykselle nimen.',
      'kilpissafarit':
        'Kilpissafarit on kilpisjärveläinen ohjelmapalveluyritys, jonka rajavartija Hannu Rauhala perusti vuonna 1995 ja jota nykyään vetää hänen poikansa Jussi Rauhala. Yritys opastaa moottorikelkkasafareita, lumikenkä- ja vaellusretkiä, revontuliretkiä ja kalastusretkiä Käsivarren erämaassa, muun muassa kelkkareitin Suomen korkeimmalle kohdalle Haltille. Samasta toimipisteestä vuokrataan kelkkoja, sähköfatbikejä, lumikenkiä, kanootteja ja kajakkeja omatoimisille retkeilijöille.',
      'kaavi-porcini':
        'Kaavi Porcini on Kaavin Herkkutattitehdas Oy:n tuotemerkki. Yritys kuivaa luonnonvaraisia metsäsieniä omassa tehtaassaan Tohmajärvellä, ja sienet kuivataan samana päivänä kun ne on poimittu Pohjois-Savon ja Pohjois-Karjalan metsistä. Valikoimaan kuuluvat herkkutatti, kanttarelli, suppilovahvero ja mustatorvisieni sekä Kittilästä kerätty pakurikääpä ja tattijauhe.',
      'tammer':
        'Tammer Brands on tamperelainen perheyritys, joka perustettiin vuonna 1954 nimellä Tammer-Tukku ja joka otti nykyisen nimensä vuonna 2019. Yhtiö kehittää ja jakelee kodin, puutarhan ja vapaa-ajan kuluttajatuotteita yli 50 brändin salkulla; niihin kuuluvat muun muassa saunasarja Rento, grillibrändi Mustang ja keittiötuotteiden Maku Kitchen Life. Rennosta yhtiö kertoo, että tuotteet valmistetaan Suomessa, muualla Euroopassa tai amfori BSCI -auditoiduissa tehtaissa ja että valmistusmaa on merkitty tuotekorttiin.',
      'finlayson':
        'Finlaysonin historia alkaa vuodesta 1820, jolloin skotlantilainen James Finlayson perusti konepajan Tammerkosken rannalle Tampereelle. Sen ympärille kasvaneesta puuvillatehtaasta tuli vuoteen 1975 mennessä Suomen suurin yksityinen työnantaja, jolla oli 11 tehdasta ja 6 500 työntekijää. Yritys tunnetaan yhä kuoseistaan, kuten Laina Koskelan vuonna 1969 suunnittelemasta Elefantista, sekä pussilakanasta, jonka se toi Suomen markkinoille 1963. Nykyään valikoimaan kuuluvat vuodevaatteet, pyyhkeet, keittiötekstiilit ja matot, ja Räsypala-matot kudotaan Suomessa asiakkaiden palauttamista lakanoista.',
      'finnish-flavours':
        'Finnish Flavours on keravalainen elintarvikebrändi, jonka valikoiman ytimessä on lakritsi: palalakritsisarja Premium Palalaku ja suklaakuorrutettu Premium Chocolaku. Saman brändin alta löytyy myös puolukka-, mustikka- ja lakkahilloja, suomalaista kirjolohta ja poronkuivalihaa. Brändi kertoo hillojen olevan valmistettu Suomessa kokonaan kotimaisista marjoista, ja jälleenmyyjälistalla on K-kauppojen ja rovaniemeläisen Samarundin lisäksi maahantuojia Yhdysvalloissa, Kanadassa, Sveitsissä, Britanniassa ja Uudessa-Seelannissa.',
      'aurora-borealis':
        'Aurora Borealis on tamperelaisen Tammer Brands Oy:n oma brändi. Yhtiö on suomalainen perheyritys ja bränditalo, jonka juuret ulottuvat vuoteen 1954. Valikoimassa on koriste- ja käyttöesineitä, asusteita ja lippuja, joiden aiheina ovat metsä, porot, huskyt, revontulet ja Suomen lippu; brändin nimellä myydään muun muassa kuksia, pehmoeläimiä, mukeja, kangaskasseja ja pelikortteja.',
      'fiskars':
        'Fiskarsin juuret ovat vuodessa 1649, jolloin Peter Thorwöste sai luvan perustaa masuunin ja sepänpajan Fiskarsin kylään. Brändi tunnetaan parhaiten oranssikahvaisista saksistaan, jotka tulivat markkinoille vuonna 1967 ensimmäisinä muovikahvaisina saksina. Classic-sakset valmistetaan yhä Billnäsin tehtaalla Suomessa ja jokainen pari testataan käsin; valikoimaan kuuluvat lisäksi puutarhatyökalut, kirveet ja keittiöveitset.',
      'arctic-power-berries':
        'Arctic Power Berries on marjajauhebrändi, jota pyörittävät Anna ja Eveliina, kaksi lapsuudenystävää Rovaniemeltä. Yritys sai alkunsa Lontoossa, jonne perustajat muuttivat, ja valikoima on yhden marjan jauheita 70 gramman pusseissa: mustikka, puolukka, tyrni, mustaherukka, karpalo, mansikka ja vadelma sekä sekamarjajauhe. Yrityksen oman kertoman mukaan luonnonmarjat poimitaan käsin Suomessa, kuivataan hellävaraisesti ja jauhetaan, ja yhteen 70 gramman pussiin menee noin 700 grammaa tuoreita marjoja ilman lisättyjä aineita.',
      'golden-crown-levin-iglut':
        'Levin Iglut Golden Crown on perheomisteinen lasi-iglukohde Utsuvaaralla Levin kupeessa. Tauno Mäkelä rakensi ensimmäiset neljä iglua vuonna 2008, ja nykyään alueella on 27 lasi-iglua, kuuden hengen Revontulitalo-villa sekä oma ravintola Utsu. Kohde on auki elokuun lopusta huhtikuun alkuun, ja lahjaostajalle olennaisia ovat majoitus- ja illallislahjakortit sekä vastaanotossa toimiva Golden Crown Shop, jonka valikoimassa on suomalaisia design- ja käsityöbrändejä.',
      'sisu':
        'Sisu on suomalainen pastillimerkki, joka tuli markkinoille vuonna 1928. Reseptin kehitti kemisti Johan Ponkamo turkulaisen Sereksen makeistehtaan kellarissa, ja pastillin pohjana on arabikumi ja salmiakkinen maku. Merkki kuuluu nykyään Cloettalle, ja valikoimaan kuuluu salmiakki-, mentoli- ja lakritsipastilleja, sokerittomia ja ksylitolilla makeutettuja versioita sekä vuodesta 2022 myös karkkipusseja.',
      'kultakuume-com':
        'Kultakuume on saariselkäläinen perheyritys, jonka mukaan sillä on ollut yritystoimintaa Saariselällä vuodesta 2008 ja mökkivuokrausta vuodesta 2009. Yritys myy opastettuja kullankaivuupäiviä omalla kultavaltauksellaan: mukana on käsinhuuhdonnan opetus, koneellisen huuhdonnan seuraaminen ja kultatakuu, jonka mukaan löydetyt kullat saa pitää. Retkien lisäksi yritys vuokraa Kaunispään Kultakelo-kelomökkejä ja myy 18 nimikkeen canvas-taulukokoelmaa kullankaivuuaiheista.',
      'muurla':
        'Muurla on suomalainen designyritys, jonka tarina alkoi Muurlan lasitehtaalta Varsinais-Suomessa: tehtaanmyymälä avattiin keväällä 1974. Yritys tunnetaan etenkin emalimukeista ja -astioista, lasituotteista ja koivuviilutarjottimista sekä Muumi-lisenssimallistostaan. Tuotteet suunnitellaan Suomessa, mutta valmistusmaa vaihtelee tuotteittain: koivuviilutuotteet tehdään Suomessa, suurin osa emalituotteista Euroopassa ja lasituotteet sekä Euroopassa että Aasiassa.',
      'novita':
        'Novita on vuonna 1928 perustettu suomalainen lankavalmistaja. Perustaja Ernst Gylfe opiskeli kampavillalangan kehruuta Bradfordissa Englannissa ja aloitti tuotannon Helsingissä; yritys on yhä saman perheen omistuksessa neljännessä sukupolvessa. Kehräämö on toiminut Korialla Kouvolassa vuodesta 1974, ja tunnetuin tuote on 7 Veljestä -sukkalanka, jonka villa tulee yhtiön mukaan pääosin Euroopasta, etenkin Englannista.',
      'mikebon':
        'Mikebon Oy on vuonna 1994 perustettu vantaalainen perheyritys, joka painaa ja brodeeraa tekstiilejä. Yritys hoitaa suunnittelun, graafisen toteutuksen, tuotannon ja logistiikan itse ja kertoo omilla sivuillaan tuotannon tapahtuvan Suomessa. Pääasiakkaita ovat matkamuisto- ja lahjatavarakauppiaat, minkä lisäksi yritys ylläpitää kuluttajaverkkokauppaa, jonka mallistoihin kuuluu muun muassa Lappi-, Suomi- ja muumiaiheisia paitoja.',
      'aromageddon':
        'Aromageddon on helsinkiläisen Aromageddon Oy:n saunatuoksusarja, jonka idea syntyi yrityksen oman kertomuksen mukaan kesällä 2024 saunassa. Valikoimaan kuuluu kuusi 15 millilitran tuoksua ja kolme lahjapakkausta, ja aiheet tulevat juomista ja makeisista: viski, olut, jääminttu, piparminttukarkki, kaneli ja minttukaakao. Yritys julkaisee omilla sivuillaan käyttöturvallisuustiedotteen jokaisesta tuoksusta, ja juoma-aiheiset versiot antavat tuoksun ilman alkoholia.',
      'leijona':
        'Leijona on Cloettan pastillibrändi, jonka tunnetuin tuote on tervan makuinen Leijona Tervalakritsi. Pastillin kehitti apteekkari Yrjö Jalander, oululaisen Merijalin perustaja, ja se tuli markkinoille vuonna 1933. Valikoimaan kuuluu nykyisin pastillien lisäksi makeispusseja, ja brändiä hallinnoi turkulainen Cloetta Suomi Oy.',
    },
  },
  de: {
    eyebrow: 'Marke',
    founded: (y) => `Gegründet ${y}`,
    officialSite: (n) => `Website von ${n}`,
    productsH2: (n) => `${n} in diesem Shop`,
    indexH1: 'Unsere Marken',
    indexIntro:
      'Wer die Dinge in diesem Shop herstellt und wo. Jedes Porträt beruht auf dem, was die Marke selbst veröffentlicht, und verlinkt auf ihre eigene Website.',
    indexCount: (n) => `${n} Produkte`,
    profile: {
      'aarikka':
        'Aarikka ist ein finnisches Designhaus, das 1954 von Kaija Aarikka und Erkki Ruokonen gegründet wurde, bekannt für Holzperlen und Schmuck und seit 2017 im Besitz von Martinex Oy. Die Marke verortet das Design und die Handmontage ihres Holzschmucks und ihrer Wohnprodukte aus Holz in Finnland, stellt ihr Sortiment aber nicht als vollständig in Finnland gefertigt dar. Bei der Kleidung werden pro Produkt ausdrücklich Herstellungsländer außerhalb Finnlands angegeben, und ein Teil der Rohstoffe stammt aus dem Ausland.',
      'foodin':
        'Foodin ist ein familiengeführtes finnisches Bio-Lebensmittelunternehmen mit Sitz in Vaajakoski, Jyväskylä, das sich selbst als Hersteller und nicht nur als Importeur beschreibt. Die Rohschokoladen-Linie wird im firmeneigenen Werk in Vaajakoski auf Steinmühlen gemahlen und von Hand fertiggestellt, der Kakao stammt von Criollo-Bohnen aus dem peruanischen Amazonasgebiet. Dasselbe Werk wird auch als Produktionsstätte für die Proteinriegel des Unternehmens genannt.',
      'kuivalihakundi':
        'Kuivalihakundi (Dried Buddy Oy) ist ein finnischer Trockenfleisch-Hersteller, der sein Fleisch im eigenen zugelassenen Fleischbetrieb in Jokela, Tuusula, trocknet, schneidet und verpackt, einer rund 1.500 m² großen Anlage, die das Unternehmen Ende 2023 bezogen hat. Der Herstellungsort ist sowohl durch die eigenen Seiten der Marke als auch durch den offiziellen Bescheid der Gemeinde über den Lebensmittelbetrieb belegt. Nach der eigenen Kennzeichnung der Marke wird das Rindfleisch in der EU aufgezogen und geschlachtet, das Rohfleisch selbst ist also nicht als finnisch bestätigt.',
      'halti':
        'Halti ist eine finnische Outdoor-Marke, die 1976 von Juhani Hyokyvaara gegründet wurde, das Design entsteht am Hauptsitz in Sipoo. Die Marke gibt auf ihrer eigenen Website an, dass sich die Produktion auf mehrere Länder verteilt: China, Vietnam und Bangladesch für technische Sportbekleidung sowie europäische Lieferanten in Italien, der Ukraine und Litauen. Nach Haltis eigener Darstellung werden nur Socken und Mützen in Finnland hergestellt, die Marke sollte daher als in Finnland entworfen und nicht als in Finnland gefertigt beschrieben werden.',
      'north-outdoor':
        'North Outdoor ist eine finnische Merinowoll-Bekleidungsmarke der Pyka Oy, am bekanntesten für die Strickerei, die sie 2021 im Stadtteil Rusko in Oulu eröffnete und die Yle als größte Wollpullover-Strickerei Finnlands bezeichnete. Die Marke verteilt die Produktion auf mehrere Länder und beschreibt diese Aufteilung nach Produktkategorien statt als eine einzige Herkunft. Ihre eigene veröffentlichte Darstellung dieser Aufteilung ist auf Englisch in sich widersprüchlich, die Aufschlüsselung nach Kategorien sollte deshalb nicht als gesicherte Tatsache wiedergegeben werden.',
      'marttiini':
        'Marttiini ist eine finnische Messermarke, die 1928 begann, als der Schmied Janne Marttiini in Rovaniemi eine Puukko-Werkstatt eröffnete. Das Sortiment reicht heute von Jagd- und Filetiermessern bis zu Küchenmessern, Klappmessern und traditionellen Puukkos, mit Griffen aus Maserbirke oder Rentiergeweih und Klingen in Lederscheiden. Der breitklingige Lapinleuku und die Filetiermesser, die die Marke in die Exportmärkte trugen, sind ihre bekanntesten Formen.',
      'kupilka':
        'Kupilka ist eine finnische Outdoor-Geschirrmarke des Familienunternehmens Plasthill Oy in Kontiolahti, Nordkarelien. Becher, Teller und Besteck werden aus dem markeneigenen Kareline-Naturfaserverbund geformt, der etwa zur Hälfte aus nordischer Nadelholzzellulose und zur Hälfte aus lebensmittelechten Polyolefinen besteht und am Standort Pyytivaara im eigenen Haus mit zertifiziertem Strom aus erneuerbaren Quellen produziert wird. Die Herkunft des Geschirrs ist von der Marke gut dokumentiert, das übrige Sortiment (insbesondere Messer und Feuerstähle) greift jedoch auf externe Lieferanten zurück.',
      'nordicbuddies':
        'Nordicbuddies ist ein finnisches Designunternehmen mit Sitz in Helsinki (eingetragen als Oy Bisly Ltd) und offizieller Lizenznehmer von Mumin, Pippi Langstrumpf und Mauri Kunnas, verkauft werden Socken, Shirts, Mützen, Taschen und weiteres Zubehör. Die Designarbeit findet in Helsinki statt, doch die eigene Über-uns-Seite der Marke verortet die Herstellung überwiegend in Europa und Eurasien mit nur einem Teil der Produktion in Finnland und die Baumwolle in den chinesischen Regionen Anhui und Henan. Die von Händlern angegebenen Herkunftsdaten weisen auf Produktebene auf China hin, die Marke sollte daher als in Finnland entworfen und nicht als in Finnland gefertigt beschrieben werden.',
      'marimekko':
        'Marimekko wurde 1951 in Finnland gegründet und betreibt weiterhin eine eigene Textildruckerei in Helsinki, die jährlich über eine Million Meter Stoff bedruckt, darunter jede als Meterware verkaufte Stoffbahn. Die fertigen Produkte selbst werden von einem Netz von Partnerlieferanten genäht, und Marimekko nennt Finnland, die baltischen Länder, Portugal, China und Thailand unter seinen Herstellungsländern. 2025 wurden 54 Prozent der Produkte in der EU und in anderen europäischen Ländern gefertigt, bei einem Marimekko-Produkt kann also ohne Prüfung des einzelnen Artikels nicht davon ausgegangen werden, dass es in Finnland hergestellt wurde.',
      'rento':
        'Rento ist eine in Finnland entworfene Sauna-Produktreihe des Familienunternehmens Tammer Brands Oy aus Tampere. Die Marke gestaltet in Finnland und trägt das Zeichen Design from Finland auf vielen Produkten, die Produktion verteilt sich jedoch auf Finnland, andere europäische Länder und nach amfori BSCI auditierte Fabriken, und das Ursprungsland wird pro Produkt und nicht pro Marke festgelegt. Mehrere als Rento verkaufte Artikel werden außerhalb Finnlands hergestellt, die Herkunft muss also Produkt für Produkt geprüft werden.',
      'lapuan-kankurit':
        'Lapuan Kankurit ist eine finnische Weberei, deren Hauptwerk in Lapua steht und deren Wurzeln bis 1917 zurückreichen. Nach eigenen Angaben webt das Unternehmen 95 % seiner Produkte in Lapua, der Rest entsteht in einer teilweise eigenen Weberei in Kaunas, Litauen, und bei europäischen Subunternehmern. Alle Rohstoffe stammen von außerhalb Finnlands: Flachs aus Frankreich, den Niederlanden und Belgien, Mohair aus Südafrika.',
      'iittala':
        'Iittala ist eine finnische Designmarke rund um die Glashütte Iittala, die 1881 im Dorf Iittala gegründet wurde und heute zur Fiskars Group gehört. Der Mutterkonzern beschreibt den Standort Hämeenlinna als die einzige noch in Finnland betriebene Glashütte mit rund 200 Beschäftigten, und Iittala gibt auf der eigenen Website an, dass die Vasen von Alvar Aalto und das Glas der Serie Ultima Thule dort mundgeblasen werden. Die Keramik wird dagegen von Auftragsfertigern im Ausland produziert, die Angabe finnischer Herkunft gilt also nur für das Glas.',
      'arctic-warriors':
        'Arctic Warriors ist ein kleines finnisches Naturproduktunternehmen mit Sitz im Dorf Narkaus bei Rovaniemi in Lappland, gegründet 2014. Es verkauft Beeren- und Kräuterpulver sowie Kräuterelixiere auf Glycerinbasis aus lappländischen Kräutern und Beeren von örtlichen Kleinbauern und Sammlern. Die eigenen Produktseiten geben als Herkunft Finnland an, nennen aber keinen Produktions- oder Verpackungsort.',
      'makia':
        'Makia ist ein 2001 gegründetes Bekleidungsunternehmen aus Helsinki, das in Finnland entwirft und im Ausland fertigen lässt. Die eigenen Seiten nennen die Türkei als wichtigstes Produktionsland, dazu Jacken und die meisten Accessoires aus China, Socken aus Portugal und der Türkei sowie einen kleinen Anteil an Wollaccessoires, der in Finnland hergestellt wird. Die eigenen Seiten der Marke widersprechen sich jedoch bei der vollständigen Länderliste, eine genaue Aufschlüsselung der Herkunft nach Kategorien lässt sich daher nicht als verifiziert angeben.',
      'pentik':
        'Pentik ist eine finnische Wohnaccessoire-Marke, die 1971 in Posio begann und dort weiterhin eine Keramikfabrik und eine angrenzende Kerzenwerkstatt betreibt. Die Fabrik deckt jedoch nicht das gesamte Sortiment ab: Nach der eigenen Nachhaltigkeitsberichterstattung der Marke wurde 2022 etwa ein Viertel der Produkte in Finnland hergestellt, der Rest wurde anderswo in Europa und in Asien bezogen. Pentik hat erklärt, dass das Herstellungsland auf den Produkten nicht hervorgehoben wird.',
      'arabia':
        'Arabia ist eine finnische Keramik- und Geschirrmarke mit Wurzeln im Helsinkier Stadtteil Arabianranta, die heute der Fiskars Group gehört. Die Keramikfabrik in Helsinki stellte die Produktion im Frühjahr 2016 ein, und Fiskars gibt auf den eigenen Markenseiten an, dass Arabia-Produkte nun von langjährigen Auftragsfertigern stammen, vor allem in Thailand und Rumänien. Design und Produktentwicklung finden weiterhin in Finnland statt, und das Arabia-Viertel in Helsinki besteht als Museum, Geschäft und Designzentrum fort.',
      'fazer':
        'Fazer ist ein finnisches Lebensmittelunternehmen, das 1891 in Helsinki gegründet wurde und vor allem für die Milchschokolade Karl Fazer sowie für Geisha und Marianne bekannt ist. Über Süßwaren hinaus betreibt der Konzern in mehreren Ländern Bäckerei-, Mühlen- und Restaurantgeschäfte. Die Produktionsstruktur verändert sich derzeit: In Lahti entsteht eine neue Schokoladenfabrik, und im Sommer 2026 kaufte Fazer Süßwarenfabriken in Schweden.',
      'moomin':
        'Moomin Characters Oy Ltd ist das Helsinkier Familienunternehmen, das die Rechte an Tove Janssons Mumin-Figuren besitzt und verwaltet. Die Figuren erschienen erstmals 1945 im Buch The Moomins and the Great Flood. Das Unternehmen stellt seit Jahrzehnten selbst keine Waren mehr her: Jeder als Mumin-Produkt verkaufte Artikel stammt von einem Lizenznehmer, und das Netz umfasst weltweit mehr als 800 davon. Im Geschenkbereich ist die bekannteste Linie Arabias Mumin-Keramikbecher, eine Serie, die 1990 begann und heute über hundert Designs umfasst.',
      'wild-about-lapland':
        'Wild About Lapland ist ein Aktivitätenanbieter mit Sitz in Rovaniemi, dessen Büro sich an der Rovakatu 24 befindet. Jede Tour ist auf acht Teilnehmer begrenzt, und das Programm läuft ganzjährig: Nordlichtfahrten, Schneemobilsafaris sowie Besuche bei Rentieren und Huskys im Winter, Kanufahren und Wandern im Sommer. Gründer und leitender Guide Theo Turner ist ehemaliger Kommandosoldat der Royal Marines und Outdoor-Ausbilder, und das Unternehmen trägt das Label Sustainable Travel Finland.',
      'meritalo':
        'Meritalo ist ein finnischer Familienbetrieb der Beerenverarbeitung, gegründet 1995 von Susanna und Olavi Lindstedt, die von Helsinki nach Ylönkylä in der Gegend von Salo in Südwestfinnland zogen. Das Unternehmen gibt an, dass alle seine Produkte dort in den eigenen Räumlichkeiten hergestellt werden, aus 100 % finnischen Beeren und Früchten, die von finnischen Erzeugern gekauft und in finnischen Wäldern gepflückt werden. Das Sortiment ist um Marmeladen und Gelees, Säfte und Birkensaft herum aufgebaut und umfasst eine 310-g-Sanddornmarmelade neben Produkten aus Erdbeere, Preiselbeere und Apfel.',
      'nordqvist':
        'Nordqvist ist ein finnisches Teeunternehmen, gegründet 1979, das als Geschäft in Helsinki mit aromatisierten und losen Tees begann und später in Import und Großhandel einstieg. Seine Tees werden in der 3.000 Quadratmeter großen unternehmenseigenen Fabrik in Nurmijärvi aromatisiert und abgepackt, die 2018 eröffnet wurde. Das Sortiment umfasst langjährige Mischungen wie Keisarin Morsian und Tiikerin Päiväuni sowie eine Teelinie mit Mumin-Motiven, die als Beutel, loser Tee und in Dosen verkauft wird.',
      'puhdistamo':
        'Puhdistamo ist eine finnische Wellnessmarke, gegründet 2009, die Vitamine, Mineralstoffe und andere Nahrungsergänzungsmittel sowie Energydrinks, Kombucha, Protein- und Rohschokoladenriegel und Superfoods verkauft. Das Unternehmen betreibt eine eigene Fabrik in Lempäälä in Finnland, wo es die meisten seiner Nahrungsergänzungsmittel herstellt und nach eigenen Angaben in einem einzigen Jahr über 80 Millionen Kapseln produziert hat. Das Werk ist nach dem Lebensmittelsicherheitsstandard FSSC 22000 zertifiziert, und das Unternehmen gibt an, dass seine Getränke mit Stevia oder Bio-Rohrzucker statt mit Aspartam, Acesulfam K oder Sucralose gesüßt werden.',
      'emendo':
        'Emendo Oy ist ein finnisches Sauna- und Wellnessunternehmen mit Sitz in Vaasa, das auf seiner eigenen Website angibt, 1986 gegründet worden zu sein. Das Sortiment umfasst Sauna- und Löylydüfte, Saunahonige, Saunatextilien aus Leinen und Baumwolle, Kellen, Seifen und Hautpflegeprodukte, verkauft unter zwei Namen, Emendo und KOLO Sauna. Das Unternehmen gibt an, seine Düfte, Saunahonige sowie Gesichts-, Körper- und Fußpflegeprodukte in Finnland herzustellen, und seine Mumin-Saunaartikel sind von Moomin Characters lizenziert und beruhen auf Tove Janssons Originalzeichnungen.',
      'moomin-arabia':
        'Moomin Arabia ist die Mumin-Serie der finnischen Keramikmarke Arabia, die 1873 gegründet wurde und heute zur Fiskars Group gehört. Das erste Mumin-Geschirr erschien in den 1950er-Jahren mit Illustrationen von Tove Jansson, und die vielfach gesammelte Becherserie begann in den 1990er-Jahren auf Basis der Teema-Form von Kaj Franck. Die Designarbeit erfolgt am Unternehmenssitz in Espoo in Finnland, während die Fiskars Group angibt, dass Arabia-Produkte von Auftragsfertigern vor allem in Thailand und Rumänien hergestellt werden.',
      'kaino-drinks':
        'KAINO Drinks ist eine Serie alkoholfreier prickelnder Getränke von Poikain Parhaat Oy, einem Lebensmittelunternehmen mit Sitz in Tampere in Finnland. Das Fichtensprossengetränk wird in Tampere von Hand aus finnischen Fichtensprossen hergestellt, und die Getränke haben 0,0 % Alkohol, sind vegan und nach FI-EKO-201 bio-zertifiziert. Das Sortiment umfasst Fichtensprosse, Rhabarber und Rose sowie Blatt der schwarzen Johannisbeere, verkauft in Flaschen zu 0,75 Liter und 0,2 Liter.',
      'omega7':
        'Omega7 ist eine finnische Marke für Sanddornöl-Nahrungsergänzung, deren erste Produkte 1997 auf den Markt kamen. Das doppelte Sanddornöl SBA24 kombiniert Beerenöl und Kernöl und wird in einem lösungsmittelfreien Verfahren in der unternehmenseigenen Fabrik in Tornio gewonnen. Der Hersteller Aromtech Oy hat klinische Studien mit Forschern und Ärzten der Universität Turku und des Universitätsklinikums Turku durchgeführt und betreibt ein Pilotprojekt zum ökologischen Sanddornanbau in Tervola in Lappland.',
      'kaapa-mushrooms':
        'KÄÄPÄ Mushrooms ist ein finnischer Hersteller funktioneller Pilze, gegründet 2018 von Eric Puro, Otso Mursula und Seppo Riikonen. Hauptsitz und Produktionsstätte liegen in Karjalohja in Südfinnland, wo die Pilze auf Birkensubstrat aus FSC- und PEFC-zertifizierten finnischen Wäldern gezüchtet und mit der unternehmenseigenen Ultraschallmethode NordRelease unter Verwendung von gereinigtem Quellwasser extrahiert werden. Das Unternehmen ist nach dem Lebensmittelsicherheitsstandard FSSC 22000 zertifiziert, stellt seine Extrakte aus Fruchtkörpern statt aus myzeldurchwachsenem Getreide her und betreibt über seine Sparte KÄÄPÄ Forest ein Netzwerk für den Chaga-Anbau im Wald.',
      'halva':
        'Halva ist ein finnisches Familienunternehmen der Süßwarenbranche, gegründet 1931 von den Brüdern Jean und Michael Karavokyros, die aus Griechenland nach Finnland gezogen waren. Bekannt ist es vor allem für Lakritz- und Salmiakki-Süßigkeiten, und das Unternehmen gibt an, dass seine Bonbonfabrik und seine Verpackungsanlage in Pitäjänmäki in Helsinki liegen. Das Geschäft wird inzwischen von der dritten Generation geführt, und die Sesampaste Halva, die dem Unternehmen den Namen gab, ist weiterhin im Sortiment.',
      'kilpissafarit':
        'Kilpissafarit ist ein Programmdienstleister in Kilpisjärvi, gegründet 1995 von dem Grenzschützer Hannu Rauhala und heute von seinem Sohn Jussi Rauhala geführt. Das Unternehmen führt Schneemobilsafaris, Schneeschuh- und Wandertouren, Nordlichtausflüge und Angeltouren in der Wildnis von Käsivarsi, darunter eine Schneemobilroute zum Halti, dem höchsten Punkt Finnlands. Von derselben Basis aus werden Schneemobile, elektrische Fatbikes, Schneeschuhe, Kanus und Kajaks an alle vermietet, die auf eigene Faust unterwegs sind.',
      'kaavi-porcini':
        'Kaavi Porcini ist die Marke von Kaavin Herkkutattitehdas Oy, einem finnischen Unternehmen, das Wildpilze aus dem Wald in einer eigenen Fabrik in Tohmajärvi trocknet. Die Pilze werden in den Wäldern von Nordsavo und Nordkarelien gesammelt und noch am Tag der Ernte getrocknet. Das Sortiment umfasst Steinpilz, Pfifferling, Trompetenpfifferling und Herbsttrompete sowie in Kittilä gesammelten Chaga und ein Steinpilzpulver, das als Würze verwendet wird.',
      'tammer':
        'Tammer Brands ist ein Familienunternehmen aus Tampere, gegründet 1954 als Tammer-Tukku und 2019 in Tammer Brands Oy umbenannt. Es entwickelt und vertreibt Konsumgüter für Haus, Garten und Freizeit unter einem Portfolio von mehr als 50 Marken, darunter die Saunaserie Rento, die Grillmarke Mustang und Maku Kitchen Life. Für Rento gibt das Unternehmen an, dass die Produkte in Finnland, anderswo in Europa oder in nach amfori BSCI auditierten Fabriken hergestellt werden, wobei das Herstellungsland auf jeder Produktkarte angegeben ist.',
      'finlayson':
        'Finlayson führt seinen Anfang auf das Jahr 1820 zurück, als der Schotte James Finlayson an den Stromschnellen von Tammerkoski in Tampere eine Maschinenwerkstatt einrichtete. Die daraus gewachsene Baumwollspinnerei war 1975 mit 11 Fabriken und 6.500 Beschäftigten Finnlands größter privater Arbeitgeber, und das Unternehmen ist weiterhin für Namen wie das Muster Elefantti bekannt, das Laina Koskela 1969 entwarf, sowie dafür, den Bettbezug 1963 auf den finnischen Markt gebracht zu haben. Heute verkauft Finlayson Bettwäsche, Handtücher, Küchentextilien und Teppiche, veröffentlicht seine Fabrikliste und webt seine Rasypala-Teppiche in Finnland aus Laken, die Kunden zurückgegeben haben.',
      'finnish-flavours':
        'Finnish Flavours ist eine finnische Lebensmittelmarke, die von Kerava aus geführt wird. Das Sortiment konzentriert sich auf Lakritz in zwei Linien, Premium Palalaku als Stücke und schokoladenüberzogenes Premium Chocolaku, daneben auf Preiselbeer-, Blaubeer- und Moltebeermarmeladen, finnische Regenbogenforelle und getrocknetes Rentierfleisch. Die Marke gibt an, dass ihre Marmeladen in Finnland und vollständig aus einheimischen Beeren hergestellt werden, und ihre gelisteten Händler reichen von finnischen K-Märkten und einem Geschäft in Rovaniemi bis zu Importeuren in den Vereinigten Staaten, Kanada, der Schweiz, dem Vereinigten Königreich und Neuseeland.',
      'aurora-borealis':
        'Aurora Borealis ist eine Eigenmarke von Tammer Brands Oy, einem familiengeführten finnischen Marken- und Großhandelsunternehmen mit Hauptsitz in Tampere, dessen Wurzeln bis 1954 zurückreichen. Das Sortiment umfasst Dekorationsstücke, Alltagsartikel, Accessoires und Fahnen rund um Motive der finnischen Natur: Wälder, Rentiere, Huskys, Nordlichter und die finnische Flagge. Zu den unter diesem Namen geführten Produkten gehören hölzerne Kuksa-Becher, Plüschrentiere und Plüschhuskys, Tassen, Stofftaschen und Spielkarten.',
      'fiskars':
        'Fiskars begann 1649, als Peter Thorwöste die Erlaubnis erhielt, in einem gleichnamigen finnischen Dorf einen Hochofen und eine Schmiede einzurichten. Bekannt ist die Marke vor allem für ihre Scheren mit orangefarbenem Griff, die 1967 als erste Scheren mit Kunststoffgriffen auf den Markt kamen; das Modell Classic wird weiterhin in der unternehmenseigenen Fabrik in Billnäs in Finnland gefertigt, und jede Schere wird von Hand geprüft. Neben Scheren verkauft Fiskars Gartengeräte, Äxte und Küchenmesser.',
      'arctic-power-berries':
        'Arctic Power Berries ist eine Marke für Beerenpulver, geführt von Anna und Eveliina, zwei Jugendfreundinnen aus Rovaniemi im finnischen Lappland, die das Geschäft nach ihrem Umzug nach London gründeten. Das Sortiment besteht aus Pulvern einzelner Beeren in 70-g-Beuteln: Blaubeere (Heidelbeere), Preiselbeere, Sanddorn, schwarze Johannisbeere, Cranberry, Erdbeere und Himbeere, dazu eine gemischte Beerenmischung. Das Unternehmen gibt an, dass die Wildbeeren in Finnland von Hand gepflückt, schonend getrocknet und gemahlen werden, wobei hinter jedem 70-g-Beutel rund 700 g frische Beeren stehen und nichts weiter zugesetzt wird.',
      'golden-crown-levin-iglut':
        'Levin Iglut Golden Crown ist ein familiengeführtes Glasiglu-Resort auf dem Fjell Utsuvaara neben Levi im finnischen Lappland. Tauno Mäkelä baute 2008 die ersten vier Iglus, und die Anlage hat heute 27 Glasiglus, die Villa Northern Lights House für sechs Personen und ein eigenes Restaurant Utsu, geöffnet von Ende August bis Anfang April. Für Geschenkkäufer sind vor allem die Gutscheine für Iglu-Aufenthalte und Abendessen im Utsu relevant sowie der Golden Crown Shop an der Rezeption, der finnische Design- und Handwerksmarken führt.',
      'sisu':
        'Sisu ist eine finnische Pastillenmarke, die 1928 eingeführt wurde. Das Rezept wurde vom Chemiker Johan Ponkamo im Keller der Süßwarenfabrik Seres in Turku entwickelt, und die Pastille beruht auf einer Basis aus Gummi arabicum mit Salmiakki-Geschmack. Die Marke gehört heute zum Portfolio von Cloetta und umfasst Salmiakki-, Menthol- und Lakritzpastillen, zuckerfreie Varianten und Varianten mit Xylit sowie seit 2022 auch Bonbontüten.',
      'kultakuume-com':
        'Kultakuume ist ein Familienbetrieb in Saariselkä im finnischen Lappland, der nach eigenen Angaben seit 2008 in der Gegend tätig ist und seit 2009 Hütten vermietet. Er verkauft geführte Goldwaschtage auf dem eigenen Claim, bei denen den Besuchern das Waschen von Hand beigebracht wird, sie das maschinelle Waschen verfolgen und alles gefundene Gold behalten. Neben den Touren vermietet er die Blockhütten Kultakelo auf dem Kaunispää und verkauft eine Serie von 18 Leinwanddrucken zu Goldwaschmotiven, jeweils 100 x 100 cm.',
      'muurla':
        'Muurla ist ein finnisches Designunternehmen, dessen Geschichte in einer Glasfabrik in Muurla in Südwestfinnland begann, wo der Fabrikladen im Frühjahr 1974 eröffnete. Bekannt ist es heute für Emaillebecher und Emaillegeschirr, Glaswaren und Servierbretter aus Birkenfurnier sowie für seine lizenzierte Mumin-Kollektion. Muurla gibt an, dass alle seine Produkte in Finnland gestaltet werden, während das Herstellungsland je nach Produkt variiert: Artikel aus Birkenfurnier werden in Finnland gefertigt, das meiste Emaillegeschirr in Europa und Glas sowohl in Europa als auch in Asien.',
      'novita':
        'Novita ist ein finnisches Garnunternehmen, gegründet 1928 von Ernst Gylfe, der das Spinnen von Kammgarn im englischen Bradford erlernte, bevor er die Produktion in Helsinki aufnahm. Das Unternehmen ist weiterhin in vierter Generation in Familienbesitz und betreibt seit 1974 seine Spinnerei in Koria in Kouvola, wo es nach eigenen Angaben etwa eine Million Kilo Garn pro Jahr herstellt. Sein bekanntestes Produkt ist das Sockengarn 7 Veljestä, gesponnen aus Wolle, die das Unternehmen nach eigenen Angaben überwiegend aus Europa und vor allem aus England bezieht.',
      'mikebon':
        'Mikebon Oy ist ein familiengeführtes Unternehmen für Textildruck und Stickerei, gegründet 1994 und ansässig in Petikko in Vantaa. Es übernimmt Design, grafische Umsetzung, Produktion und Logistik selbst und gibt auf seiner eigenen Website an, dass die Produktion in Finnland stattfindet. Seine Hauptkunden sind Souvenir- und Geschenkhändler, und es betreibt außerdem einen Webshop für Verbraucher, dessen Sortiment Shirts und Hoodies mit Lappland-, Finnland- und Mumin-Motiven umfasst.',
      'aromageddon':
        'Aromageddon ist eine Saunaduftserie von Aromageddon Oy, einem in Helsinki registrierten Unternehmen, das die Idee auf einen Saunagang im Sommer 2024 datiert. Die Linie umfasst sechs Düfte zu je 15 ml für 7,90 Euro pro Stück sowie drei Geschenksets, und die Themen stammen aus Getränken und Süßigkeiten statt aus Wald oder Birke: Whisky, Bier, Eisminze, Pfefferminzbonbon, Zimt und Minzkakao. Das Unternehmen veröffentlicht auf seiner eigenen Website für jeden Duft ein CLP-Sicherheitsdatenblatt, und die getränkeinspirierten Varianten tragen die Geschmacksnote ohne Alkohol.',
      'leijona':
        'Leijona ist eine finnische Pastillenmarke im Besitz von Cloetta, am bekanntesten für Leijona Tervalakritsi, eine zuckerüberzogene Lakritzpastille mit Teergeschmack. Sie wurde von dem Apotheker Yrjö Jalander entwickelt, dem Gründer des Süßwarenunternehmens Merijal aus Oulu, und kam 1933 auf den Markt. Neben den Pastillendosen mit 32 g umfasst das aktuelle Sortiment Bonbontüten mit 180 g, und die Marke wird von der Cloetta Suomi Oy aus Turku geführt.',
    },
  },
  sv: {
    eyebrow: 'Varumärke',
    founded: (y) => `Grundat ${y}`,
    officialSite: (n) => `${n}s egen webbplats`,
    productsH2: (n) => `${n} i den här butiken`,
    indexH1: 'Våra varumärken',
    indexIntro:
      'Vem som tillverkar sakerna i den här butiken och var. Varje presentation bygger på vad varumärket själv publicerar och länkar till deras egen webbplats.',
    indexCount: (n) => `${n} produkter`,
    profile: {
      'aarikka':
        'Aarikka är ett finländskt designhus som grundades 1954 av Kaija Aarikka och Erkki Ruokonen, känt för träpärlor och smycken, och som ägs av Martinex Oy sedan 2017. Varumärket uppger att designen och handmonteringen av träsmyckena och trävarorna för hemmet sker i Finland, men det framställer inte sortimentet som helt tillverkat i Finland. För kläderna anges tillverkningsland uttryckligen per produkt, och de ligger utanför Finland; en del råvaror köps också in utomlands.',
      'foodin':
        'Foodin är ett familjeägt finländskt ekologiskt livsmedelsföretag med bas i Vaajakoski i Jyväskylä, som beskriver sig som tillverkare och inte enbart importör. Företagets råchokladserie stenmals och handbearbetas i den egna fabriken i Vaajakoski, och kakaon kommer från Criollo-bönor odlade i den peruanska Amazonas. Samma fabrik anges också som produktionsplats för företagets proteinbarer.',
      'kuivalihakundi':
        'Kuivalihakundi (Dried Buddy Oy) är en finländsk tillverkare av torkat kött som torkar, skär och packar sitt kött i den egna godkända köttanläggningen i Jokela i Tusby, en lokal på cirka 1 500 m2 dit företaget flyttade i slutet av 2023. Tillverkningsorten bekräftas både av varumärkets egna sidor och av kommunens officiella beslut om livsmedelslokalen. Enligt varumärkets egen märkning är nötköttet uppfött och slaktat inom EU, så själva råköttet är inte bekräftat finländskt.',
      'halti':
        'Halti är ett finländskt friluftsvarumärke som grundades 1976 av Juhani Hyokyvaara, och designen görs vid huvudkontoret i Sibbo. Varumärket uppger på sin egen webbplats att produktionen är spridd över flera länder: Kina, Vietnam och Bangladesh för tekniska sportkläder, plus europeiska leverantörer i Italien, Ukraina och Litauen. Enligt Haltis egen uppgift tillverkas endast strumpor och mössor i Finland, så varumärket bör beskrivas som finländskt designat snarare än finländskt tillverkat.',
      'north-outdoor':
        'North Outdoor är ett finländskt klädmärke i merinoull som drivs av Pyka Oy och som är mest känt för den stickerifabrik det öppnade i stadsdelen Rusko i Uleåborg 2021, av Yle beskriven som Finlands största fabrik för ylletröjor. Varumärket fördelar produktionen på flera länder och beskriver fördelningen per produktkategori i stället för som ett enda ursprung. Dess egen publicerade beskrivning av fördelningen är motstridig på engelska, så uppdelningen per kategori bör inte upprepas som fastslagen fakta.',
      'marttiini':
        'Marttiini är ett finländskt knivmärke som startade 1928, när smeden Janne Marttiini öppnade en puukkoverkstad i Rovaniemi. Sortimentet omfattar i dag allt från jakt- och filékniver till kökskniver, fällkniver och traditionella puukkokniver, med skaft i masurbjörk eller renhorn och blad som bärs i läderslidor. Den bredbladiga Lapinleuku och filékniverna som förde varumärket ut på exportmarknaderna är dess mest igenkännbara former.',
      'kupilka':
        'Kupilka är ett finländskt varumärke för friluftsservis som drivs av familjeföretaget Plasthill Oy i Kontiolahti i Norra Karelen. Muggarna, tallrikarna och besticken formgjuts av den egna naturfiberkompositen Kareline, som består av ungefär hälften nordisk barrvedscellulosa och hälften livsmedelsgodkända polyolefiner, och tillverkas i egen regi vid anläggningen i Pyytivaara med certifierad förnybar el. Servisens ursprung är väl dokumenterat av varumärket, men det bredare sortimentet (särskilt knivar och eldstål) bygger på utomstående leverantörer.',
      'nordicbuddies':
        'Nordicbuddies är ett finländskt designföretag i Helsingfors (registrerat som Oy Bisly Ltd) och officiell licenstagare för Mumin, Pippi Långstrump och Mauri Kunnas, med försäljning av strumpor, tröjor, kepsar, väskor och andra accessoarer. Designarbetet görs i Helsingfors, men varumärkets egen Om oss-sida placerar tillverkningen huvudsakligen i Europa och Eurasien med endast en del av produktionen i Finland, och bomullen i regionerna Anhui och Henan i Kina. Återförsäljarnas uppgivna ursprungsdata pekar på Kina på produktnivå, så varumärket bör beskrivas som finländskt designat, inte finländskt tillverkat.',
      'marimekko':
        'Marimekko grundades i Finland 1951 och driver fortfarande sin egen textiltryckerifabrik i Helsingfors, som trycker över en miljon meter tyg per år, inklusive alla tyger som säljs i metervara. Själva de färdiga produkterna sys av ett nätverk av samarbetsleverantörer, och Marimekko nämner Finland, Baltikum, Portugal, Kina och Thailand bland sina tillverkningsländer. År 2025 tillverkades 54 procent av produkterna inom EU och andra europeiska länder, så en Marimekko-produkt kan inte antas vara tillverkad i Finland utan att den enskilda varan kontrolleras.',
      'rento':
        'Rento är ett finländskt designat bastusortiment som ägs av familjeföretaget Tammer Brands Oy i Tammerfors. Varumärket designar i Finland och bär märket Design from Finland på en stor del av sortimentet, men produktionen är fördelad på Finland, andra europeiska länder och fabriker som granskats enligt Amfori BSCI, och ursprungslandet avgörs per produkt i stället för per varumärke. Flera varor som säljs som Rento tillverkas utanför Finland, så ursprunget måste kontrolleras produkt för produkt.',
      'lapuan-kankurit':
        'Lapuan Kankurit är ett finländskt väveriföretag vars huvudväveri ligger i Lappo och vars rötter går tillbaka till 1917. Enligt egen uppgift väver företaget 95 % av sina produkter i Lappo, medan resten tillverkas vid ett delägt väveri i Kaunas i Litauen och av europeiska underleverantörer. Alla råvaror har sitt ursprung utanför Finland: lin från Frankrike, Nederländerna och Belgien, mohair från Sydafrika.',
      'iittala':
        'Iittala är ett finländskt designvarumärke som byggts kring glasbruket i Iittala, grundat 1881 i byn Iittala och i dag en del av Fiskars Group. Moderbolaget beskriver anläggningen i Tavastehus som det enda glasbruk som fortfarande är i drift i Finland, med omkring 200 anställda, och Iittala uppger på sin egen webbplats att Alvar Aalto-vaserna och Ultima Thule-glasen munblåses där. Keramiken tillverkas däremot av kontraktstillverkare utomlands, så påståendet om finländskt ursprung gäller endast glasprodukterna.',
      'arctic-warriors':
        'Arctic Warriors är ett litet finländskt naturproduktföretag som är registrerat i byn Narkaus nära Rovaniemi i Lappland och grundades 2014. Det säljer bär- och örtpulver samt glycerolbaserade örtelixir gjorda på lappländska örter och bär som köps in av lokala småbrukare och plockare. Företagets egna produktsidor anger Finland som ursprung men uppger ingen produktions- eller packningsort.',
      'makia':
        'Makia är ett klädföretag i Helsingfors som grundades 2001, designar i Finland och tillverkar utomlands. Företagets egna sidor anger Turkiet som huvudsakligt produktionsland, med jackor och de flesta accessoarer från Kina, strumpor från Portugal och Turkiet och en liten andel ylleaccessoarer tillverkade i Finland. Varumärkets egna sidor motsäger dock varandra om den fullständiga landslistan, så ingen exakt ursprungsfördelning per kategori kan anges som verifierad.',
      'pentik':
        'Pentik är ett finländskt varumärke för heminredning som startade i Posio 1971 och fortfarande driver en keramikfabrik och en intilliggande ljusverkstad där. Fabriken täcker dock inte hela sortimentet: enligt varumärkets egen hållbarhetsrapportering tillverkades ungefär en fjärdedel av produkterna i Finland 2022, medan resten köptes in på annat håll i Europa och Asien. Pentik har uppgett att företaget inte lyfter fram tillverkningsland på sina produkter.',
      'arabia':
        'Arabia är ett finländskt varumärke för keramik och bordsservis med rötter i stadsdelen Arabiastranden i Helsingfors och ägs i dag av Fiskars Group. Keramikfabriken i Helsingfors upphörde med produktionen våren 2016, och Fiskars uppger på sina egna varumärkessidor att Arabia-produkterna nu kommer från långvariga kontraktstillverkare, huvudsakligen i Thailand och Rumänien. Design och produktutveckling sker fortfarande i Finland, och Arabiakvarteret i Helsingfors fortsätter som museum, butik och designcenter.',
      'fazer':
        'Fazer är ett finländskt livsmedelsföretag som grundades i Helsingfors 1891 och är mest känt för mjölkchokladen Karl Fazer, Geisha och Marianne. Utöver konfektyr driver koncernen bageri-, kvarn- och restaurangverksamhet i flera länder. Produktionsstrukturen är i förändring just nu: en ny chokladfabrik byggs i Lahtis, och sommaren 2026 köpte Fazer konfektyrfabriker i Sverige.',
      'moomin':
        'Moomin Characters Oy Ltd är det familjeföretag i Helsingfors som äger och övervakar rättigheterna till Tove Janssons muminfigurer, som först dök upp i boken Småtrollen och den stora översvämningen från 1945. Företaget slutade själv tillverka varor för decennier sedan: varje vara som säljs som en muminprodukt kommer från en licenstagare, och nätverket omfattar över 800 av dem världen över. På presentsidan är den mest igenkännbara serien Arabias muminmuggar i keramik, en serie som startade 1990 och i dag omfattar över hundra motiv.',
      'wild-about-lapland':
        'Wild About Lapland är en aktivitetsarrangör med bas i Rovaniemi, med kontor på Rovakatu 24. Varje tur har högst åtta deltagare, och programmet pågår året runt: norrskensturer, snöskotersafarier och besök hos renar och huskyhundar på vintern, kanotpaddling och vandring på sommaren. Grundaren och huvudguiden Theo Turner är tidigare kommandosoldat i Royal Marines och friluftsinstruktör, och företaget bär märkningen Sustainable Travel Finland.',
      'meritalo':
        'Meritalo är en finländsk familjeägd bärförädlare som grundades 1995 av Susanna och Olavi Lindstedt, som flyttade från Helsingfors till Ylönkylä i Salotrakten i sydvästra Finland. Företaget uppger att alla dess produkter tillverkas i de egna lokalerna där, av 100 % finländska bär och frukter som köps av finländska odlare och plockas i finländska skogar. Sortimentet bygger på sylt och gelé, saft och björksav, och omfattar en havtornssylt på 310 g vid sidan av produkter av jordgubbe, lingon och äpple.',
      'nordqvist':
        'Nordqvist är ett finländskt teföretag som grundades 1979 och som började som en butik i Helsingfors med smaksatt te och te i lösvikt, och som senare gick in i import och partihandel. Teerna smaksätts och packas i företagets egen fabrik på 3 000 kvadratmeter i Nurmijärvi, som öppnade 2018. Sortimentet omfattar långlivade blandningar som Keisarin Morsian och Tiikerin Päiväuni vid sidan av en teserie med mumintema som säljs i påsar, som lösvikt och i burkar.',
      'puhdistamo':
        'Puhdistamo är ett finländskt wellnessvarumärke som grundades 2009 och som säljer vitaminer, mineraler och andra kosttillskott vid sidan av energidrycker, kombucha, protein- och rawchokladbitar samt superfoods. Företaget driver en egen fabrik i Lempäälä i Finland, där det tillverkar största delen av sina kosttillskott och uppger sig producera över 80 miljoner kapslar på ett år. Anläggningen har livsmedelssäkerhetscertifikatet FSSC 22000, och företaget uppger att dess drycker sötas med stevia eller ekologiskt rörsocker i stället för aspartam, acesulfam K eller sukralos.',
      'emendo':
        'Emendo Oy är ett finländskt bastu- och wellnessföretag med bas i Vasa, som på sin egen webbplats uppger att det grundades 1986. Sortimentet omfattar bastu- och löylydofter, bastuhonung, bastutextilier i lin och bomull, badskopor, tvålar och hudvårdsprodukter, som säljs under två namn, Emendo och KOLO Sauna. Företaget uppger att det tillverkar sina dofter, bastuhonungar och ansikts-, kropps- och fotvårdsprodukter i Finland, och dess muminbastuprodukter är licensierade av Moomin Characters och bygger på Tove Janssons originalteckningar.',
      'moomin-arabia':
        'Moomin Arabia är muminsortimentet från det finländska keramikvarumärket Arabia, som grundades 1873 och i dag ingår i Fiskars Group. De första muminserviserna kom på 1950-talet med illustrationer av Tove Jansson, och den flitigt samlade muggserien inleddes på 1990-talet med Kaj Francks Teema-form. Formgivningen görs vid företagets huvudkontor i Esbo i Finland, medan Fiskars Group uppger att Arabias produkter tillverkas av kontraktstillverkare huvudsakligen i Thailand och Rumänien.',
      'kaino-drinks':
        'KAINO Drinks är ett sortiment alkoholfria mousserande drycker från Poikain Parhaat Oy, ett livsmedelsföretag med bas i Tammerfors i Finland. Drycken av granskott tillverkas för hand i Tammerfors av finländska granskott, och dryckerna är 0,0 % alkohol, veganska och ekologiskt certifierade under FI-EKO-201. Sortimentet omfattar granskott, rabarber och ros samt svartvinbärsblad, och säljs i flaskor på 0,75 liter och 0,2 liter.',
      'omega7':
        'Omega7 är ett finländskt varumärke för kosttillskott av havtornsolja vars första produkter kom ut på marknaden 1997. Dess dubbla havtornsolja SBA24 kombinerar bärolja och fröolja, och den utvinns med en lösningsmedelsfri process i företagets fabrik i Torneå. Tillverkaren Aromtech Oy har gjort kliniska studier tillsammans med forskare och läkare från Åbo universitet och Åbo universitetscentralsjukhus, och företaget driver ett pilotprojekt med ekologisk havtornsodling i Tervola i Lappland.',
      'kaapa-mushrooms':
        'KÄÄPÄ Mushrooms är en finländsk producent av funktionella svampar som grundades 2018 av Eric Puro, Otso Mursula och Seppo Riikonen. Huvudkontoret och produktionsanläggningen ligger i Karjalohja i södra Finland, där svamparna odlas på björksubstrat från FSC- och PEFC-certifierade finländska skogar och extraheras med företagets egen ultraljudsmetod NordRelease med renat källvatten. Företaget har livsmedelssäkerhetscertifikatet FSSC 22000, gör sina extrakt av fruktkroppar i stället för mycelodlad spannmål och driver ett nätverk för odling av sprängticka i skog genom sin division KÄÄPÄ Forest.',
      'halva':
        'Halva är ett finländskt familjeägt konfektyrföretag som grundades 1931 av bröderna Jean och Michael Karavokyros, som hade flyttat till Finland från Grekland. Det är mest känt för lakrits- och salmiakgodis, och företaget uppger att dess godisfabrik och packeri ligger i Pitäjänmäki i Helsingfors. Verksamheten drivs nu av tredje generationen, och sesampastan halva som gav företaget dess namn finns fortfarande i sortimentet.',
      'kilpissafarit':
        'Kilpissafarit är ett programserviceföretag i Kilpisjärvi som grundades 1995 av gränsbevakaren Hannu Rauhala och som nu drivs av hans son Jussi Rauhala. Det guidar snöskotersafarier, snösko- och vandringsturer, norrskensutflykter och fisketurer i Käsivarsi ödemark, bland annat en snöskoterrutt till Halti, Finlands högsta punkt. Från samma bas hyrs snöskotrar, elektriska fatbikes, snöskor, kanoter och kajaker ut till dem som ger sig ut på egen hand.',
      'kaavi-porcini':
        'Kaavi Porcini är varumärket för Kaavin Herkkutattitehdas Oy, ett finländskt företag som torkar vilda skogssvampar i sin egen fabrik i Tohmajärvi. Svamparna plockas i skogarna i Norra Savolax och Norra Karelen och torkas samma dag som de plockas. Sortimentet omfattar stensopp, kantarell, trattkantarell och svart trumpetsvamp, plus sprängticka som samlas i Kittilä och ett stensoppspulver som används som krydda.',
      'tammer':
        'Tammer Brands är ett familjeägt företag från Tammerfors som grundades 1954 som Tammer-Tukku och bytte namn till Tammer Brands Oy 2019. Det utvecklar och distribuerar konsumentprodukter för hem, trädgård och fritid under en portfölj på över 50 varumärken, bland dem bastuserien Rento, grillvarumärket Mustang och Maku Kitchen Life. För Rento uppger företaget att produkterna tillverkas i Finland, någon annanstans i Europa eller i fabriker som granskats enligt amfori BSCI, och att tillverkningslandet anges på varje produktkort.',
      'finlayson':
        'Finlayson räknar sin början till 1820, då skotten James Finlayson grundade en mekanisk verkstad vid forsen Tammerkoski i Tammerfors. Bomullsfabriken som växte fram kring den blev 1975 Finlands största privata arbetsgivare, med 11 fabriker och 6 500 anställda, och företaget är fortfarande känt för namn som mönstret Elefantti som Laina Koskela formgav 1969 och för att ha fört ut påslakanet på den finländska marknaden 1963. I dag säljer Finlayson sängkläder, handdukar, kökstextilier och mattor, publicerar sin fabrikslista och väver sina Rasypala-mattor i Finland av lakan som kunderna lämnat tillbaka.',
      'finnish-flavours':
        'Finnish Flavours är ett finländskt livsmedelsvarumärke som drivs från Kervo. Sortimentet bygger på lakrits i två serier, Premium Palalaku-bitar och chokladdoppad Premium Chocolaku, vid sidan av sylt av lingon, blåbär och hjortron, finländsk regnbågslax och torkat renkött. Varumärket uppger att dess sylt tillverkas i Finland helt av inhemska bär, och de återförsäljare som listas sträcker sig från finländska K-butiker och en butik i Rovaniemi till importörer i USA, Kanada, Schweiz, Storbritannien och Nya Zeeland.',
      'aurora-borealis':
        'Aurora Borealis är ett eget varumärke från Tammer Brands Oy, ett familjeägt finländskt varumärkes- och partihandelsföretag med huvudkontor i Tammerfors vars rötter går tillbaka till 1954. Sortimentet omfattar dekorationsföremål, vardagsartiklar, accessoarer och flaggor byggda kring motiv från den finländska naturen: skogar, renar, huskyhundar, norrsken och Finlands flagga. Bland produkterna under namnet finns kåsor i trä, mjukisrenar och mjukishuskyhundar, muggar, tygkassar och spelkort.',
      'fiskars':
        'Fiskars började 1649, då Peter Thorwöste fick tillstånd att anlägga en masugn och en smedja i en finländsk by med samma namn. Varumärket är mest känt för sina saxar med orange handtag, som lanserades 1967 som de första saxarna med plasthandtag; Classic-modellen tillverkas fortfarande vid företagets fabrik i Billnäs i Finland och varje sax testas för hand. Vid sidan av saxar säljer Fiskars trädgårdsredskap, yxor och köksknivar.',
      'arctic-power-berries':
        'Arctic Power Berries är ett varumärke för bärpulver som drivs av Anna och Eveliina, två barndomsvänner från Rovaniemi i finska Lappland som startade verksamheten efter att ha flyttat till London. Sortimentet består av pulver av enskilda bär i påsar på 70 g: blåbär (skogsblåbär), lingon, havtorn, svarta vinbär, tranbär, jordgubbe och hallon, plus en blandning av flera bär. Företaget uppger att de vilda bären plockas för hand i Finland, torkas skonsamt och mals, att det går ungefär 700 g färska bär på varje påse om 70 g och att inget annat tillsätts.',
      'golden-crown-levin-iglut':
        'Levin Iglut Golden Crown är en familjedriven glasiglooanläggning på fjället Utsuvaara intill Levi i finska Lappland. Tauno Mäkelä byggde de fyra första igloorna 2008, och anläggningen har nu 27 glasigloor, villan Northern Lights House för sex personer och en egen restaurang, Restaurant Utsu, öppen från slutet av augusti till början av april. För den som köper present är de relevanta produkterna presentkorten på iglooövernattningar och middagar på Utsu, samt Golden Crown Shop i receptionen, som för finländska design- och hantverksvarumärken.',
      'sisu':
        'Sisu är ett finländskt pastillvarumärke som lanserades 1928. Receptet togs fram av kemisten Johan Ponkamo i källaren till konfektyrfabriken Seres i Åbo, och pastillen bygger på en bas av gummi arabicum med salmiaksmak. Varumärket ingår nu i Cloettas portfölj och omfattar pastiller med salmiak, mentol och lakrits, sockerfria versioner och xylitolversioner, och sedan 2022 även godispåsar.',
      'kultakuume-com':
        'Kultakuume är ett familjedrivet företag i Saariselkä i finska Lappland, som uppger att det har verkat i området sedan 2008 och hyrt ut stugor sedan 2009. Det säljer guidade guldvaskningsdagar på sitt eget inmutade område, där besökarna lärs upp i vaskning för hand, får se maskinell tvättning och får behålla allt guld de hittar. Vid sidan av turerna hyr företaget ut stockstugorna Kultakelo på Kaunispää och säljer en serie på 18 canvastavlor med guldvaskningsmotiv, var och en 100 x 100 cm.',
      'muurla':
        'Muurla är ett finländskt designföretag vars historia började vid en glasfabrik i Muurla i sydvästra Finland, där fabriksbutiken öppnade våren 1974. I dag är det känt för emaljmuggar och emaljserviser, glas och serveringsbrickor i björkfanér, och för sin licensierade muminkollektion. Muurla uppger att alla dess produkter formges i Finland, medan tillverkningslandet varierar per produkt: produkter i björkfanér tillverkas i Finland, största delen av emaljvarorna i Europa och glas både i Europa och i Asien.',
      'novita':
        'Novita är ett finländskt garnföretag som grundades 1928 av Ernst Gylfe, som lärde sig kamgarnsspinning i Bradford i England innan han startade produktionen i Helsingfors. Verksamheten är fortfarande familjeägd i fjärde generationen och har drivit sitt spinneri i Koria i Kouvola sedan 1974, där det uppger sig producera omkring en miljon kilo garn per år. Dess mest kända produkt är sockgarnet 7 Veljestä, spunnet av ull som företaget uppger sig köpa huvudsakligen från Europa, främst England.',
      'mikebon':
        'Mikebon Oy är ett familjedrivet företag inom textiltryck och brodyr som grundades 1994 och har sin bas i Petikko i Vanda. Det sköter formgivning, grafiskt utförande, produktion och logistik själv, och uppger på sin egen webbplats att produktionen sker i Finland. Dess huvudsakliga kunder är souvenir- och presentbutiker, och det driver också en webbutik för konsumenter vars sortiment omfattar tröjor och huvtröjor med Lappland-, Finland- och mumintema.',
      'aromageddon':
        'Aromageddon är ett sortiment bastudofter från Aromageddon Oy, ett företag registrerat i Helsingfors, som daterar idén till ett bastubad sommaren 2024. Serien omfattar sex dofter på 15 ml för 7,90 euro styck plus tre presentförpackningar, och temana kommer från drycker och godis i stället för skog eller björk: whisky, öl, ismint, pepparmintsgodis, kanel och mintkakao. Företaget publicerar ett CLP-säkerhetsdatablad för varje doft på sin egen webbplats, och de dryckestemade versionerna bär smaknoten utan alkohol.',
      'leijona':
        'Leijona är ett finländskt pastillvarumärke som ägs av Cloetta och som är mest känt för Leijona Tervalakritsi, en sockrad lakritspastill med tjärsmak. Den utvecklades av apotekaren Yrjö Jalander, grundare av konfektyrföretaget Merijal i Uleåborg, och kom ut på marknaden 1933. Vid sidan av pastillaskarna på 32 g omfattar det nuvarande sortimentet godispåsar på 180 g, och varumärket drivs av Cloetta Suomi Oy från Åbo.',
    },
  },
  fr: {
    eyebrow: 'Marque',
    founded: (y) => `Fondée en ${y}`,
    officialSite: (n) => `Le site de ${n}`,
    productsH2: (n) => `${n} dans cette boutique`,
    indexH1: 'Nos marques',
    indexIntro:
      'Qui fabrique les articles de cette boutique, et où. Chaque portrait s’appuie sur ce que la marque publie elle-même et renvoie à son propre site.',
    indexCount: (n) => `${n} produits`,
    profile: {
      'aarikka':
        'Aarikka est une maison de design finlandaise fondée en 1954 par Kaija Aarikka et Erkki Ruokonen, connue pour ses perles et ses bijoux en bois, et détenue par Martinex Oy depuis 2017. La marque attribue à la Finlande la conception ainsi que l\'assemblage à la main de ses bijoux en bois et de ses articles de maison en bois, mais elle ne se présente pas comme une gamme entièrement fabriquée en Finlande. Ses vêtements indiquent, produit par produit, des pays de fabrication explicites situés hors de Finlande, et certaines matières premières proviennent de l\'étranger.',
      'foodin':
        'Foodin est une entreprise familiale finlandaise d\'aliments biologiques établie à Vaajakoski, à Jyväskylä, qui se décrit comme fabricant et non comme simple importateur. Sa gamme de chocolat cru est broyée à la meule de pierre et finie à la main dans l\'usine que l\'entreprise possède à Vaajakoski, avec un cacao issu de fèves Criollo cultivées en Amazonie péruvienne. La même usine est également citée comme site de production des barres protéinées de l\'entreprise.',
      'kuivalihakundi':
        'Kuivalihakundi (Dried Buddy Oy) est un producteur finlandais de viande séchée qui sèche, découpe et emballe sa viande dans son propre atelier de viande agréé à Jokela, à Tuusula, un site d\'environ 1 500 m2 où il s\'est installé fin 2023. Le lieu de fabrication est confirmé à la fois par les pages de la marque et par la décision officielle de la commune concernant cet établissement alimentaire. L\'étiquetage de la marque indique que le bœuf est élevé et abattu dans l\'UE : l\'origine finlandaise de la viande crue elle-même n\'est donc pas confirmée.',
      'halti':
        'Halti est une marque finlandaise de plein air fondée en 1976 par Juhani Hyokyvaara, dont la conception se fait à son siège de Sipoo. La marque indique sur son propre site que la production est répartie entre plusieurs pays : Chine, Vietnam et Bangladesh pour les vêtements de sport techniques, plus des fournisseurs européens en Italie, en Ukraine et en Lituanie. Selon les informations de Halti elle-même, seuls les chaussettes et les bonnets sont fabriqués en Finlande ; la marque doit donc être décrite comme conçue en Finlande plutôt que fabriquée en Finlande.',
      'north-outdoor':
        'North Outdoor est une marque finlandaise de vêtements en laine mérinos exploitée par Pyka Oy, surtout connue pour l\'usine de tricotage qu\'elle a ouverte dans le quartier de Rusko, à Oulu, en 2021, présentée par Yle comme la plus grande usine de pulls en laine de Finlande. La marque répartit sa production entre plusieurs pays et décrit cette répartition par catégorie de produit plutôt que comme une origine unique. Sa propre description publiée de cette répartition se contredit dans sa version anglaise, la ventilation par catégorie ne doit donc pas être reprise comme un fait établi.',
      'marttiini':
        'Marttiini est une marque finlandaise de couteaux née en 1928, lorsque le forgeron Janne Marttiini a ouvert un atelier de puukko à Rovaniemi. Le catalogue va aujourd\'hui des couteaux de chasse et à filet aux couteaux de cuisine, couteaux pliants et puukkos traditionnels, avec des manches en bouleau madré ou en bois de renne et des lames portées dans des étuis en cuir. Le Lapinleuku à lame large et les couteaux à filet qui ont porté la marque vers les marchés d\'exportation sont ses formes les plus reconnaissables.',
      'kupilka':
        'Kupilka est une marque finlandaise de vaisselle de plein air gérée par l\'entreprise familiale Plasthill Oy à Kontiolahti, en Carélie du Nord. Ses tasses, assiettes et couverts sont moulés dans un composite de fibres naturelles Kareline propre à l\'entreprise, composé pour environ moitié de cellulose de résineux nordique et pour moitié de polyoléfines de qualité alimentaire, produit en interne sur le site de Pyytivaara avec de l\'électricité renouvelable certifiée. L\'origine de la vaisselle est bien documentée par la marque, mais le reste du catalogue, les couteaux et les allume-feu en particulier, fait appel à des fournisseurs extérieurs.',
      'nordicbuddies':
        'Nordicbuddies est une entreprise de design finlandaise basée à Helsinki (immatriculée sous le nom d\'Oy Bisly Ltd) et licenciée officielle de Moumine, de Fifi Brindacier (Pippi Longstocking) et de Mauri Kunnas ; elle vend des chaussettes, chemises, casquettes, sacs et autres accessoires. La conception se fait à Helsinki, mais la page À propos de la marque situe la fabrication principalement en Europe et en Eurasie, avec une partie seulement de la production en Finlande, et son coton dans les régions chinoises d\'Anhui et du Henan. Les données d\'origine déclarées par les détaillants indiquent la Chine au niveau du produit, la marque doit donc être décrite comme conçue en Finlande et non fabriquée en Finlande.',
      'marimekko':
        'Marimekko a été fondée en Finlande en 1951 et exploite toujours sa propre usine d\'impression textile à Helsinki, qui imprime plus d\'un million de mètres de tissu par an, y compris tous les tissus vendus au mètre. Les produits finis eux-mêmes sont cousus par un réseau de fournisseurs partenaires, et Marimekko cite la Finlande, les pays baltes, le Portugal, la Chine et la Thaïlande parmi ses pays de fabrication. En 2025, 54 pour cent des produits ont été fabriqués dans l\'UE et dans d\'autres pays européens : on ne peut donc pas supposer qu\'un produit Marimekko soit fabriqué en Finlande sans vérifier l\'article en question.',
      'rento':
        'Rento est une gamme de sauna conçue en Finlande et détenue par l\'entreprise familiale Tammer Brands Oy, de Tampere. La marque conçoit en Finlande et porte largement le label Design from Finland, mais la production est répartie entre la Finlande, d\'autres pays européens et des usines auditées Amfori BSCI, et le pays d\'origine est déterminé par produit et non par marque. Plusieurs articles vendus sous le nom de Rento sont fabriqués hors de Finlande, l\'origine doit donc être vérifiée produit par produit.',
      'lapuan-kankurit':
        'Lapuan Kankurit est une entreprise de tissage finlandaise dont l\'usine principale se trouve à Lapua et dont les racines remontent à 1917. Selon ses propres informations, elle tisse 95 % de ses produits à Lapua, le reste étant fabriqué dans une usine détenue en partie à Kaunas, en Lituanie, et par des sous-traitants européens. Toutes les matières premières proviennent de l\'extérieur de la Finlande : le lin de France, des Pays-Bas et de Belgique, le mohair d\'Afrique du Sud.',
      'iittala':
        'Iittala est une marque de design finlandaise construite autour de la verrerie d\'Iittala, fondée en 1881 dans le village d\'Iittala et aujourd\'hui intégrée au groupe Fiskars. Sa société mère décrit le site de Hämeenlinna comme la seule verrerie encore en activité en Finlande, employant environ 200 personnes, et Iittala indique sur son propre site que les vases d\'Alvar Aalto et le verre Ultima Thule y sont soufflés à la bouche. Sa céramique, en revanche, est fabriquée par des sous-traitants à l\'étranger : l\'origine finlandaise ne vaut donc que pour la verrerie.',
      'arctic-warriors':
        'Arctic Warriors, fondée en 2014, est une petite entreprise finlandaise de produits naturels immatriculée au village de Narkaus, près de Rovaniemi en Laponie. Elle vend des poudres de baies et de plantes et des élixirs végétaux à base de glycérol, faits de plantes et de baies de Laponie achetées à de petits producteurs et cueilleurs locaux. Ses propres fiches produits indiquent la Finlande comme origine, mais sans préciser de lieu de production ni de conditionnement.',
      'makia':
        'Makia est une entreprise de vêtements basée à Helsinki, fondée en 2001, qui conçoit en Finlande et fabrique à l\'étranger. Ses propres pages citent la Türkiye comme principal pays de production, avec les vestes et la plupart des accessoires venant de Chine, les chaussettes du Portugal et de Türkiye, et une petite part d\'accessoires en laine fabriquée en Finlande. Les pages de la marque se contredisent toutefois sur la liste complète des pays : aucune ventilation précise de l\'origine par catégorie ne peut donc être présentée comme vérifiée.',
      'pentik':
        'Pentik est une marque finlandaise d\'articles pour la maison qui a débuté à Posio en 1971 et qui y exploite toujours une fabrique de céramique et un atelier de bougies attenant. L\'usine ne couvre cependant pas toute la gamme : selon les propres rapports de durabilité de la marque, environ un quart de ses produits ont été fabriqués en Finlande en 2022, le reste étant produit ailleurs en Europe et en Asie. Pentik a déclaré qu\'elle ne met pas en avant le pays de fabrication sur ses produits.',
      'arabia':
        'Arabia est une marque finlandaise de céramique et d\'arts de la table enracinée dans le quartier d\'Arabianranta à Helsinki et détenue aujourd\'hui par le groupe Fiskars. Son usine de céramique d\'Helsinki a cessé la production au printemps 2016, et Fiskars indique sur ses propres pages de marque que les produits Arabia proviennent désormais de sous-traitants de longue date, principalement en Thaïlande et en Roumanie. La conception et le développement des produits ont toujours lieu en Finlande, et le quartier Arabia d\'Helsinki poursuit son activité comme musée, boutique et centre de design.',
      'fazer':
        'Fazer est une entreprise alimentaire finlandaise fondée à Helsinki en 1891, surtout connue pour le chocolat au lait Karl Fazer, Geisha et Marianne. Au-delà de la confiserie, le groupe exploite des activités de boulangerie, de meunerie et de restauration dans plusieurs pays. Son implantation industrielle est en train de changer : une nouvelle chocolaterie est en construction à Lahti, et à l\'été 2026 Fazer a acheté des usines de confiserie en Suède.',
      'moomin':
        'Moomin Characters Oy Ltd est l\'entreprise familiale d\'Helsinki qui détient et supervise les droits sur les personnages des Moumines de Tove Jansson, apparus pour la première fois dans le livre de 1945 The Moomins and the Great Flood. L\'entreprise a cessé de fabriquer elle-même des produits il y a des décennies : chaque article vendu comme produit Moumine provient d\'un licencié, et le réseau en compte plus de 800 dans le monde. Côté cadeaux, la ligne la plus reconnaissable est celle des mugs Moumine en céramique d\'Arabia, une série lancée en 1990 et qui compte aujourd\'hui plus d\'une centaine de motifs.',
      'wild-about-lapland':
        'Wild About Lapland est un opérateur d\'activités basé à Rovaniemi, dont le bureau se trouve au Rovakatu 24. Chaque excursion est limitée à huit participants et le programme se déroule toute l\'année : sorties aurores boréales, safaris en motoneige et visites de rennes et de huskies en hiver, canoë et randonnée en été. Le fondateur et guide principal Theo Turner est un ancien commando des Royal Marines et instructeur de plein air, et l\'entreprise détient le label Sustainable Travel Finland.',
      'meritalo':
        'Meritalo est une entreprise familiale finlandaise de transformation de baies fondée en 1995 par Susanna et Olavi Lindstedt, qui ont quitté Helsinki pour Ylönkylä, dans la région de Salo, au sud-ouest de la Finlande. L\'entreprise indique que tous ses produits sont fabriqués dans ses propres locaux sur place, à partir de baies et de fruits 100 % finlandais achetés à des producteurs finlandais et cueillis dans les forêts finlandaises. La gamme s\'articule autour de confitures et de gelées, de jus et de sève de bouleau, et comprend une confiture d\'argousier de 310 g aux côtés de produits à la fraise, à l\'airelle rouge et à la pomme.',
      'nordqvist':
        'Nordqvist est une entreprise de thé finlandaise fondée en 1979, qui a débuté comme une boutique d\'Helsinki vendant des thés aromatisés et en vrac avant de se tourner vers l\'importation et la vente en gros. Ses thés sont aromatisés et conditionnés dans l\'usine de 3 000 mètres carrés de l\'entreprise à Nurmijärvi, ouverte en 2018. La gamme comprend des mélanges de longue date comme Keisarin Morsian et Tiikerin Päiväuni ainsi qu\'une ligne de thés sur le thème des Moomins, vendue en sachets, en vrac et en boîtes métalliques.',
      'puhdistamo':
        'Puhdistamo est une marque finlandaise de bien-être fondée en 2009 qui vend des vitamines, des minéraux et d\'autres compléments alimentaires, ainsi que des boissons énergisantes, du kombucha, des barres protéinées et de chocolat cru, et des superaliments. L\'entreprise exploite sa propre usine à Lempäälä, en Finlande, où elle fabrique la majeure partie de ses compléments et indique avoir produit plus de 80 millions de gélules en une seule année. L\'usine détient la certification de sécurité alimentaire FSSC 22000, et l\'entreprise indique que ses boissons sont sucrées à la stévia ou au sucre de canne biologique plutôt qu\'à l\'aspartame, à l\'acésulfame K ou au sucralose.',
      'emendo':
        'Emendo Oy est une entreprise finlandaise de sauna et de bien-être basée à Vaasa, qui indique sur son propre site avoir été fondée en 1986. Sa gamme couvre les parfums de sauna et de loyly, les miels de sauna, les textiles de sauna en lin et coton, les louches, les savons et les produits de soin de la peau, vendus sous deux noms, Emendo et KOLO Sauna. L\'entreprise dit fabriquer en Finlande ses parfums, ses miels de sauna et ses produits de soin du visage, du corps et des pieds, et ses articles de sauna Moomin sont sous licence de Moomin Characters et fondés sur les dessins originaux de Tove Jansson.',
      'moomin-arabia':
        'Moomin Arabia est la gamme Moomins de la marque de céramique finlandaise Arabia, fondée en 1873 et aujourd\'hui membre du groupe Fiskars. La première vaisselle Moomins est apparue dans les années 1950 avec des illustrations de Tove Jansson, et la série de mugs très collectionnée a débuté dans les années 1990 en reprenant la forme Teema de Kaj Franck. Le travail de design est réalisé au siège de l\'entreprise à Espoo, en Finlande, tandis que Fiskars Group indique que les produits Arabia sont fabriqués par des sous-traitants principalement en Thaïlande et en Roumanie.',
      'kaino-drinks':
        'KAINO Drinks est une gamme de boissons pétillantes sans alcool de Poikain Parhaat Oy, une entreprise alimentaire basée à Tampere, en Finlande. La boisson aux pousses d\'épicéa est fabriquée à la main à Tampere à partir de pousses d\'épicéa finlandaises, et les boissons titrent 0,0 % d\'alcool, sont véganes et certifiées biologiques sous le numéro FI-EKO-201. La gamme comprend pousse d\'épicéa, rhubarbe et rose, et feuille de cassis, vendues en bouteilles de 0,75 litre et de 0,2 litre.',
      'omega7':
        'Omega7 est une marque finlandaise de compléments à l\'huile d\'argousier dont les premiers produits sont arrivés sur le marché en 1997. Son huile d\'argousier double SBA24 associe huile de baie et huile de pépins, et elle est extraite par un procédé sans solvant à l\'usine de l\'entreprise à Tornio. Le producteur, Aromtech Oy, a mené des études cliniques avec des chercheurs et des médecins de l\'université de Turku et de l\'hôpital universitaire de Turku, et il conduit un projet pilote de culture d\'argousier biologique à Tervola, en Laponie.',
      'kaapa-mushrooms':
        'KÄÄPÄ Mushrooms est un producteur finlandais de champignons fonctionnels fondé en 2018 par Eric Puro, Otso Mursula et Seppo Riikonen. Son siège et son site de production se trouvent à Karjalohja, dans le sud de la Finlande, où les champignons sont cultivés sur un substrat de bouleau issu de forêts finlandaises certifiées FSC et PEFC, puis extraits selon la méthode ultrasonique NordRelease propre à l\'entreprise, avec de l\'eau de source purifiée. L\'entreprise détient la certification de sécurité alimentaire FSSC 22000, fabrique ses extraits à partir de carpophores et non de grain mycélié, et anime un réseau de culture du chaga en forêt via sa division KÄÄPÄ Forest.',
      'halva':
        'Halva est une confiserie familiale finlandaise fondée en 1931 par les frères Jean et Michael Karavokyros, qui s\'étaient installés en Finlande depuis la Grèce. Elle est surtout connue pour ses bonbons à la réglisse et au salmiakki, et l\'entreprise indique que sa fabrique de bonbons et son site de conditionnement se trouvent à Pitäjänmäki, à Helsinki. L\'affaire est aujourd\'hui dirigée par la troisième génération, et le halva à la pâte de sésame qui a donné son nom à l\'entreprise figure toujours dans la gamme.',
      'kilpissafarit':
        'Kilpissafarit est une entreprise de services de programmes à Kilpisjärvi, fondée en 1995 par le garde-frontière Hannu Rauhala et dirigée aujourd\'hui par son fils Jussi Rauhala. Elle encadre des safaris en motoneige, des sorties en raquettes et des randonnées, des sorties aurores boréales et des excursions de pêche dans la nature sauvage du Käsivarsi, dont un itinéraire en motoneige jusqu\'au Halti, le point culminant de la Finlande. La même base loue des motoneiges, des fatbikes électriques, des raquettes, des canoës et des kayaks à ceux qui partent par eux-mêmes.',
      'kaavi-porcini':
        'Kaavi Porcini est la marque de Kaavin Herkkutattitehdas Oy, une entreprise finlandaise qui sèche des champignons sauvages de forêt dans sa propre usine à Tohmajärvi. Les champignons sont cueillis dans les forêts de Savonie du Nord et de Carélie du Nord et séchés le jour même de leur cueillette. La gamme couvre le cèpe, la girolle, la chanterelle en tube et la trompette-des-morts, ainsi que du chaga récolté à Kittilä et une poudre de cèpe utilisée comme assaisonnement.',
      'tammer':
        'Tammer Brands est une entreprise familiale de Tampere, fondée en 1954 sous le nom de Tammer-Tukku et rebaptisée Tammer Brands Oy en 2019. Elle développe et distribue des produits de consommation pour la maison, le jardin et les loisirs sous un portefeuille de plus de 50 marques, parmi lesquelles la gamme de sauna Rento, la marque de grillades Mustang et Maku Kitchen Life. Pour Rento, l\'entreprise indique que les produits sont fabriqués en Finlande, ailleurs en Europe ou dans des usines auditées amfori BSCI, le pays de fabrication étant précisé sur chaque fiche produit.',
      'finlayson':
        'Finlayson fait remonter ses débuts à 1820, quand l\'Écossais James Finlayson installa un atelier de mécanique au bord des rapides de Tammerkoski, à Tampere. La filature de coton qui s\'est développée autour est devenue en 1975 le premier employeur privé de Finlande, avec 11 usines et 6 500 salariés, et l\'entreprise reste connue pour des noms familiers comme le motif Elefantti dessiné par Laina Koskela en 1969 et pour avoir lancé la housse de couette sur le marché finlandais en 1963. Aujourd\'hui, Finlayson vend du linge de lit, des serviettes, des textiles de cuisine et des tapis, publie la liste de ses usines et tisse ses tapis Rasypala en Finlande à partir de draps rapportés par les clients.',
      'finnish-flavours':
        'Finnish Flavours est une marque alimentaire finlandaise dirigée depuis Kerava. Sa gamme s\'articule autour de la réglisse en deux lignes, les morceaux Premium Palalaku et le Premium Chocolaku enrobé de chocolat, aux côtés de confitures d\'airelle rouge, de myrtille et de plaquebière, de truite arc-en-ciel finlandaise et de viande de renne séchée. La marque indique que ses confitures sont fabriquées en Finlande entièrement à partir de baies du pays, et ses revendeurs listés vont des magasins K finlandais et d\'une boutique de Rovaniemi à des importateurs aux États-Unis, au Canada, en Suisse, au Royaume-Uni et en Nouvelle-Zélande.',
      'aurora-borealis':
        'Aurora Borealis est une marque propre de Tammer Brands Oy, une entreprise familiale finlandaise de marques et de vente en gros dont le siège est à Tampere et dont les racines remontent à 1954. La gamme couvre des objets décoratifs, des articles du quotidien, des accessoires et des drapeaux construits autour de motifs de la nature finlandaise : forêts, rennes, huskies, aurores boréales et drapeau finlandais. Les produits vendus sous ce nom comprennent des kuksa en bois, des rennes et des huskies en peluche, des mugs, des tote bags et des jeux de cartes.',
      'fiskars':
        'Fiskars a commencé en 1649, quand Peter Thorwöste obtint l\'autorisation d\'installer un haut fourneau et une forge dans un village finlandais du même nom. La marque est surtout connue pour ses ciseaux à manches orange, lancés en 1967 comme les premiers ciseaux à manches en plastique ; le modèle Classic est toujours fabriqué à l\'usine de l\'entreprise à Billnäs, en Finlande, et chaque paire est testée à la main. Outre les ciseaux, Fiskars vend des outils de jardin, des haches et des couteaux de cuisine.',
      'arctic-power-berries':
        'Arctic Power Berries est une marque de poudres de baies dirigée par Anna et Eveliina, deux amies d\'enfance de Rovaniemi, en Laponie finlandaise, qui ont lancé l\'entreprise après s\'être installées à Londres. La gamme se compose de poudres d\'une seule baie en sachets de 70 g : myrtille (myrtille sauvage), airelle rouge, argousier, cassis, canneberge, fraise et framboise, plus un mélange de baies. L\'entreprise dit que les baies sauvages sont cueillies à la main en Finlande, séchées doucement puis broyées, avec environ 700 g de baies fraîches derrière chaque sachet de 70 g et rien d\'autre ajouté.',
      'golden-crown-levin-iglut':
        'Levin Iglut Golden Crown est un complexe familial d\'igloos de verre sur le fjäll d\'Utsuvaara, à côté de Levi, en Laponie finlandaise. Tauno Mäkelä a construit les quatre premiers igloos en 2008, et le site compte aujourd\'hui 27 igloos de verre, la villa Northern Lights House pour six personnes et son propre restaurant Utsu, ouvert de fin août à début avril. Pour ceux qui cherchent un cadeau, les articles pertinents sont ses cartes-cadeaux pour des séjours en igloo et des dîners à l\'Utsu, ainsi que la Golden Crown Shop à la réception, qui propose des marques finlandaises de design et d\'artisanat.',
      'sisu':
        'Sisu est une marque finlandaise de pastilles lancée en 1928. La recette a été mise au point par le chimiste Johan Ponkamo dans la cave de la fabrique de confiserie Seres à Turku, et la pastille repose sur une base de gomme arabique avec un goût de salmiakki. La marque fait aujourd\'hui partie du portefeuille de Cloetta et couvre des pastilles au salmiakki, au menthol et à la réglisse, des versions sans sucre et au xylitol, et depuis 2022 aussi des sachets de bonbons.',
      'kultakuume-com':
        'Kultakuume est une entreprise familiale de Saariselkä, en Laponie finlandaise, qui dit être présente dans la région depuis 2008 et louer des chalets depuis 2009. Elle vend des journées guidées d\'orpaillage sur sa propre concession, où les visiteurs apprennent l\'orpaillage à la batée, assistent au lavage mécanisé et gardent l\'or qu\'ils trouvent. À côté de ces sorties, elle loue les chalets en rondins Kultakelo sur le Kaunispää et vend une série de 18 tirages sur toile sur le thème de l\'orpaillage, chacun de 100 x 100 cm.',
      'muurla':
        'Muurla est une entreprise de design finlandaise dont l\'histoire a commencé dans une verrerie de Muurla, au sud-ouest de la Finlande, où la boutique d\'usine a ouvert au printemps 1974. Elle est connue aujourd\'hui pour ses mugs et sa vaisselle en émail, sa verrerie et ses planches de service en placage de bouleau, ainsi que pour sa collection Moomins sous licence. Muurla dit que tous ses produits sont conçus en Finlande, tandis que le pays de fabrication varie selon le produit : les articles en placage de bouleau sont fabriqués en Finlande, la plupart des émaux en Europe, et le verre en Europe comme en Asie.',
      'novita':
        'Novita est une entreprise finlandaise de fils à tricoter fondée en 1928 par Ernst Gylfe, qui avait appris la filature de laine peignée à Bradford, en Angleterre, avant de lancer la production à Helsinki. L\'entreprise appartient toujours à la famille, à la quatrième génération, et exploite sa filature de Koria, à Kouvola, depuis 1974, où elle dit produire environ un million de kilos de fil par an. Son produit le plus connu est le fil à chaussettes 7 Veljestä, filé à partir d\'une laine que l\'entreprise déclare provenir principalement d\'Europe, surtout d\'Angleterre.',
      'mikebon':
        'Mikebon Oy est une entreprise familiale d\'impression textile et de broderie fondée en 1994 et basée à Petikko, à Vantaa. Elle assure elle-même la conception, l\'exécution graphique, la production et la logistique, et indique sur son propre site que la production a lieu en Finlande. Ses principaux clients sont les détaillants de souvenirs et de cadeaux, et elle exploite aussi une boutique en ligne grand public dont les gammes comprennent des t-shirts et des sweats à capuche sur les thèmes de la Laponie, de la Finlande et des Moomins.',
      'aromageddon':
        'Aromageddon est une gamme de parfums de sauna d\'Aromageddon Oy, une société immatriculée à Helsinki, qui fait remonter l\'idée à une séance de sauna à l\'été 2024. La ligne comprend six parfums de 15 ml à 7,90 euros pièce plus trois coffrets cadeaux, et les thèmes viennent des boissons et des sucreries plutôt que de la forêt ou du bouleau : whisky, bière, menthe glacée, bonbon à la menthe poivrée, cannelle et cacao à la menthe. L\'entreprise publie une fiche de données de sécurité CLP pour chaque parfum sur son propre site, et les versions sur le thème des boissons portent la note aromatique sans alcool.',
      'leijona':
        'Leijona est une marque finlandaise de pastilles détenue par Cloetta, surtout connue pour Leijona Tervalakritsi, une pastille de réglisse enrobée de sucre et aromatisée au goudron. Elle a été mise au point par le pharmacien Yrjö Jalander, fondateur de la confiserie Merijal à Oulu, et est arrivée sur le marché en 1933. À côté des boîtes de pastilles de 32 g, la gamme actuelle comprend des sachets de bonbons de 180 g, et la marque est gérée par Cloetta Suomi Oy depuis Turku.',
    },
  },
  es: {
    eyebrow: 'Marca',
    founded: (y) => `Fundada en ${y}`,
    officialSite: (n) => `La web de ${n}`,
    productsH2: (n) => `${n} en esta tienda`,
    indexH1: 'Nuestras marcas',
    indexIntro:
      'Quién fabrica lo que hay en esta tienda, y dónde. Cada perfil parte de lo que la propia marca publica y enlaza a su web.',
    indexCount: (n) => `${n} productos`,
    profile: {
      'aarikka':
        'Aarikka es una casa de diseño finlandesa fundada en 1954 por Kaija Aarikka y Erkki Ruokonen, conocida por sus cuentas y joyas de madera, y propiedad de Martinex Oy desde 2017. La marca atribuye a Finlandia el diseño y el ensamblaje a mano de sus joyas de madera y de sus productos de madera para el hogar, pero no se presenta como una gama fabricada íntegramente en Finlandia. Su ropa indica de forma explícita el país de fabricación de cada producto fuera de Finlandia, y algunas materias primas se obtienen en el extranjero.',
      'foodin':
        'Foodin es una empresa finlandesa de alimentos ecológicos de propiedad familiar, con sede en Vaajakoski, Jyväskylä, que se describe a sí misma como fabricante y no solo como importadora. Su línea de chocolate crudo se muele a la piedra y se termina a mano en la planta propia de la empresa en Vaajakoski, con cacao procedente de granos criollo cultivados en la Amazonía peruana. Esa misma planta se menciona también como lugar de producción de las barritas de proteína de la empresa.',
      'kuivalihakundi':
        'Kuivalihakundi (Dried Buddy Oy) es un fabricante finlandés de carne seca que seca, corta y envasa su carne en su propia planta cárnica autorizada de Jokela, Tuusula, unas instalaciones de aproximadamente 1.500 m2 a las que se trasladó a finales de 2023. El lugar de fabricación está respaldado tanto por las páginas de la propia marca como por la decisión oficial del municipio sobre el establecimiento alimentario. El etiquetado de la propia marca indica que la carne de vacuno se cría y se sacrifica en la UE, por lo que no está confirmado que la carne cruda sea finlandesa.',
      'halti':
        'Halti es una marca finlandesa de ropa de exterior fundada en 1976 por Juhani Hyokyvaara, con el diseño hecho en su sede de Sipoo. La marca afirma en su propio sitio que la producción se reparte entre varios países: China, Vietnam y Bangladés para la ropa deportiva técnica, además de proveedores europeos en Italia, Ucrania y Lituania. Según la propia Halti, solo los calcetines y los gorros se fabrican en Finlandia, por lo que la marca debe describirse como diseñada en Finlandia y no como fabricada en Finlandia.',
      'north-outdoor':
        'North Outdoor es una marca finlandesa de ropa de lana merina gestionada por Pyka Oy, conocida sobre todo por la fábrica de punto que abrió en el distrito de Rusko, en Oulu, en 2021, descrita por Yle como la mayor fábrica de jerséis de lana de Finlandia. La marca reparte la producción entre varios países y describe ese reparto por categoría de producto en lugar de dar un origen único. Su propia descripción publicada de ese reparto es contradictoria en inglés, por lo que el desglose por categorías no debe repetirse como un hecho establecido.',
      'marttiini':
        'Marttiini es una marca finlandesa de cuchillos que empezó en 1928, cuando el herrero Janne Marttiini abrió un taller de puukko en Rovaniemi. Hoy el catálogo va de los cuchillos de caza y de fileteado a los de cocina, los plegables y los puukko tradicionales, con mangos de abedul rizado o asta de reno y hojas que se llevan en fundas de cuero. El Lapinleuku de hoja ancha y los cuchillos de fileteado que llevaron la marca a los mercados de exportación son sus formas más reconocibles.',
      'kupilka':
        'Kupilka es una marca finlandesa de vajilla de exterior gestionada por la empresa familiar Plasthill Oy en Kontiolahti, Carelia del Norte. Sus tazas, platos y cubiertos se moldean con Kareline, un compuesto propio de fibra natural formado aproximadamente por mitad de celulosa de madera de conífera nórdica y mitad de poliolefinas aptas para uso alimentario, producido internamente en la planta de Pyytivaara con electricidad renovable certificada. El origen de la vajilla está bien documentado por la marca, pero el resto del catálogo (en particular los cuchillos y los pedernales de ferrocerio) recurre a proveedores externos.',
      'nordicbuddies':
        'Nordicbuddies es una empresa finlandesa de diseño con sede en Helsinki (registrada como Oy Bisly Ltd) y licenciataria oficial de Moomin, Pippi Calzaslargas y Mauri Kunnas, que vende calcetines, camisetas, gorras, bolsos y otros accesorios. El trabajo de diseño se hace en Helsinki, pero la página About Us de la propia marca sitúa la fabricación principalmente en Europa y Eurasia, con solo una parte de la producción en Finlandia, y su algodón en las regiones chinas de Anhui y Henan. Los datos de origen declarados por los minoristas apuntan a China a nivel de producto, por lo que la marca debe describirse como diseñada en Finlandia, no como fabricada en Finlandia.',
      'marimekko':
        'Marimekko se fundó en Finlandia en 1951 y sigue teniendo su propia fábrica de estampación textil en Helsinki, que imprime más de un millón de metros de tela al año, incluida toda la tela que se vende por metros. Los productos acabados los cosen una red de proveedores asociados, y Marimekko cita a Finlandia, los países bálticos, Portugal, China y Tailandia entre sus países de fabricación. En 2025, el 54 por ciento de los productos se fabricó en la UE y en otros países europeos, por lo que no se puede dar por hecho que un producto de Marimekko esté fabricado en Finlandia sin comprobar el artículo concreto.',
      'rento':
        'Rento es una gama de sauna de diseño finlandés propiedad de la empresa familiar Tammer Brands Oy, de Tampere. La marca diseña en Finlandia y usa ampliamente el sello Design from Finland, pero la producción se reparte entre Finlandia, otros países europeos y fábricas auditadas según Amfori BSCI, y el país de origen se decide por producto y no por marca. Varios artículos vendidos como Rento se fabrican fuera de Finlandia, así que el origen hay que comprobarlo producto por producto.',
      'lapuan-kankurit':
        'Lapuan Kankurit es una empresa textil finlandesa cuya fábrica principal está en Lapua y cuyas raíces se remontan a 1917. Según sus propios datos, teje el 95 % de sus productos en Lapua, mientras que el resto se hace en una fábrica participada en Kaunas, Lituania, y en subcontratistas europeos. Todas las materias primas proceden de fuera de Finlandia: el lino de Francia, los Países Bajos y Bélgica, el mohair de Sudáfrica.',
      'iittala':
        'Iittala es una marca de diseño finlandesa construida en torno a la fábrica de vidrio de Iittala, fundada en 1881 en la aldea de Iittala y hoy parte de Fiskars Group. Su empresa matriz describe la planta de Hämeenlinna como la única fábrica de vidrio que sigue operando en Finlandia, con unos 200 empleados, e Iittala afirma en su propio sitio que allí se soplan a boca los jarrones de Alvar Aalto y el vidrio Ultima Thule. Su cerámica, en cambio, la hacen fabricantes subcontratados en el extranjero, por lo que la afirmación de origen finlandés se aplica solo a la cristalería.',
      'arctic-warriors':
        'Arctic Warriors es una pequeña empresa finlandesa de productos naturales registrada en la aldea de Narkaus, cerca de Rovaniemi, en Laponia, y fundada en 2014. Vende polvos de bayas y hierbas y elixires de hierbas a base de glicerol elaborados con hierbas y bayas de Laponia obtenidas de pequeños productores y recolectores locales. Sus propias fichas de producto indican Finlandia como origen, pero no señalan un lugar de producción o de envasado.',
      'makia':
        'Makia es una empresa de ropa con sede en Helsinki, fundada en 2001, que diseña en Finlandia y fabrica en el extranjero. Sus propias páginas señalan a Türkiye (Turquía) como principal país de producción, con las chaquetas y la mayoría de los accesorios de China, los calcetines de Portugal y Türkiye, y una pequeña parte de los accesorios de lana hecha en Finlandia. Sin embargo, las páginas de la propia marca se contradicen entre sí sobre la lista completa de países, por lo que no se puede dar por verificado ningún desglose exacto de origen por categoría.',
      'pentik':
        'Pentik es una marca finlandesa de artículos para el hogar que empezó en Posio en 1971 y que sigue teniendo allí una fábrica de cerámica y un taller de velas contiguo. Aun así, la fábrica no cubre toda la gama: según los informes de sostenibilidad de la propia marca, alrededor de una cuarta parte de sus productos se fabricó en Finlandia en 2022, y el resto se obtuvo en otros lugares de Europa y Asia. Pentik ha declarado que no destaca el país de fabricación en sus productos.',
      'arabia':
        'Arabia es una marca finlandesa de cerámica y vajilla arraigada en el barrio de Arabianranta, en Helsinki, y hoy propiedad de Fiskars Group. Su fábrica de cerámica de Helsinki dejó de producir en la primavera de 2016, y Fiskars afirma en sus propias páginas de marca que los productos de Arabia proceden ahora de fabricantes subcontratados a largo plazo, principalmente en Tailandia y Rumanía. El diseño y el desarrollo de producto siguen haciéndose en Finlandia, y el barrio de Arabia en Helsinki continúa como museo, tienda y centro de diseño.',
      'fazer':
        'Fazer es una empresa alimentaria finlandesa fundada en Helsinki en 1891, conocida sobre todo por el chocolate con leche Karl Fazer, Geisha y Marianne. Además de la confitería, el grupo tiene negocios de panadería, molinería y restauración en varios países. Su huella productiva está cambiando ahora mismo: se está construyendo una nueva fábrica de chocolate en Lahti y, en el verano de 2026, Fazer compró fábricas de confitería en Suecia.',
      'moomin':
        'Moomin Characters Oy Ltd es la empresa familiar de Helsinki que posee y supervisa los derechos de los personajes Moomin de Tove Jansson, que aparecieron por primera vez en el libro de 1945 Los Moomin y la gran inundación. La empresa dejó de fabricar productos ella misma hace décadas: todo artículo vendido como producto Moomin procede de un licenciatario, y la red suma más de 800 en todo el mundo. En el ámbito del regalo, la línea más reconocible son las tazas de cerámica Moomin de Arabia, una serie que empezó en 1990 y que hoy abarca más de cien diseños.',
      'wild-about-lapland':
        'Wild About Lapland es un operador de actividades con sede en Rovaniemi y oficina en Rovakatu 24. Cada excursión admite un máximo de ocho participantes y el programa funciona todo el año: salidas para ver auroras boreales, safaris en moto de nieve y visitas a renos y huskies en invierno, piragüismo y senderismo en verano. Su fundador y guía principal, Theo Turner, es antiguo comando de los Royal Marines e instructor de actividades al aire libre, y la empresa cuenta con el sello Sustainable Travel Finland.',
      'meritalo':
        'Meritalo es una empresa familiar finlandesa de elaboración de bayas fundada en 1995 por Susanna y Olavi Lindstedt, que se mudaron de Helsinki a Ylönkylä, en la zona de Salo, en el suroeste de Finlandia. La empresa afirma que todos sus productos se elaboran en sus propias instalaciones allí, con un 100 % de bayas y frutas finlandesas compradas a productores finlandeses y recogidas en los bosques del país. La gama se organiza en torno a mermeladas y jaleas, zumos y savia de abedul, e incluye una mermelada de espino amarillo de 310 g junto a productos de fresa, arándano rojo y manzana.',
      'nordqvist':
        'Nordqvist es una empresa finlandesa de té fundada en 1979, que empezó como una tienda de Helsinki dedicada a la venta de tés aromatizados y a granel y que después pasó a la importación y la venta al por mayor. Sus tés se aromatizan y se envasan en la fábrica propia de la empresa en Nurmijärvi, de 3.000 metros cuadrados, inaugurada en 2018. La gama incluye mezclas de larga trayectoria como Keisarin Morsian y Tiikerin Päiväuni junto a una línea de tés con temática de los Mumin, vendida en bolsitas, a granel y en latas.',
      'puhdistamo':
        'Puhdistamo es una marca finlandesa de bienestar fundada en 2009 que vende vitaminas, minerales y otros complementos junto a bebidas energéticas, kombucha, barritas de proteínas y de chocolate crudo, y superalimentos. La empresa tiene su propia fábrica en Lempäälä, Finlandia, donde elabora la mayoría de sus complementos y donde declara haber producido más de 80 millones de cápsulas en un solo año. La planta cuenta con la certificación de seguridad alimentaria FSSC 22000, y la empresa afirma que sus bebidas se endulzan con estevia o azúcar de caña ecológico en lugar de aspartamo, acesulfamo K o sucralosa.',
      'emendo':
        'Emendo Oy es una empresa finlandesa de sauna y bienestar con sede en Vaasa, que indica en su propio sitio web que fue fundada en 1986. Su gama abarca fragancias para la sauna y el löyly, mieles de sauna, textiles de sauna en lino y algodón, cazos, jabones y productos de cuidado de la piel, vendidos bajo dos nombres, Emendo y KOLO Sauna. La empresa dice que fabrica en Finlandia sus fragancias, sus mieles de sauna y sus productos de cuidado facial, corporal y de pies, y sus artículos de sauna Mumin están licenciados por Moomin Characters y se basan en los dibujos originales de Tove Jansson.',
      'moomin-arabia':
        'Moomin Arabia es la gama Mumin de la marca finlandesa de cerámica Arabia, fundada en 1873 y hoy parte de Fiskars Group. Las primeras vajillas Mumin aparecieron en los años cincuenta con ilustraciones de Tove Jansson, y la serie de tazas, muy coleccionada, comenzó en los años noventa con la forma Teema de Kaj Franck. El trabajo de diseño se hace en la sede de la empresa en Espoo, Finlandia, mientras que Fiskars Group indica que los productos de Arabia los fabrican empresas subcontratadas principalmente en Tailandia y Rumanía.',
      'kaino-drinks':
        'KAINO Drinks es una gama de bebidas espumosas sin alcohol de Poikain Parhaat Oy, una empresa alimentaria con sede en Tampere, Finlandia. La bebida de brotes de abeto se elabora a mano en Tampere con brotes de abeto finlandeses, y las bebidas tienen 0,0 % de alcohol, son veganas y cuentan con certificación ecológica FI-EKO-201. La gama incluye brote de abeto, ruibarbo y rosa, y hoja de grosella negra, en botellas de 0,75 litros y 0,2 litros.',
      'omega7':
        'Omega7 es una marca finlandesa de complementos de aceite de espino amarillo cuyos primeros productos llegaron al mercado en 1997. Su aceite doble de espino amarillo SBA24 combina aceite de la baya y aceite de la semilla, y se extrae mediante un proceso sin disolventes en la fábrica de la empresa en Tornio. El productor, Aromtech Oy, ha realizado estudios clínicos con investigadores y médicos de la Universidad de Turku y del Hospital Universitario de Turku, y mantiene un proyecto piloto de cultivo ecológico de espino amarillo en Tervola, Laponia.',
      'kaapa-mushrooms':
        'KÄÄPÄ Mushrooms es un productor finlandés de hongos funcionales fundado en 2018 por Eric Puro, Otso Mursula y Seppo Riikonen. Su sede y su planta de producción están en Karjalohja, en el sur de Finlandia, donde los hongos se cultivan sobre sustrato de abedul procedente de bosques finlandeses certificados FSC y PEFC y se extraen con el método ultrasónico propio de la empresa, NordRelease, con agua de manantial purificada. La empresa cuenta con la certificación de seguridad alimentaria FSSC 22000, elabora sus extractos a partir de cuerpos fructíferos y no de grano miceliado, y gestiona una red de cultivo de chaga en bosque a través de su división KÄÄPÄ Forest.',
      'halva':
        'Halva es una empresa familiar finlandesa de confitería fundada en 1931 por los hermanos Jean y Michael Karavokyros, que se habían trasladado a Finlandia desde Grecia. Es conocida sobre todo por sus dulces de regaliz y salmiakki, y la empresa indica que su fábrica de caramelos y su planta de envasado están en Pitäjänmäki, Helsinki. El negocio lo dirige ahora la tercera generación, y el halva de pasta de sésamo que dio nombre a la empresa sigue en la gama.',
      'kilpissafarit':
        'Kilpissafarit es una empresa de servicios de programa en Kilpisjärvi, fundada en 1995 por el guardia fronterizo Hannu Rauhala y dirigida ahora por su hijo Jussi Rauhala. Guía safaris en moto de nieve, salidas con raquetas de nieve y de senderismo, excursiones para ver auroras boreales y salidas de pesca en el área silvestre de Käsivarsi, incluida una ruta en moto de nieve hasta Halti, el punto más alto de Finlandia. Desde la misma base se alquilan motos de nieve, fatbikes eléctricas, raquetas de nieve, canoas y kayaks para quienes salen por su cuenta.',
      'kaavi-porcini':
        'Kaavi Porcini es la marca de Kaavin Herkkutattitehdas Oy, una empresa finlandesa que seca setas silvestres del bosque en su propia fábrica en Tohmajärvi. Las setas se recogen en los bosques de Savo del Norte y Carelia del Norte y se secan el mismo día en que se recogen. La gama incluye boleto, rebozuelo, rebozuelo atrompetado y trompeta negra, además de chaga recogida en Kittilä y un polvo de boleto que se usa como condimento.',
      'tammer':
        'Tammer Brands es una empresa familiar de Tampere, fundada en 1954 como Tammer-Tukku y rebautizada Tammer Brands Oy en 2019. Desarrolla y distribuye productos de consumo para el hogar, el jardín y el ocio bajo una cartera de más de 50 marcas, entre ellas la gama de sauna Rento, la marca de barbacoa Mustang y Maku Kitchen Life. Para Rento, la empresa indica que los productos se fabrican en Finlandia, en otros países de Europa o en fábricas auditadas por amfori BSCI, y que el país de fabricación figura en cada ficha de producto.',
      'finlayson':
        'Finlayson sitúa su origen en 1820, cuando el escocés James Finlayson instaló un taller mecánico junto a los rápidos de Tammerkoski, en Tampere. La fábrica de algodón que creció a su alrededor llegó a ser el mayor empleador privado de Finlandia en 1975, con 11 fábricas y 6.500 trabajadores, y la empresa sigue siendo conocida por nombres muy familiares como el estampado Elefantti que Laina Koskela diseñó en 1969 y por haber introducido la funda nórdica en el mercado finlandés en 1963. Hoy Finlayson vende ropa de cama, toallas, textiles de cocina y alfombras, publica su lista de fábricas y teje en Finlandia sus alfombras Rasypala con sábanas devueltas por los clientes.',
      'finnish-flavours':
        'Finnish Flavours es una marca finlandesa de alimentación gestionada desde Kerava. Su gama se centra en el regaliz en dos líneas, las piezas Premium Palalaku y el Premium Chocolaku recubierto de chocolate, junto a mermeladas de arándano rojo, arándano y mora ártica, trucha arcoíris finlandesa y carne de reno seca. La marca afirma que sus mermeladas se elaboran en Finlandia exclusivamente con bayas nacionales, y los minoristas que enumera van desde tiendas K finlandesas y una tienda de Rovaniemi hasta importadores en Estados Unidos, Canadá, Suiza, el Reino Unido y Nueva Zelanda.',
      'aurora-borealis':
        'Aurora Borealis es una marca propia de Tammer Brands Oy, una empresa familiar finlandesa de marcas y venta al por mayor con sede en Tampere cuyas raíces se remontan a 1954. La gama abarca piezas decorativas, artículos de uso diario, accesorios y banderas construidos en torno a motivos de la naturaleza finlandesa: bosques, renos, huskies, auroras boreales y la bandera de Finlandia. Entre los productos que se venden con este nombre hay vasos kuksa de madera, renos y huskies de peluche, tazas, bolsas de tela y barajas de cartas.',
      'fiskars':
        'Fiskars comenzó en 1649, cuando Peter Thorwöste recibió permiso para instalar un alto horno y una herrería en un pueblo finlandés del mismo nombre. La marca es conocida sobre todo por sus tijeras de mango naranja, lanzadas en 1967 como las primeras tijeras con mango de plástico; el modelo Classic se sigue fabricando en la fábrica de la empresa en Billnäs, Finlandia, y cada par se prueba a mano. Además de tijeras, Fiskars vende herramientas de jardín, hachas y cuchillos de cocina.',
      'arctic-power-berries':
        'Arctic Power Berries es una marca de bayas en polvo llevada por Anna y Eveliina, dos amigas de la infancia de Rovaniemi, en la Laponia finlandesa, que empezaron el negocio tras mudarse a Londres. La gama son polvos de una sola baya en bolsitas de 70 g: arándano azul (mirtilo), arándano rojo, espino amarillo, grosella negra, arándano agrio, fresa y frambuesa, además de una mezcla de varias bayas. La empresa dice que las bayas silvestres se recogen a mano en Finlandia, se secan con suavidad y se muelen, con unos 700 g de bayas frescas detrás de cada bolsita de 70 g y sin añadir nada más.',
      'golden-crown-levin-iglut':
        'Levin Iglut Golden Crown es un complejo familiar de iglús de cristal en el monte Utsuvaara, junto a Levi, en la Laponia finlandesa. Tauno Mäkelä construyó los cuatro primeros iglús en 2008, y el lugar tiene ahora 27 iglús de cristal, la villa Northern Lights House para seis personas y su propio Restaurant Utsu, abierto desde finales de agosto hasta principios de abril. Para quien busca regalos, lo relevante son sus tarjetas regalo para estancias en iglú y cenas en Utsu, y la Golden Crown Shop de la recepción, que ofrece marcas finlandesas de diseño y artesanía.',
      'sisu':
        'Sisu es una marca finlandesa de pastillas lanzada en 1928. La receta la desarrolló el químico Johan Ponkamo en el sótano de la fábrica de dulces Seres, en Turku, y la pastilla se basa en goma arábiga con sabor a salmiakki. La marca forma ahora parte de la cartera de Cloetta y abarca pastillas de salmiakki, mentol y regaliz, versiones sin azúcar y con xilitol, y desde 2022 también bolsas de caramelos.',
      'kultakuume-com':
        'Kultakuume es una empresa familiar de Saariselkä, en la Laponia finlandesa, que dice llevar operando en la zona desde 2008 y alquilando cabañas desde 2009. Vende jornadas guiadas de búsqueda de oro en su propia concesión, donde se enseña a los visitantes el bateo a mano, se les muestra el lavado mecanizado y se quedan con el oro que encuentren. Junto a las excursiones alquila las cabañas de troncos Kultakelo en Kaunispää y vende un conjunto de 18 impresiones sobre lienzo con temas de la búsqueda de oro, de 100 x 100 cm cada una.',
      'muurla':
        'Muurla es una empresa finlandesa de diseño cuya historia comenzó en una fábrica de vidrio en Muurla, en el suroeste de Finlandia, donde la tienda de fábrica abrió en la primavera de 1974. Hoy es conocida por sus tazas y vajillas esmaltadas, su cristalería y sus tablas de servir en chapa de abedul, y por su colección licenciada de los Mumin. Muurla dice que todos sus productos se diseñan en Finlandia, mientras que el país de fabricación varía según el producto: los artículos de chapa de abedul se hacen en Finlandia, la mayor parte del esmalte en Europa y el vidrio tanto en Europa como en Asia.',
      'novita':
        'Novita es una empresa finlandesa de hilados fundada en 1928 por Ernst Gylfe, que aprendió el hilado de lana peinada en Bradford, Inglaterra, antes de iniciar la producción en Helsinki. El negocio sigue en manos de la familia en su cuarta generación y tiene su hilandería en Koria, Kouvola, desde 1974, donde dice producir alrededor de un millón de kilos de hilo al año. Su producto más conocido es el hilo para calcetines 7 Veljestä, hilado con lana que la empresa declara obtener principalmente de Europa, sobre todo de Inglaterra.',
      'mikebon':
        'Mikebon Oy es una empresa familiar de estampación y bordado textil fundada en 1994 y con sede en Petikko, Vantaa. Se encarga ella misma del diseño, la ejecución gráfica, la producción y la logística, e indica en su propio sitio web que la producción tiene lugar en Finlandia. Sus principales clientes son minoristas de souvenirs y regalos, y también gestiona una tienda online para consumidores cuyas gamas incluyen camisetas y sudaderas con temas de Laponia, Finlandia y los Mumin.',
      'aromageddon':
        'Aromageddon es una gama de aromas para sauna de Aromageddon Oy, una empresa registrada en Helsinki, que sitúa el origen de la idea en una sesión de sauna del verano de 2024. La línea abarca seis aromas de 15 ml a 7,90 euros cada uno más tres sets de regalo, y los temas vienen de bebidas y dulces en lugar del bosque o el abedul: whisky, cerveza, menta helada, caramelo de menta, canela y cacao con menta. La empresa publica en su propio sitio web una ficha de datos de seguridad CLP de cada aroma, y las versiones inspiradas en bebidas llevan la nota de sabor sin alcohol.',
      'leijona':
        'Leijona es una marca finlandesa de pastillas propiedad de Cloetta, conocida sobre todo por Leijona Tervalakritsi, una pastilla de regaliz recubierta de azúcar y aromatizada con alquitrán. La desarrolló el farmacéutico Yrjö Jalander, fundador de la empresa de confitería Merijal, de Oulu, y llegó al mercado en 1933. Junto a las cajas de pastillas de 32 g, la gama actual incluye bolsas de caramelos de 180 g, y la marca la gestiona Cloetta Suomi Oy desde Turku.',
    },
  },
  it: {
    eyebrow: 'Marchio',
    founded: (y) => `Fondata nel ${y}`,
    officialSite: (n) => `Il sito di ${n}`,
    productsH2: (n) => `${n} in questo negozio`,
    indexH1: 'I nostri marchi',
    indexIntro:
      'Chi produce le cose di questo negozio, e dove. Ogni profilo parte da ciò che il marchio pubblica di sé e rimanda al suo sito.',
    indexCount: (n) => `${n} prodotti`,
    profile: {
      'aarikka':
        'Aarikka è una casa di design finlandese fondata nel 1954 da Kaija Aarikka ed Erkki Ruokonen, nota per le perle e i gioielli in legno, di proprietà di Martinex Oy dal 2017. Il marchio attribuisce alla Finlandia il design e l\'assemblaggio a mano dei suoi gioielli in legno e dei suoi prodotti in legno per la casa, ma non si presenta come una gamma interamente fabbricata in Finlandia. I suoi capi di abbigliamento riportano esplicitamente, prodotto per prodotto, paesi di fabbricazione fuori dalla Finlandia, e alcune materie prime provengono dall\'estero.',
      'foodin':
        'Foodin è un\'azienda finlandese di alimenti biologici a conduzione familiare con sede a Vaajakoski, Jyväskylä, che si descrive come produttore e non solo come importatore. La sua linea di cioccolato crudo viene macinata a pietra e rifinita a mano nello stabilimento di proprietà dell\'azienda a Vaajakoski, con cacao ottenuto da fave Criollo coltivate nell\'Amazzonia peruviana. Lo stesso stabilimento è indicato anche come sito di produzione delle barrette proteiche dell\'azienda.',
      'kuivalihakundi':
        'Kuivalihakundi (Dried Buddy Oy) è un produttore finlandese di carne essiccata che essicca, taglia e confeziona la carne nel proprio stabilimento di lavorazione carni approvato a Jokela, Tuusula, una struttura di circa 1.500 m2 in cui si è trasferito alla fine del 2023. Il luogo di fabbricazione è confermato sia dalle pagine del marchio sia dalla decisione ufficiale del comune sull\'impianto alimentare. L\'etichettatura del marchio indica che il manzo è allevato e macellato nell\'UE, quindi non è confermato che la carne cruda stessa sia finlandese.',
      'halti':
        'Halti è un marchio finlandese di abbigliamento outdoor fondato nel 1976 da Juhani Hyokyvaara, con il design realizzato nella sede di Sipoo. Sul proprio sito il marchio dichiara che la produzione è distribuita su più paesi: Cina, Vietnam e Bangladesh per l\'abbigliamento sportivo tecnico, oltre a fornitori europei in Italia, Ucraina e Lituania. Secondo quanto dichiara Halti stessa, solo i calzini e i berretti sono fabbricati in Finlandia, quindi il marchio va descritto come progettato in Finlandia e non come fabbricato in Finlandia.',
      'north-outdoor':
        'North Outdoor è un marchio finlandese di abbigliamento in lana merino gestito da Pyka Oy, noto soprattutto per il maglificio che ha aperto nel quartiere Rusko di Oulu nel 2021, indicato da Yle come il più grande maglificio di maglioni di lana della Finlandia. Il marchio distribuisce la produzione su più paesi e descrive tale suddivisione per categoria di prodotto invece che con un\'unica origine. La descrizione di quella suddivisione che il marchio pubblica in inglese è internamente incoerente, quindi la ripartizione per categoria non va ripetuta come dato certo.',
      'marttiini':
        'Marttiini è un marchio finlandese di coltelli nato nel 1928, quando il fabbro Janne Marttiini aprì una bottega di puukko a Rovaniemi. Il catalogo odierno va dai coltelli da caccia e da filetto ai coltelli da cucina, ai coltelli pieghevoli e ai puukko tradizionali, con manici in betulla fiammata o corno di renna e lame custodite in foderi di cuoio. Il Lapinleuku dalla lama larga e i coltelli da filetto che portarono il marchio sui mercati d\'esportazione sono le sue forme più riconoscibili.',
      'kupilka':
        'Kupilka è un marchio finlandese di stoviglie da outdoor gestito dall\'azienda familiare Plasthill Oy a Kontiolahti, nella Carelia settentrionale. Tazze, piatti e posate sono stampati in un composito proprietario di fibre naturali Kareline, formato per circa metà da cellulosa di conifere nordiche e per metà da poliolefine per uso alimentare, prodotto internamente nel sito di Pyytivaara con elettricità rinnovabile certificata. L\'origine delle stoviglie è ben documentata dal marchio, ma il resto del catalogo, in particolare i coltelli e gli acciarini, si appoggia a fornitori esterni.',
      'nordicbuddies':
        'Nordicbuddies è un\'azienda di design finlandese con sede a Helsinki (registrata come Oy Bisly Ltd) e licenziataria ufficiale di Moomin, Pippi Calzelunghe e Mauri Kunnas, che vende calzini, magliette, cappellini, borse e altri accessori. Il lavoro di design viene svolto a Helsinki, ma la pagina About Us del marchio colloca la fabbricazione principalmente in Europa e in Eurasia, con solo una parte della produzione in Finlandia, e il suo cotone nelle regioni cinesi di Anhui e Henan. I dati di origine dichiarati dai rivenditori indicano la Cina a livello di prodotto, quindi il marchio va descritto come progettato in Finlandia, non come fabbricato in Finlandia.',
      'marimekko':
        'Marimekko è stata fondata in Finlandia nel 1951 e gestisce tuttora la propria stamperia tessile a Helsinki, che stampa oltre un milione di metri di tessuto all\'anno, compresi tutti i tessuti venduti al metro. I prodotti finiti sono invece cuciti da una rete di fornitori partner, e Marimekko indica tra i propri paesi di fabbricazione Finlandia, paesi baltici, Portogallo, Cina e Thailandia. Nel 2025 il 54 percento dei prodotti è stato realizzato nell\'UE e in altri paesi europei, quindi non si può dare per scontato che un prodotto Marimekko sia fabbricato in Finlandia senza controllare il singolo articolo.',
      'rento':
        'Rento è una gamma di prodotti per la sauna progettata in Finlandia e di proprietà dell\'azienda familiare Tammer Brands Oy di Tampere. Il marchio progetta in Finlandia e usa ampiamente il marchio Design from Finland, ma la produzione è distribuita tra la Finlandia, altri paesi europei e fabbriche verificate secondo Amfori BSCI, e il paese di origine è deciso per singolo prodotto e non per marchio. Diversi articoli venduti come Rento sono fabbricati fuori dalla Finlandia, quindi l\'origine va verificata prodotto per prodotto.',
      'lapuan-kankurit':
        'Lapuan Kankurit è un\'azienda tessile finlandese il cui stabilimento principale si trova a Lapua e le cui radici risalgono al 1917. Secondo quanto dichiara, tesse il 95% dei suoi prodotti a Lapua, mentre il resto è realizzato in uno stabilimento partecipato a Kaunas, in Lituania, e da subappaltatori europei. Tutte le materie prime provengono da fuori dalla Finlandia: il lino da Francia, Paesi Bassi e Belgio, il mohair dal Sudafrica.',
      'iittala':
        'Iittala è un marchio di design finlandese costruito attorno alla vetreria di Iittala, fondata nel 1881 nel villaggio di Iittala e oggi parte di Fiskars Group. La sua casa madre descrive il sito di Hämeenlinna come l\'unica vetreria ancora in attività in Finlandia, con circa 200 dipendenti, e Iittala dichiara sul proprio sito che i vasi di Alvar Aalto e i bicchieri Ultima Thule vengono soffiati a bocca lì. Le sue ceramiche sono invece prodotte da terzisti all\'estero, quindi l\'affermazione sull\'origine finlandese vale solo per gli articoli in vetro.',
      'arctic-warriors':
        'Arctic Warriors è una piccola azienda finlandese di prodotti naturali registrata nel villaggio di Narkaus, vicino a Rovaniemi in Lapponia, fondata nel 2014. Vende polveri di bacche ed erbe ed elisir di erbe a base di glicerolo, ottenuti da erbe e bacche lapponi raccolte presso piccoli produttori e raccoglitori locali. Le sue pagine di prodotto indicano la Finlandia come origine, ma non dichiarano un luogo di produzione o di confezionamento.',
      'makia':
        'Makia è un\'azienda di abbigliamento con sede a Helsinki, fondata nel 2001, che progetta in Finlandia e fabbrica all\'estero. Le sue pagine indicano la Türkiye come principale paese di produzione, con le giacche e la maggior parte degli accessori dalla Cina, i calzini da Portogallo e Türkiye e una piccola quota di accessori in lana fabbricata in Finlandia. Le pagine del marchio però non concordano tra loro sull\'elenco completo dei paesi, quindi non si può indicare come verificata alcuna ripartizione precisa dell\'origine per categoria.',
      'pentik':
        'Pentik è un marchio finlandese di articoli per la casa nato a Posio nel 1971, dove gestisce ancora una fabbrica di ceramica e un attiguo laboratorio di candele. La fabbrica però non copre l\'intera gamma: secondo il rendiconto di sostenibilità del marchio, nel 2022 circa un quarto dei suoi prodotti è stato fabbricato in Finlandia, mentre il resto proveniva da altre località in Europa e in Asia. Pentik ha dichiarato di non evidenziare il paese di fabbricazione sui propri prodotti.',
      'arabia':
        'Arabia è un marchio finlandese di ceramiche e stoviglie radicato nel quartiere Arabianranta di Helsinki e oggi di proprietà di Fiskars Group. La sua fabbrica di ceramica di Helsinki ha cessato la produzione nella primavera 2016, e Fiskars dichiara sulle proprie pagine di marchio che i prodotti Arabia provengono ora da terzisti di lungo periodo, soprattutto in Thailandia e Romania. Il design e lo sviluppo prodotto avvengono ancora in Finlandia, e il quartiere Arabia di Helsinki prosegue come museo, negozio e centro del design.',
      'fazer':
        'Fazer è un\'azienda alimentare finlandese fondata a Helsinki nel 1891, nota soprattutto per il cioccolato al latte Karl Fazer, Geisha e Marianne. Oltre ai dolciumi il gruppo gestisce attività di panificazione, molitura e ristorazione in diversi paesi. La sua struttura produttiva è attualmente in movimento: a Lahti è in costruzione una nuova fabbrica di cioccolato e nell\'estate 2026 Fazer ha acquistato fabbriche dolciarie in Svezia.',
      'moomin':
        'Moomin Characters Oy Ltd è l\'azienda familiare di Helsinki che possiede e sorveglia i diritti sui personaggi Moomin di Tove Jansson, apparsi per la prima volta nel libro del 1945 The Moomins and the Great Flood. L\'azienda ha smesso di produrre articoli in proprio decenni fa: ogni articolo venduto come prodotto Moomin proviene da un licenziatario, e la rete ne conta oltre 800 in tutto il mondo. Sul fronte dei regali la linea più riconoscibile sono le tazze in ceramica Moomin di Arabia, una serie iniziata nel 1990 che oggi comprende oltre cento design.',
      'wild-about-lapland':
        'Wild About Lapland è un operatore di attività con sede a Rovaniemi, con ufficio in Rovakatu 24. Ogni escursione ha un limite di otto partecipanti e il programma si svolge tutto l\'anno: uscite per l\'aurora boreale, safari in motoslitta e visite a renne e husky in inverno, canoa ed escursioni a piedi in estate. Il fondatore e guida principale Theo Turner è un ex commando dei Royal Marines e istruttore outdoor, e l\'azienda possiede il marchio Sustainable Travel Finland.',
      'meritalo':
        'Meritalo è un\'azienda familiare finlandese di trasformazione delle bacche, fondata nel 1995 da Susanna e Olavi Lindstedt, che si trasferirono da Helsinki a Ylönkylä, nella zona di Salo, nel sud-ovest della Finlandia. L\'azienda dichiara che tutti i suoi prodotti sono realizzati nei propri stabilimenti in loco, con il 100% di bacche e frutta finlandesi acquistate da coltivatori finlandesi e raccolte nei boschi finlandesi. La gamma ruota attorno a confetture e gelatine, succhi e linfa di betulla, e comprende una confettura di olivello spinoso da 310 g accanto a prodotti a base di fragola, mirtillo rosso e mela.',
      'nordqvist':
        'Nordqvist è un\'azienda finlandese del tè fondata nel 1979, nata come negozio di Helsinki che vendeva tè aromatizzati e in foglia sfusa e passata in seguito all\'importazione e al commercio all\'ingrosso. I suoi tè vengono aromatizzati e confezionati nello stabilimento di proprietà dell\'azienda a Nurmijärvi, di 3.000 metri quadrati, aperto nel 2018. La gamma comprende miscele di lunga data come Keisarin Morsian e Tiikerin Päiväuni accanto a una linea di tè a tema Mumin venduta in bustine, in foglia sfusa e in latta.',
      'puhdistamo':
        'Puhdistamo è un marchio finlandese del benessere fondato nel 2009 che vende vitamine, minerali e altri integratori accanto a bevande energetiche, kombucha, barrette proteiche e di cioccolato crudo e superfood. L\'azienda gestisce un proprio stabilimento a Lempäälä, in Finlandia, dove produce la maggior parte dei suoi integratori e dichiara di aver prodotto oltre 80 milioni di capsule in un solo anno. Lo stabilimento è certificato FSSC 22000 per la sicurezza alimentare e l\'azienda afferma che le sue bevande sono dolcificate con stevia o zucchero di canna biologico anziché con aspartame, acesulfame K o sucralosio.',
      'emendo':
        'Emendo Oy è un\'azienda finlandese di prodotti per la sauna e il benessere con sede a Vaasa, che sul proprio sito dichiara di essere stata fondata nel 1986. La sua gamma comprende fragranze per la sauna e per il löyly, mieli da sauna, tessili da sauna in lino e cotone, mestoli, saponi e prodotti per la cura della pelle, venduti con due nomi, Emendo e KOLO Sauna. L\'azienda afferma di produrre in Finlandia le proprie fragranze, i mieli da sauna e i prodotti per la cura di viso, corpo e piedi, e i suoi articoli per la sauna a tema Mumin sono su licenza di Moomin Characters e basati sui disegni originali di Tove Jansson.',
      'moomin-arabia':
        'Moomin Arabia è la linea Mumin del marchio ceramico finlandese Arabia, fondato nel 1873 e oggi parte di Fiskars Group. Le prime stoviglie Mumin comparvero negli anni Cinquanta con illustrazioni di Tove Jansson, e la serie di tazze molto ricercata dai collezionisti iniziò negli anni Novanta utilizzando la forma Teema di Kaj Franck. Il lavoro di design viene svolto nella sede aziendale di Espoo, in Finlandia, mentre Fiskars Group dichiara che i prodotti Arabia sono realizzati da produttori terzi principalmente in Thailandia e Romania.',
      'kaino-drinks':
        'KAINO Drinks è una gamma di bevande frizzanti analcoliche di Poikain Parhaat Oy, un\'azienda alimentare con sede a Tampere, in Finlandia. La bevanda ai germogli di abete è prodotta a mano a Tampere con germogli di abete finlandesi, e le bevande sono a 0,0% di alcol, vegane e certificate biologiche con il codice FI-EKO-201. La gamma comprende germogli di abete, rabarbaro e rosa, e foglia di ribes nero, venduta in bottiglie da 0,75 litri e da 0,2 litri.',
      'omega7':
        'Omega7 è un marchio finlandese di integratori a base di olio di olivello spinoso i cui primi prodotti sono arrivati sul mercato nel 1997. Il suo doppio olio di olivello spinoso SBA24 unisce olio della bacca e olio dei semi, ed è estratto con un processo privo di solventi nello stabilimento dell\'azienda a Tornio. Il produttore, Aromtech Oy, ha condotto studi clinici con ricercatori e medici dell\'Università di Turku e dell\'ospedale universitario di Turku, e gestisce un progetto pilota di coltivazione biologica di olivello spinoso a Tervola, in Lapponia.',
      'kaapa-mushrooms':
        'KÄÄPÄ Mushrooms è un produttore finlandese di funghi funzionali fondato nel 2018 da Eric Puro, Otso Mursula e Seppo Riikonen. La sede e l\'impianto di produzione si trovano a Karjalohja, nel sud della Finlandia, dove i funghi vengono coltivati su substrato di betulla proveniente da foreste finlandesi certificate FSC e PEFC ed estratti con il metodo a ultrasuoni NordRelease dell\'azienda, che utilizza acqua sorgiva purificata. L\'azienda ha la certificazione di sicurezza alimentare FSSC 22000, produce i suoi estratti dai corpi fruttiferi anziché da cereali miceliati e gestisce una rete di coltivazione della chaga in foresta tramite la divisione KÄÄPÄ Forest.',
      'halva':
        'Halva è un\'azienda dolciaria familiare finlandese fondata nel 1931 dai fratelli Jean e Michael Karavokyros, trasferitisi in Finlandia dalla Grecia. È conosciuta soprattutto per le caramelle alla liquirizia e al salmiakki, e l\'azienda dichiara che la sua fabbrica di caramelle e il reparto di confezionamento si trovano a Pitäjänmäki, a Helsinki. L\'attività è oggi guidata dalla terza generazione e la halva di pasta di sesamo che ha dato il nome all\'azienda è ancora in gamma.',
      'kilpissafarit':
        'Kilpissafarit è un\'azienda di servizi per attività a Kilpisjärvi, fondata nel 1995 dalla guardia di frontiera Hannu Rauhala e oggi guidata dal figlio Jussi Rauhala. Organizza safari guidati in motoslitta, escursioni con le ciaspole e a piedi, uscite per l\'aurora boreale e battute di pesca nella natura selvaggia del Käsivarsi, compreso un percorso in motoslitta fino a Halti, il punto più alto della Finlandia. La stessa base noleggia motoslitte, fatbike elettriche, ciaspole, canoe e kayak a chi parte per conto proprio.',
      'kaavi-porcini':
        'Kaavi Porcini è il marchio di Kaavin Herkkutattitehdas Oy, un\'azienda finlandese che essicca funghi selvatici di bosco nel proprio stabilimento a Tohmajärvi. I funghi sono raccolti nelle foreste del Savo settentrionale e della Carelia settentrionale e vengono essiccati nello stesso giorno della raccolta. La gamma comprende porcini, finferli, finferle e trombette dei morti, oltre alla chaga raccolta a Kittilä e a una polvere di porcini usata come condimento.',
      'tammer':
        'Tammer Brands è un\'azienda familiare di Tampere, fondata nel 1954 come Tammer-Tukku e rinominata Tammer Brands Oy nel 2019. Sviluppa e distribuisce prodotti di consumo per la casa, il giardino e il tempo libero con un portafoglio di oltre 50 marchi, tra cui la linea per la sauna Rento, il marchio per la grigliata Mustang e Maku Kitchen Life. Per Rento l\'azienda dichiara che i prodotti sono fabbricati in Finlandia, altrove in Europa o in stabilimenti sottoposti ad audit amfori BSCI, con il paese di produzione indicato su ogni scheda prodotto.',
      'finlayson':
        'Finlayson fa risalire i suoi inizi al 1820, quando lo scozzese James Finlayson avviò un\'officina meccanica presso le rapide di Tammerkoski, a Tampere. Il cotonificio che vi crebbe attorno divenne nel 1975 il maggiore datore di lavoro privato della Finlandia, con 11 fabbriche e 6.500 dipendenti, e l\'azienda è tuttora nota per nomi familiari come il motivo Elefantti che Laina Koskela disegnò nel 1969 e per aver portato il copripiumino sul mercato finlandese nel 1963. Oggi Finlayson vende biancheria da letto, asciugamani, tessili da cucina e tappeti, pubblica l\'elenco delle sue fabbriche e tesse i tappeti Rasypala in Finlandia con le lenzuola restituite dai clienti.',
      'finnish-flavours':
        'Finnish Flavours è un marchio alimentare finlandese gestito da Kerava. La sua gamma è incentrata sulla liquirizia in due linee, i pezzetti Premium Palalaku e i Premium Chocolaku ricoperti di cioccolato, accanto a confetture di mirtillo rosso, mirtillo nero e camemoro, trota iridea finlandese e carne di renna essiccata. Il marchio dichiara che le sue confetture sono prodotte in Finlandia esclusivamente con bacche nazionali, e i rivenditori elencati vanno dai negozi K finlandesi e da un negozio a Rovaniemi fino a importatori negli Stati Uniti, in Canada, in Svizzera, nel Regno Unito e in Nuova Zelanda.',
      'aurora-borealis':
        'Aurora Borealis è un marchio proprio di Tammer Brands Oy, azienda familiare finlandese di marchi e commercio all\'ingrosso con sede a Tampere, le cui radici risalgono al 1954. La gamma comprende oggetti decorativi, articoli di uso quotidiano, accessori e bandiere costruiti attorno a motivi della natura finlandese: foreste, renne, husky, aurora boreale e bandiera finlandese. Tra i prodotti venduti con questo nome ci sono kuksa di legno, renne e husky di peluche, tazze, borse tote e carte da gioco.',
      'fiskars':
        'Fiskars nacque nel 1649, quando Peter Thorwöste ottenne il permesso di avviare un altoforno e una fucina in un villaggio finlandese dello stesso nome. Il marchio è conosciuto soprattutto per le forbici dal manico arancione, lanciate nel 1967 come le prime forbici con manici in plastica; il modello Classic è ancora prodotto nello stabilimento aziendale di Billnäs, in Finlandia, e ogni paio viene testato a mano. Oltre alle forbici, Fiskars vende attrezzi da giardino, asce e coltelli da cucina.',
      'arctic-power-berries':
        'Arctic Power Berries è un marchio di bacche in polvere gestito da Anna ed Eveliina, due amiche d\'infanzia di Rovaniemi, nella Lapponia finlandese, che hanno avviato l\'attività dopo essersi trasferite a Londra. La gamma è composta da polveri di una sola bacca in bustine da 70 g: mirtillo (mirtillo nero selvatico), mirtillo rosso, olivello spinoso, ribes nero, mirtillo rosso americano, fragola e lampone, più una miscela di bacche. L\'azienda afferma che le bacche selvatiche sono raccolte a mano in Finlandia, essiccate delicatamente e macinate, con circa 700 g di bacche fresche dietro ogni bustina da 70 g e nient\'altro aggiunto.',
      'golden-crown-levin-iglut':
        'Levin Iglut Golden Crown è un resort di igloo di vetro a conduzione familiare sulla collina di Utsuvaara, accanto a Levi, nella Lapponia finlandese. Tauno Mäkelä costruì i primi quattro igloo nel 2008 e oggi il sito conta 27 igloo di vetro, la villa Northern Lights House da sei persone e il proprio Restaurant Utsu, aperto da fine agosto a inizio aprile. Per chi cerca un regalo, gli articoli rilevanti sono le sue gift card per i soggiorni negli igloo e per le cene all\'Utsu, e il Golden Crown Shop alla reception, che propone marchi finlandesi di design e artigianato.',
      'sisu':
        'Sisu è un marchio finlandese di pastiglie lanciato nel 1928. La ricetta fu messa a punto dal chimico Johan Ponkamo nella cantina della fabbrica dolciaria Seres a Turku, e la pastiglia è costruita su una base di gomma arabica con aroma di salmiakki. Il marchio fa oggi parte del portafoglio di Cloetta e comprende pastiglie al salmiakki, al mentolo e alla liquirizia, versioni senza zucchero e allo xilitolo e, dal 2022, anche sacchetti di caramelle.',
      'kultakuume-com':
        'Kultakuume è un\'attività a conduzione familiare a Saariselkä, nella Lapponia finlandese, che dichiara di operare nella zona dal 2008 e di affittare cabine dal 2009. Vende giornate guidate di ricerca dell\'oro sulla propria concessione, dove ai visitatori viene insegnato il lavaggio a mano con la batea, si assiste al lavaggio meccanizzato e si tiene tutto l\'oro trovato. Oltre alle escursioni affitta le baite in legno Kultakelo sul Kaunispää e vende una serie di 18 stampe su tela a tema ricerca dell\'oro, ciascuna di 100 x 100 cm.',
      'muurla':
        'Muurla è un\'azienda finlandese di design la cui storia iniziò in una vetreria a Muurla, nel sud-ovest della Finlandia, dove il negozio della fabbrica aprì nella primavera del 1974. Oggi è conosciuta per tazze e stoviglie smaltate, articoli in vetro e vassoi in impiallacciatura di betulla, e per la sua collezione Mumin su licenza. Muurla afferma che tutti i suoi prodotti sono progettati in Finlandia, mentre il paese di produzione varia a seconda del prodotto: gli articoli in impiallacciatura di betulla sono fabbricati in Finlandia, la maggior parte degli smaltati in Europa e il vetro sia in Europa sia in Asia.',
      'novita':
        'Novita è un\'azienda finlandese di filati fondata nel 1928 da Ernst Gylfe, che imparò la filatura della lana pettinata a Bradford, in Inghilterra, prima di avviare la produzione a Helsinki. L\'attività è tuttora di proprietà familiare alla quarta generazione e dal 1974 gestisce la sua filatura a Koria, a Kouvola, dove dichiara di produrre circa un milione di chili di filato all\'anno. Il suo prodotto più noto è il filato per calze 7 Veljestä, filato con lana che l\'azienda riferisce di acquistare principalmente in Europa, soprattutto in Inghilterra.',
      'mikebon':
        'Mikebon Oy è un\'azienda familiare di stampa e ricamo su tessuto fondata nel 1994 e con sede a Petikko, a Vantaa. Cura internamente progettazione, esecuzione grafica, produzione e logistica, e dichiara sul proprio sito che la produzione avviene in Finlandia. I suoi clienti principali sono i rivenditori di souvenir e articoli da regalo, e gestisce anche un negozio online per i consumatori le cui gamme comprendono magliette e felpe a tema Lapponia, Finlandia e Mumin.',
      'aromageddon':
        'Aromageddon è una gamma di profumi per la sauna di Aromageddon Oy, azienda registrata a Helsinki, che fa risalire l\'idea a una sessione di sauna dell\'estate 2024. La linea comprende sei profumi da 15 ml a 7,90 euro ciascuno più tre confezioni regalo, e i temi vengono da bevande e dolci anziché dal bosco o dalla betulla: whisky, birra, menta ghiacciata, caramella alla menta piperita, cannella e cacao alla menta. L\'azienda pubblica sul proprio sito una scheda di sicurezza CLP per ogni profumo, e le versioni a tema bevande portano la nota aromatica senza alcol.',
      'leijona':
        'Leijona è un marchio finlandese di pastiglie di proprietà di Cloetta, conosciuto soprattutto per Leijona Tervalakritsi, una pastiglia di liquirizia ricoperta di zucchero e aromatizzata al catrame. Fu sviluppata dal farmacista Yrjö Jalander, fondatore dell\'azienda dolciaria Merijal di Oulu, e arrivò sul mercato nel 1933. Accanto alle scatole di pastiglie da 32 g, la gamma attuale comprende sacchetti di caramelle da 180 g, e il marchio è gestito da Cloetta Suomi Oy da Turku.',
    },
  },
  nl: {
    eyebrow: 'Merk',
    founded: (y) => `Opgericht in ${y}`,
    officialSite: (n) => `De site van ${n}`,
    productsH2: (n) => `${n} in deze winkel`,
    indexH1: 'Onze merken',
    indexIntro:
      'Wie de spullen in deze winkel maakt, en waar. Elk profiel is geschreven op basis van wat het merk zelf publiceert en linkt naar hun eigen site.',
    indexCount: (n) => `${n} producten`,
    profile: {
      'aarikka':
        'Aarikka is een Fins designhuis, in 1954 opgericht door Kaija Aarikka en Erkki Ruokonen, bekend om houten kralen en sieraden, en sinds 2017 eigendom van Martinex Oy. Het merk schrijft aan Finland het ontwerp toe en het met de hand assembleren van zijn houten sieraden en houten woonproducten, maar presenteert zijn assortiment niet als volledig in Finland vervaardigd. Bij de kleding staat per product expliciet een productieland buiten Finland vermeld, en een deel van de grondstoffen komt uit het buitenland.',
      'foodin':
        'Foodin is een Fins biologisch voedingsbedrijf in familiebezit, gevestigd in Vaajakoski, Jyväskylä, dat zichzelf omschrijft als producent en niet alleen als importeur. De rauwe chocoladelijn wordt in de eigen fabriek in Vaajakoski op steen gemalen en met de hand afgewerkt, met cacao van Criollo-bonen uit het Peruaanse Amazonegebied. Dezelfde fabriek wordt ook genoemd als productielocatie van de proteïnerepen van het bedrijf.',
      'kuivalihakundi':
        'Kuivalihakundi (Dried Buddy Oy) is een Finse jerkyproducent die zijn vlees droogt, snijdt en verpakt in een eigen goedgekeurde vleesinrichting in Jokela, Tuusula, een pand van ongeveer 1.500 m2 waar het eind 2023 introk. De productielocatie wordt onderbouwd door zowel de eigen pagina\'s van het merk als het officiële besluit van de gemeente over de levensmiddeleninrichting. Op het etiket van het merk zelf staat dat het rundvlees in de EU is gehouden en geslacht, dus dat het vlees zelf Fins is, staat niet vast.',
      'halti':
        'Halti is een Fins outdoormerk, in 1976 opgericht door Juhani Hyokyvaara, met het ontwerp op het hoofdkantoor in Sipoo. Het merk vermeldt op zijn eigen site dat de productie over meerdere landen verspreid is: China, Vietnam en Bangladesh voor technische sportkleding, plus Europese leveranciers in Italië, Oekraïne en Litouwen. Volgens Halti zelf worden alleen sokken en mutsen in Finland gemaakt, dus het merk kan beter Fins ontworpen dan Fins gemaakt worden genoemd.',
      'north-outdoor':
        'North Outdoor is een Fins merk van merinowollen kleding, geëxploiteerd door Pyka Oy, vooral bekend om de breierij die het in 2021 opende in het stadsdeel Rusko in Oulu, door Yle beschreven als de grootste wollen-truienfabriek van Finland. Het merk verdeelt de productie over meerdere landen en beschrijft die verdeling per productcategorie in plaats van als één herkomst. De eigen gepubliceerde beschrijving van die verdeling is in het Engels intern tegenstrijdig, dus de uitsplitsing per categorie mag niet als vaststaand feit worden herhaald.',
      'marttiini':
        'Marttiini is een Fins messenmerk dat begon in 1928, toen smid Janne Marttiini in Rovaniemi een puukko-werkplaats opende. Het assortiment loopt vandaag van jacht- en fileermessen tot keukenmessen, zakmessen en traditionele puukko\'s, met heften van kroezenberk of rendiergewei en lemmeten in leren scheden. De breedbladige Lapinleuku en de fileermessen die het merk naar de exportmarkten brachten, zijn de bekendste vormen.',
      'kupilka':
        'Kupilka is een Fins merk van outdoorservies, gerund door het familiebedrijf Plasthill Oy in Kontiolahti, Noord-Karelië. De bekers, borden en het bestek worden gegoten uit het eigen natuurvezelcomposiet Kareline, dat ongeveer half uit Noordse naaldhoutcellulose en half uit polyolefinen van voedselkwaliteit bestaat en in eigen huis op de locatie Pyytivaara wordt gemaakt met gecertificeerde hernieuwbare elektriciteit. De herkomst van het serviesgoed is door het merk goed gedocumenteerd, maar het bredere assortiment (met name messen en vuurstalen) leunt op externe leveranciers.',
      'nordicbuddies':
        'Nordicbuddies is een Fins designbedrijf uit Helsinki (geregistreerd als Oy Bisly Ltd) en officieel licentiehouder van Moomin, Pippi Langkous en Mauri Kunnas, dat sokken, shirts, petten, tassen en andere accessoires verkoopt. Het ontwerpwerk gebeurt in Helsinki, maar de eigen About Us-pagina van het merk legt de productie vooral in Europa en Eurazië met slechts een deel van de productie in Finland, en het katoen in de Chinese regio\'s Anhui en Henan. Door retailers opgegeven herkomstgegevens wijzen op productniveau naar China, dus het merk kan beter Fins ontworpen dan Fins gemaakt worden genoemd.',
      'marimekko':
        'Marimekko werd in 1951 in Finland opgericht en heeft nog steeds een eigen textieldrukkerij in Helsinki, waar per jaar ruim een miljoen meter stof wordt bedrukt, waaronder alle stof die per meter wordt verkocht. De eindproducten zelf worden genaaid door een netwerk van partnerleveranciers, en Marimekko noemt Finland, de Baltische landen, Portugal, China en Thailand als productielanden. In 2025 werd 54 procent van de producten in de EU en andere Europese landen gemaakt, dus van een Marimekko-product kan niet zonder controle van het afzonderlijke artikel worden aangenomen dat het in Finland is gemaakt.',
      'rento':
        'Rento is een in Finland ontworpen saunacollectie van het Tamperese familiebedrijf Tammer Brands Oy. Het merk ontwerpt in Finland en draagt breed het merkteken Design from Finland, maar de productie is verdeeld over Finland, andere Europese landen en fabrieken met een Amfori BSCI-audit, en het land van herkomst wordt per product bepaald, niet per merk. Verschillende artikelen die als Rento worden verkocht, worden buiten Finland gemaakt, dus de herkomst moet product voor product worden gecontroleerd.',
      'lapuan-kankurit':
        'Lapuan Kankurit is een Fins weverijbedrijf waarvan de belangrijkste weverij in Lapua staat en waarvan de wortels teruggaan tot 1917. Naar eigen zeggen weeft het 95% van zijn producten in Lapua, terwijl de rest wordt gemaakt in een deels eigen weverij in Kaunas, Litouwen, en door Europese onderaannemers. Alle grondstoffen komen van buiten Finland: vlas uit Frankrijk, Nederland en België, mohair uit Zuid-Afrika.',
      'iittala':
        'Iittala is een Fins designmerk dat is opgebouwd rond de glasfabriek Iittala, in 1881 opgericht in het dorp Iittala en nu onderdeel van Fiskars Group. Het moederbedrijf omschrijft de vestiging in Hämeenlinna als de enige glasfabriek die nog in Finland werkt, met ongeveer 200 medewerkers, en Iittala vermeldt op zijn eigen site dat de vazen van Alvar Aalto en het glas van Ultima Thule daar met de mond worden geblazen. Het keramiek wordt echter gemaakt door contractfabrikanten in het buitenland, dus de claim van Finse herkomst geldt alleen voor het glaswerk.',
      'arctic-warriors':
        'Arctic Warriors is een klein Fins bedrijf in natuurproducten, geregistreerd in het dorp Narkaus bij Rovaniemi in Lapland en opgericht in 2014. Het verkoopt bessen- en kruidenpoeders en kruidenelixers op glycerolbasis, gemaakt van Laplandse kruiden en bessen van lokale kleine boeren en plukkers. De eigen productpagina\'s vermelden Finland als herkomst, maar noemen geen productie- of verpakkingslocatie.',
      'makia':
        'Makia is een kledingbedrijf uit Helsinki, opgericht in 2001, dat in Finland ontwerpt en in het buitenland produceert. De eigen pagina\'s noemen Türkiye als belangrijkste productieland, met jassen en de meeste accessoires uit China, sokken uit Portugal en Türkiye, en een klein deel van de wollen accessoires gemaakt in Finland. De eigen pagina\'s van het merk spreken elkaar echter tegen over de volledige landenlijst, dus er kan geen precieze herkomstuitsplitsing per categorie als geverifieerd worden vermeld.',
      'pentik':
        'Pentik is een Fins woonmerk dat in 1971 in Posio begon en daar nog steeds een keramiekfabriek en een aangrenzend kaarsenatelier heeft. De fabriek dekt echter niet het hele assortiment: volgens de eigen duurzaamheidsrapportage van het merk werd in 2022 ongeveer een kwart van de producten in Finland gemaakt, de rest werd elders in Europa en Azië ingekocht. Pentik heeft verklaard dat het het land van productie niet op zijn producten benadrukt.',
      'arabia':
        'Arabia is een Fins merk van keramiek en serviesgoed met wortels in de Helsinkise wijk Arabianranta en tegenwoordig eigendom van Fiskars Group. De keramiekfabriek in Helsinki stopte in het voorjaar van 2016 met produceren, en Fiskars vermeldt op zijn eigen merkpagina\'s dat Arabia-producten nu komen van vaste contractfabrikanten, vooral in Thailand en Roemenië. Ontwerp en productontwikkeling gebeuren nog steeds in Finland, en de Arabia-wijk in Helsinki gaat verder als museum, winkel en designcentrum.',
      'fazer':
        'Fazer is een Fins voedingsbedrijf, in 1891 in Helsinki opgericht en vooral bekend van de melkchocolade Karl Fazer, Geisha en Marianne. Naast zoetwaren heeft de groep bakkerij-, molen- en restaurantactiviteiten in meerdere landen. De productielocaties verschuiven op dit moment: in Lahti wordt een nieuwe chocoladefabriek gebouwd, en in de zomer van 2026 kocht Fazer zoetwarenfabrieken in Zweden.',
      'moomin':
        'Moomin Characters Oy Ltd is het familiebedrijf uit Helsinki dat de rechten op de Moomin-figuren van Tove Jansson bezit en beheert; die verschenen voor het eerst in het boek The Moomins and the Great Flood uit 1945. Het bedrijf maakt al decennia zelf geen artikelen meer: elk artikel dat als Moomin-product wordt verkocht, komt van een licentiehouder, en dat netwerk telt er wereldwijd meer dan 800. Aan de cadeaukant is de bekendste lijn de keramische Moomin-mokken van Arabia, een serie die in 1990 begon en nu meer dan honderd ontwerpen omvat.',
      'wild-about-lapland':
        'Wild About Lapland is een activiteitenaanbieder in Rovaniemi, met kantoor aan Rovakatu 24. Elke tour heeft maximaal acht deelnemers en het programma loopt het hele jaar door: noorderlichttochten, sneeuwscootersafari\'s en bezoeken aan rendieren en husky\'s in de winter, kanoën en wandelen in de zomer. Oprichter en hoofdgids Theo Turner is een voormalig Royal Marines-commando en buitensportinstructeur, en het bedrijf draagt het label Sustainable Travel Finland.',
      'meritalo':
        'Meritalo is een Fins familiebedrijf dat bessen verwerkt, in 1995 opgericht door Susanna en Olavi Lindstedt, die vanuit Helsinki naar Ylonkyla in de regio Salo in Zuidwest-Finland verhuisden. Het bedrijf stelt dat al zijn producten daar in de eigen productieruimte worden gemaakt, met 100% Finse bessen en vruchten die bij Finse telers worden gekocht en in Finse bossen worden geplukt. Het assortiment is opgebouwd rond jams en gelei, sappen en berkensap, en omvat een duindoornjam van 310 g naast producten met aardbei, rode bosbes en appel.',
      'nordqvist':
        'Nordqvist is een Fins theebedrijf dat in 1979 werd opgericht en begon als een winkel in Helsinki met gearomatiseerde thee en losse thee, en later overging op import en groothandel. De theeën worden gearomatiseerd en verpakt in de eigen fabriek van 3.000 vierkante meter in Nurmijärvi, geopend in 2018. Het assortiment omvat al lang bestaande melanges zoals Keisarin Morsian en Tiikerin Päiväuni, naast een Moomin-theelijn die in zakjes, los en in blik wordt verkocht.',
      'puhdistamo':
        'Puhdistamo is een Fins wellnessmerk dat in 2009 werd opgericht en vitamines, mineralen en andere supplementen verkoopt, naast energiedranken, kombucha, eiwit- en rawchocoladerepen en superfoods. Het bedrijf heeft een eigen fabriek in Lempäälä, Finland, waar het de meeste van zijn supplementen maakt en waar het naar eigen opgave in één jaar meer dan 80 miljoen capsules produceerde. De fabriek heeft de voedselveiligheidscertificering FSSC 22000, en het bedrijf stelt dat zijn dranken worden gezoet met stevia of biologische rietsuiker in plaats van aspartaam, acesulfaam K of sucralose.',
      'emendo':
        'Emendo Oy is een Fins sauna- en wellnessbedrijf uit Vaasa, dat op zijn eigen site aangeeft dat het in 1986 is opgericht. Het assortiment omvat sauna- en loylygeuren, saunahoning, saunatextiel van linnen en katoen, opgietlepels, zepen en huidverzorgingsproducten, verkocht onder twee namen: Emendo en KOLO Sauna. Het bedrijf zegt dat het zijn geuren, saunahoning en gezichts-, lichaams- en voetverzorgingsproducten in Finland maakt, en zijn Moomin-saunaproducten zijn gelicentieerd van Moomin Characters en gebaseerd op de originele tekeningen van Tove Jansson.',
      'moomin-arabia':
        'Moomin Arabia is de Moomin-collectie van het Finse keramiekmerk Arabia, opgericht in 1873 en tegenwoordig onderdeel van Fiskars Group. Het eerste Moomin-servies verscheen in de jaren vijftig met illustraties van Tove Jansson, en de veel verzamelde mokkenserie begon in de jaren negentig op basis van de Teema-vorm van Kaj Franck. Het ontwerpwerk gebeurt op het hoofdkantoor van het bedrijf in Espoo in Finland, terwijl Fiskars Group aangeeft dat Arabia-producten worden gemaakt door contractfabrikanten, voornamelijk in Thailand en Roemenië.',
      'kaino-drinks':
        'KAINO Drinks is een alcoholvrije reeks bruisende dranken van Poikain Parhaat Oy, een voedingsbedrijf uit Tampere, Finland. De drank van sparrenscheuten wordt met de hand gemaakt in Tampere van Finse sparrenscheuten, en de dranken bevatten 0,0% alcohol, zijn veganistisch en biologisch gecertificeerd onder FI-EKO-201. Het assortiment omvat sparrenscheut, rabarber en roos, en zwartebessenblad, verkocht in flessen van 0,75 liter en 0,2 liter.',
      'omega7':
        'Omega7 is een Fins merk van duindoornoliesupplementen waarvan de eerste producten in 1997 op de markt kwamen. De SBA24 dubbele duindoornolie combineert bessenolie en zaadolie en wordt gewonnen met een oplosmiddelvrij proces in de fabriek van het bedrijf in Tornio. De producent, Aromtech Oy, heeft klinische studies uitgevoerd met onderzoekers en artsen van de Universiteit van Turku en het Universitair Ziekenhuis Turku, en heeft een proefproject met biologische duindoornteelt in Tervola, Lapland.',
      'kaapa-mushrooms':
        'KÄÄPÄ Mushrooms is een Finse producent van functionele paddenstoelen, in 2018 opgericht door Eric Puro, Otso Mursula en Seppo Riikonen. Het hoofdkantoor en de productiefaciliteit staan in Karjalohja in Zuid-Finland, waar paddenstoelen worden gekweekt op een substraat van berkenhout uit FSC- en PEFC-gecertificeerde Finse bossen en worden geëxtraheerd met de eigen ultrasone NordRelease-methode van het bedrijf, met gezuiverd bronwater. Het bedrijf heeft de voedselveiligheidscertificering FSSC 22000, maakt zijn extracten van vruchtlichamen in plaats van gemyceliseerd graan, en beheert via zijn divisie KÄÄPÄ Forest een netwerk voor de teelt van chaga in bossen.',
      'halva':
        'Halva is een Fins familiebedrijf in zoetwaren, in 1931 opgericht door de broers Jean en Michael Karavokyros, die vanuit Griekenland naar Finland waren verhuisd. Het is vooral bekend om drop en salmiak, en het bedrijf stelt dat zijn snoepfabriek en verpakkingsbedrijf in Pitajanmaki, Helsinki staan. De onderneming wordt nu geleid door de derde generatie, en de sesampasta halva die het bedrijf zijn naam gaf, zit nog steeds in het assortiment.',
      'kilpissafarit':
        'Kilpissafarit is een programmadienstenbedrijf in Kilpisjarvi, in 1995 opgericht door grenswachter Hannu Rauhala en nu geleid door zijn zoon Jussi Rauhala. Het begeleidt sneeuwscootersafari\'s, sneeuwschoen- en wandeltochten, noorderlichtuitstapjes en visreizen in de wildernis van Kasivarsi, waaronder een sneeuwscooterroute naar Halti, het hoogste punt van Finland. Dezelfde basis verhuurt sneeuwscooters, elektrische fatbikes, sneeuwschoenen, kano\'s en kajaks aan mensen die er op eigen houtje op uit trekken.',
      'kaavi-porcini':
        'Kaavi Porcini is het merk van Kaavin Herkkutattitehdas Oy, een Fins bedrijf dat wilde bospaddenstoelen droogt in zijn eigen fabriek in Tohmajärvi. De paddenstoelen worden verzameld in de bossen van Noord-Savo en Noord-Karelië en gedroogd op de dag dat ze worden geplukt. Het assortiment omvat eekhoorntjesbrood, cantharel, trechtercantharel en hoorn des overvloeds, plus chaga die in Kittilä wordt verzameld en een poeder van eekhoorntjesbrood dat als smaakmaker wordt gebruikt.',
      'tammer':
        'Tammer Brands is een familiebedrijf uit Tampere, in 1954 opgericht als Tammer-Tukku en in 2019 omgedoopt tot Tammer Brands Oy. Het ontwikkelt en distribueert consumentenproducten voor huis, tuin en vrije tijd onder een portfolio van meer dan 50 merken, waaronder de saunalijn Rento, het grillmerk Mustang en Maku Kitchen Life. Voor Rento stelt het bedrijf dat de producten worden gemaakt in Finland, elders in Europa of in fabrieken met een amfori BSCI-audit, waarbij het land van fabricage op elke productkaart wordt vermeld.',
      'finlayson':
        'Finlayson voert zijn begin terug op 1820, toen de Schot James Finlayson een machinewerkplaats opzette bij de stroomversnellingen van Tammerkoski in Tampere. De katoenfabriek die eromheen groeide, was in 1975 de grootste particuliere werkgever van Finland, met 11 fabrieken en 6.500 werknemers, en het bedrijf is nog steeds bekend van namen als het dessin Elefantti dat Laina Koskela in 1969 ontwierp en van de introductie van de dekbedovertrek op de Finse markt in 1963. Vandaag verkoopt Finlayson beddengoed, handdoeken, keukentextiel en vloerkleden, publiceert het zijn fabriekslijst en weeft het zijn Rasypala-vloerkleden in Finland van lakens die klanten hebben teruggestuurd.',
      'finnish-flavours':
        'Finnish Flavours is een Fins voedingsmerk dat vanuit Kerava wordt gerund. Het assortiment draait om drop in twee lijnen, Premium Palalaku-stukjes en met chocolade omhulde Premium Chocolaku, naast jams van rode bosbes, blauwe bosbes en moerasbraam, Finse regenboogforel en gedroogd rendiervlees. Het merk stelt dat zijn jams in Finland worden gemaakt en volledig uit Finse bessen bestaan, en de vermelde verkooppunten lopen van Finse K-winkels en een winkel in Rovaniemi tot importeurs in de Verenigde Staten, Canada, Zwitserland, het Verenigd Koninkrijk en Nieuw-Zeeland.',
      'aurora-borealis':
        'Aurora Borealis is een huismerk van Tammer Brands Oy, een Fins familiebedrijf in merken en groothandel met hoofdkantoor in Tampere, waarvan de wortels teruggaan tot 1954. Het assortiment omvat decoratieve stukken, alledaagse artikelen, accessoires en vlaggen rond motieven uit de Finse natuur: bossen, rendieren, husky\'s, het noorderlicht en de Finse vlag. Onder de naam worden onder meer houten kuksa-bekers, pluche rendieren en husky\'s, mokken, tote bags en speelkaarten verkocht.',
      'fiskars':
        'Fiskars begon in 1649, toen Peter Thorwöste toestemming kreeg om een hoogoven en een smederij op te zetten in een Fins dorp met dezelfde naam. Het merk is vooral bekend om zijn scharen met oranje handvatten, in 1967 op de markt gebracht als de eerste schaar met kunststof handvatten; het model Classic wordt nog steeds gemaakt in de fabriek van het bedrijf in Billnäs in Finland en elke schaar wordt met de hand getest. Naast scharen verkoopt Fiskars tuingereedschap, bijlen en keukenmessen.',
      'arctic-power-berries':
        'Arctic Power Berries is een merk van bessenpoeder dat wordt gerund door Anna en Eveliina, twee jeugdvriendinnen uit Rovaniemi in Fins Lapland die het bedrijf begonnen nadat ze naar Londen waren verhuisd. Het assortiment bestaat uit poeders van één bessensoort in zakjes van 70 g: blauwe bosbes, rode bosbes, duindoorn, zwarte bes, veenbes, aardbei en framboos, plus een gemengde bessenmelange. Het bedrijf zegt dat de wilde bessen in Finland met de hand worden geplukt, voorzichtig worden gedroogd en gemalen, met ongeveer 700 g verse bessen achter elk zakje van 70 g en verder niets toegevoegd.',
      'golden-crown-levin-iglut':
        'Levin Iglut Golden Crown is een familieresort met glazen iglo\'s op de fjäll Utsuvaara naast Levi in Fins Lapland. Tauno Mäkelä bouwde de eerste vier iglo\'s in 2008, en het terrein telt nu 27 glazen iglo\'s, de villa Northern Lights House voor zes personen en het eigen Restaurant Utsu, open van eind augustus tot begin april. Voor wie een cadeau zoekt, zijn de cadeaubonnen voor iglo-overnachtingen en Utsu-diners relevant, en de Golden Crown Shop bij de receptie, die Finse design- en ambachtsmerken voert.',
      'sisu':
        'Sisu is een Fins pastillemerk dat in 1928 op de markt kwam. Het recept werd uitgewerkt door chemicus Johan Ponkamo in de kelder van de snoepfabriek Seres in Turku, en de pastille is opgebouwd op een basis van arabische gom met een salmiaksmaak. Het merk zit nu in het portfolio van Cloetta en omvat pastilles met salmiak, menthol en drop, suikervrije en xylitolversies, en sinds 2022 ook snoepzakken.',
      'kultakuume-com':
        'Kultakuume is een familiebedrijf in Saariselkä in Fins Lapland, dat zegt sinds 2008 in het gebied actief te zijn en sinds 2009 hutten te verhuren. Het verkoopt begeleide dagen goudwassen op zijn eigen claim, waar bezoekers leren goud met de hand te wassen, het gemechaniseerde wassen bekijken en al het goud dat ze vinden mogen houden. Naast de tochten verhuurt het de blokhutten Kultakelo op de Kaunispää en verkoopt het een set van 18 canvasprints met goudwasmotieven, elk 100 x 100 cm.',
      'muurla':
        'Muurla is een Fins designbedrijf waarvan het verhaal begon bij een glasfabriek in Muurla in Zuidwest-Finland, waar de fabriekswinkel in het voorjaar van 1974 opende. Het is tegenwoordig bekend om geëmailleerde mokken en serviesgoed, glaswerk en serveerplanken van berkenfineer, en om zijn gelicentieerde Moomin-collectie. Muurla zegt dat al zijn producten in Finland worden ontworpen, terwijl het land van fabricage per product verschilt: artikelen van berkenfineer worden in Finland gemaakt, het meeste emaille in Europa en glas zowel in Europa als in Azië.',
      'novita':
        'Novita is een Fins garenbedrijf dat in 1928 werd opgericht door Ernst Gylfe, die het spinnen van kamgaren wol leerde in Bradford, Engeland, voordat hij de productie in Helsinki startte. Het bedrijf is nog steeds in handen van de familie, inmiddels in de vierde generatie, en heeft sinds 1974 zijn spinnerij in Koria, Kouvola, waar het naar eigen opgave ongeveer een miljoen kilo garen per jaar produceert. Het bekendste product is het sokkengaren 7 Veljestä, gesponnen uit wol die het bedrijf naar eigen opgave vooral uit Europa betrekt, hoofdzakelijk uit Engeland.',
      'mikebon':
        'Mikebon Oy is een familiebedrijf in textieldruk en borduurwerk, opgericht in 1994 en gevestigd in Petikko, Vantaa. Het verzorgt het ontwerp, de grafische uitvoering, de productie en de logistiek zelf, en geeft op zijn eigen site aan dat de productie in Finland plaatsvindt. De belangrijkste klanten zijn souvenir- en cadeauwinkels, en het bedrijf heeft ook een consumentenwebshop met onder meer shirts en hoodies met Lapland-, Finland- en Moomin-thema\'s.',
      'aromageddon':
        'Aromageddon is een reeks saunageuren van Aromageddon Oy, een in Helsinki geregistreerd bedrijf dat het idee dateert op een saunasessie in de zomer van 2024. De lijn omvat zes geuren van 15 ml voor 7,90 euro per stuk plus drie cadeausets, en de thema\'s komen uit dranken en snoep in plaats van bos of berk: whisky, bier, ijsmunt, pepermuntsnoep, kaneel en muntcacao. Het bedrijf publiceert voor elke geur een CLP-veiligheidsinformatieblad op zijn eigen site, en de versies met drankthema dragen de smaaknoot zonder alcohol.',
      'leijona':
        'Leijona is een Fins pastillemerk van Cloetta, vooral bekend van Leijona Tervalakritsi, een met suiker omhulde droppastille met teersmaak. Het werd ontwikkeld door apotheker Yrjö Jalander, oprichter van het snoepbedrijf Merijal uit Oulu, en kwam in 1933 op de markt. Naast de pastilledoosjes van 32 g omvat het huidige assortiment snoepzakken van 180 g, en het merk wordt vanuit Turku beheerd door Cloetta Suomi Oy.',
    },
  },
  'pt-BR': {
    eyebrow: 'Marca',
    founded: (y) => `Fundada em ${y}`,
    officialSite: (n) => `O site da ${n}`,
    productsH2: (n) => `${n} nesta loja`,
    indexH1: 'Nossas marcas',
    indexIntro:
      'Quem faz as coisas desta loja, e onde. Cada perfil parte do que a própria marca publica e leva ao site dela.',
    indexCount: (n) => `${n} produtos`,
    profile: {
      'aarikka':
        'A Aarikka é uma casa de design finlandesa fundada em 1954 por Kaija Aarikka e Erkki Ruokonen, conhecida por contas e joias de madeira, e pertencente à Martinex Oy desde 2017. A marca atribui à Finlândia o design e a montagem manual de suas joias de madeira e de seus produtos de madeira para a casa, mas não se apresenta como uma linha inteiramente fabricada na Finlândia. Suas roupas trazem países de fabricação explícitos, produto a produto, fora da Finlândia, e parte das matérias-primas vem do exterior.',
      'foodin':
        'A Foodin é uma empresa finlandesa familiar de alimentos orgânicos sediada em Vaajakoski, Jyväskylä, que se descreve como fabricante e não apenas importadora. Sua linha de chocolate cru é moída em pedra e finalizada à mão na fábrica própria da empresa em Vaajakoski, com cacau de grãos Criollo cultivados na Amazônia peruana. A mesma fábrica também é indicada como local de produção das barras de proteína da empresa.',
      'kuivalihakundi':
        'A Kuivalihakundi (Dried Buddy Oy) é uma fabricante finlandesa de carne seca que seca, corta e embala sua carne em fábrica de carne própria e aprovada em Jokela, Tuusula, uma instalação de cerca de 1.500 m2 para a qual se mudou no fim de 2023. O local de fabricação é comprovado tanto pelas páginas da própria marca quanto pela decisão oficial do município sobre o estabelecimento de alimentos. A rotulagem da própria marca diz que a carne bovina é criada e abatida na UE, portanto não está confirmado que a carne crua em si seja finlandesa.',
      'halti':
        'A Halti é uma marca finlandesa de outdoor fundada em 1976 por Juhani Hyokyvaara, com design feito em sua sede em Sipoo. A marca afirma no próprio site que a produção está distribuída por vários países: China, Vietnã e Bangladesh para o vestuário esportivo técnico, além de fornecedores europeus na Itália, na Ucrânia e na Lituânia. Segundo a própria Halti, apenas as meias e os gorros são feitos na Finlândia, de modo que a marca deve ser descrita como de design finlandês, e não de fabricação finlandesa.',
      'north-outdoor':
        'A North Outdoor é uma marca finlandesa de roupas de lã merino operada pela Pyka Oy, mais conhecida pela malharia que abriu no distrito de Rusko, em Oulu, em 2021, noticiada pela Yle como a maior fábrica de suéteres de lã da Finlândia. A marca divide a produção entre vários países e descreve essa divisão por categoria de produto, e não como uma origem única. Sua própria descrição publicada dessa divisão é internamente contraditória em inglês, portanto o detalhamento por categoria não deve ser repetido como fato estabelecido.',
      'marttiini':
        'A Marttiini é uma marca finlandesa de facas que começou em 1928, quando o ferreiro Janne Marttiini abriu uma oficina de puukko em Rovaniemi. O catálogo atual vai de facas de caça e de filetar a facas de cozinha, canivetes e puukkos tradicionais, com cabos de bétula encaracolada ou chifre de rena e lâminas guardadas em bainhas de couro. O Lapinleuku, de lâmina larga, e as facas de filetar que levaram a marca aos mercados de exportação são seus formatos mais reconhecíveis.',
      'kupilka':
        'A Kupilka é uma marca finlandesa de utensílios de mesa para atividades ao ar livre, tocada pela empresa familiar Plasthill Oy em Kontiolahti, na Carélia do Norte. Seus copos, pratos e talheres são moldados em um compósito próprio de fibra natural, o Kareline, composto de cerca de metade celulose de conífera nórdica e metade poliolefinas de grau alimentício, produzido internamente na unidade de Pyytivaara com eletricidade renovável certificada. A origem dos utensílios de mesa é bem documentada pela marca, mas o catálogo mais amplo (facas e pederneiras em particular) recorre a fornecedores externos.',
      'nordicbuddies':
        'A Nordicbuddies é uma empresa de design finlandesa sediada em Helsinque (registrada como Oy Bisly Ltd) e licenciada oficial de Moomin, Píppi Meialonga e Mauri Kunnas, que vende meias, camisetas, bonés, bolsas e outros acessórios. O trabalho de design é feito em Helsinque, mas a própria página About Us da marca situa a fabricação principalmente na Europa e na Eurásia, com apenas parte da produção na Finlândia, e seu algodão nas regiões de Anhui e Henan, na China. Os dados de origem declarados pelos varejistas apontam para a China no nível do produto, portanto a marca deve ser descrita como de design finlandês, e não de fabricação finlandesa.',
      'marimekko':
        'A Marimekko foi fundada na Finlândia em 1951 e ainda opera sua própria estamparia têxtil em Helsinque, que estampa mais de um milhão de metros de tecido por ano, incluindo todos os tecidos vendidos por metro. Os produtos acabados são costurados por uma rede de fornecedores parceiros, e a Marimekko cita Finlândia, países bálticos, Portugal, China e Tailândia entre seus países de fabricação. Em 2025, 54 por cento dos produtos foram feitos na UE e em outros países europeus, portanto não se pode presumir que um produto Marimekko seja feito na Finlândia sem verificar a peça individual.',
      'rento':
        'A Rento é uma linha de sauna de design finlandês pertencente à empresa familiar Tammer Brands Oy, de Tampere. A marca faz o design na Finlândia e usa amplamente o selo Design from Finland, mas a produção está dividida entre a Finlândia, outros países europeus e fábricas auditadas pelo Amfori BSCI, e o país de origem é definido por produto, e não por marca. Vários itens vendidos como Rento são feitos fora da Finlândia, portanto a origem precisa ser verificada produto a produto.',
      'lapuan-kankurit':
        'A Lapuan Kankurit é uma tecelagem finlandesa cuja fábrica principal fica em Lapua e cujas raízes remontam a 1917. Segundo a própria empresa, 95% de seus produtos são tecidos em Lapua, enquanto o restante é feito em uma fábrica de propriedade parcial em Kaunas, na Lituânia, e por subcontratados europeus. Todas as matérias-primas vêm de fora da Finlândia: linho da França, dos Países Baixos e da Bélgica, mohair da África do Sul.',
      'iittala':
        'A Iittala é uma marca de design finlandesa construída em torno da fábrica de vidro de Iittala, fundada em 1881 no vilarejo de Iittala e hoje parte do Fiskars Group. Sua empresa-mãe descreve a unidade de Hämeenlinna como a única fábrica de vidro ainda em operação na Finlândia, com cerca de 200 funcionários, e a Iittala afirma no próprio site que os vasos de Alvar Aalto e o vidro Ultima Thule são soprados à boca ali. Sua cerâmica, porém, é feita por fabricantes terceirizados no exterior, portanto a alegação de origem finlandesa vale apenas para os artigos de vidro.',
      'arctic-warriors':
        'A Arctic Warriors é uma pequena empresa finlandesa de produtos naturais registrada no vilarejo de Narkaus, perto de Rovaniemi, na Lapônia, fundada em 2014. Vende pós de frutos silvestres e de ervas e elixires de ervas à base de glicerol feitos com ervas e frutos lapões obtidos de pequenos produtores e coletores locais. Suas próprias páginas de produto indicam a Finlândia como origem, mas não informam um local de produção ou de embalagem.',
      'makia':
        'A Makia é uma empresa de roupas sediada em Helsinque, fundada em 2001, que faz o design na Finlândia e fabrica no exterior. Suas próprias páginas apontam a Türkiye como principal país de produção, com jaquetas e a maioria dos acessórios vindos da China, meias de Portugal e da Türkiye, e uma pequena parte dos acessórios de lã feita na Finlândia. No entanto, as páginas da própria marca divergem entre si quanto à lista completa de países, portanto nenhum detalhamento preciso de origem por categoria pode ser dado como verificado.',
      'pentik':
        'A Pentik é uma marca finlandesa de artigos para a casa que começou em Posio em 1971 e ainda mantém ali uma fábrica de cerâmica e uma oficina de velas anexa. A fábrica não cobre toda a linha, porém: segundo os próprios relatórios de sustentabilidade da marca, cerca de um quarto de seus produtos foi feito na Finlândia em 2022, e o restante veio de outros lugares da Europa e da Ásia. A Pentik afirmou que não destaca o país de fabricação em seus produtos.',
      'arabia':
        'A Arabia é uma marca finlandesa de cerâmica e artigos de mesa enraizada no bairro Arabianranta, em Helsinque, e hoje pertencente ao Fiskars Group. Sua fábrica de cerâmica em Helsinque parou de produzir na primavera de 2016, e a Fiskars afirma nas próprias páginas da marca que os produtos Arabia vêm agora de fabricantes terceirizados de longo prazo, principalmente na Tailândia e na Romênia. O design e o desenvolvimento de produto continuam acontecendo na Finlândia, e o bairro Arabia, em Helsinque, segue como museu, loja e centro de design.',
      'fazer':
        'A Fazer é uma empresa finlandesa de alimentos fundada em Helsinque em 1891, mais conhecida pelo chocolate ao leite Karl Fazer, pelo Geisha e pelo Marianne. Além dos confeitos, o grupo opera negócios de panificação, moagem e restaurantes em vários países. Sua estrutura de produção está mudando no momento: uma nova fábrica de chocolate está sendo construída em Lahti e, no verão de 2026, a Fazer comprou fábricas de confeitos na Suécia.',
      'moomin':
        'A Moomin Characters Oy Ltd é a empresa familiar de Helsinque que detém e supervisiona os direitos sobre os personagens Moomin de Tove Jansson, que apareceram pela primeira vez no livro de 1945 The Moomins and the Great Flood. A empresa parou de fabricar produtos por conta própria há décadas: todo item vendido como produto Moomin vem de um licenciado, e a rede chega a mais de 800 deles no mundo todo. No lado dos presentes, a linha mais reconhecível são as canecas de cerâmica Moomin da Arabia, uma série que começou em 1990 e hoje reúne mais de cem modelos.',
      'wild-about-lapland':
        'A Wild About Lapland é uma operadora de atividades sediada em Rovaniemi, com escritório na Rovakatu 24. Cada passeio tem no máximo oito participantes, e a programação funciona o ano todo: saídas para ver a aurora boreal, safáris de snowmobile e visitas a renas e huskies no inverno, canoagem e caminhadas no verão. O fundador e guia principal, Theo Turner, é ex-comando dos Royal Marines e instrutor de atividades ao ar livre, e a empresa tem o selo Sustainable Travel Finland.',
      'meritalo':
        'A Meritalo é uma processadora familiar finlandesa de frutas silvestres fundada em 1995 por Susanna e Olavi Lindstedt, que se mudaram de Helsinki para Ylonkyla, na região de Salo, no sudoeste da Finlândia. A empresa afirma que todos os seus produtos são feitos nas próprias instalações ali, com 100% de frutas silvestres e frutas finlandesas compradas de produtores finlandeses e colhidas em florestas da Finlândia. A linha se concentra em geleias e compotas, sucos e seiva de bétula, e inclui uma geleia de espinheiro-marítimo de 310 g ao lado de produtos de morango, airela e maçã.',
      'nordqvist':
        'A Nordqvist é uma empresa finlandesa de chá fundada em 1979, que começou como uma loja em Helsinki vendendo chás aromatizados e a granel e depois passou à importação e ao atacado. Seus chás são aromatizados e embalados na fábrica própria da empresa em Nurmijärvi, de 3.000 metros quadrados, inaugurada em 2018. A linha abrange misturas antigas como Keisarin Morsian e Tiikerin Päiväuni, além de uma linha de chás com tema dos Mumins vendida em sachês, folhas soltas e latas.',
      'puhdistamo':
        'A Puhdistamo é uma marca finlandesa de bem-estar fundada em 2009 que vende vitaminas, minerais e outros suplementos, além de bebidas energéticas, kombucha, barras de proteína e de chocolate cru e superalimentos. A empresa opera sua própria fábrica em Lempäälä, na Finlândia, onde produz a maior parte de seus suplementos e informa ter produzido mais de 80 milhões de cápsulas em um único ano. A fábrica tem a certificação de segurança alimentar FSSC 22000, e a empresa afirma que suas bebidas são adoçadas com estévia ou açúcar de cana orgânico em vez de aspartame, acessulfame K ou sucralose.',
      'emendo':
        'A Emendo Oy é uma empresa finlandesa de sauna e bem-estar sediada em Vaasa, que afirma no próprio site ter sido fundada em 1986. Sua linha abrange fragrâncias para sauna e para o loyly, méis de sauna, têxteis de sauna em linho e algodão, conchas, sabonetes e produtos de cuidado da pele, vendidos sob dois nomes, Emendo e KOLO Sauna. A empresa diz fabricar na Finlândia suas fragrâncias, méis de sauna e produtos de cuidado para rosto, corpo e pés, e seus artigos de sauna dos Mumins são licenciados pela Moomin Characters e baseados nos desenhos originais de Tove Jansson.',
      'moomin-arabia':
        'Moomin Arabia é a linha dos Mumins da marca finlandesa de cerâmica Arabia, fundada em 1873 e hoje parte do Fiskars Group. As primeiras louças dos Mumins surgiram nos anos 1950 com ilustrações de Tove Jansson, e a série de canecas muito colecionada começou nos anos 1990 usando o formato Teema, de Kaj Franck. O trabalho de design é feito na sede da empresa em Espoo, na Finlândia, enquanto o Fiskars Group afirma que os produtos Arabia são fabricados por terceiros principalmente na Tailândia e na Romênia.',
      'kaino-drinks':
        'KAINO Drinks é uma linha de bebidas gaseificadas sem álcool da Poikain Parhaat Oy, uma empresa de alimentos sediada em Tampere, na Finlândia. A bebida de brotos de abeto é feita à mão em Tampere com brotos de abeto finlandeses, e as bebidas têm 0,0% de álcool, são veganas e certificadas como orgânicas sob o código FI-EKO-201. A linha abrange brotos de abeto, ruibarbo e rosa, e folha de groselha-preta, vendidas em garrafas de 0,75 litro e 0,2 litro.',
      'omega7':
        'Omega7 é uma marca finlandesa de suplementos de óleo de espinheiro-marítimo cujos primeiros produtos chegaram ao mercado em 1997. Seu óleo duplo de espinheiro-marítimo SBA24 combina óleo da baga e óleo da semente, e é extraído por um processo sem solventes na fábrica da empresa em Tornio. A fabricante, Aromtech Oy, realizou estudos clínicos com pesquisadores e médicos da Universidade de Turku e do Hospital Universitário de Turku, e mantém um projeto-piloto de cultivo orgânico de espinheiro-marítimo em Tervola, na Lapônia.',
      'kaapa-mushrooms':
        'KÄÄPÄ Mushrooms é uma produtora finlandesa de cogumelos funcionais fundada em 2018 por Eric Puro, Otso Mursula e Seppo Riikonen. Sua sede e unidade de produção ficam em Karjalohja, no sul da Finlândia, onde os cogumelos são cultivados em substrato de bétula de florestas finlandesas certificadas FSC e PEFC e extraídos com o método ultrassônico próprio da empresa, o NordRelease, com água de nascente purificada. A empresa tem a certificação de segurança alimentar FSSC 22000, faz seus extratos a partir dos corpos de frutificação e não de grãos miceliados, e mantém uma rede de cultivo de chaga em floresta por meio de sua divisão KÄÄPÄ Forest.',
      'halva':
        'A Halva é uma empresa familiar finlandesa de confeitaria fundada em 1931 pelos irmãos Jean e Michael Karavokyros, que haviam se mudado da Grécia para a Finlândia. É mais conhecida por seus doces de alcaçuz e salmiakki, e a empresa afirma que sua fábrica de balas e sua unidade de embalagem ficam em Pitajanmaki, em Helsinki. O negócio é hoje conduzido pela terceira geração, e a halva de pasta de gergelim que deu nome à empresa segue na linha.',
      'kilpissafarit':
        'Kilpissafarit é uma empresa de serviços de programas em Kilpisjarvi, fundada em 1995 pelo guarda de fronteira Hannu Rauhala e hoje dirigida por seu filho, Jussi Rauhala. Ela guia safáris de snowmobile, saídas de raquetes de neve e caminhadas, passeios para ver a aurora boreal e pescarias na região selvagem de Kasivarsi, incluindo uma rota de snowmobile até o Halti, o ponto mais alto da Finlândia. A mesma base aluga snowmobiles, fatbikes elétricas, raquetes de neve, canoas e caiaques para quem sai por conta própria.',
      'kaavi-porcini':
        'Kaavi Porcini é a marca da Kaavin Herkkutattitehdas Oy, uma empresa finlandesa que seca cogumelos silvestres na própria fábrica em Tohmajärvi. Os cogumelos são colhidos nas florestas de Savo do Norte e da Carélia do Norte e secados no mesmo dia da colheita. A linha abrange porcini, cantarelo, cantarelo-de-funil e trombeta-dos-mortos, além de chaga colhida em Kittilä e um pó de porcini usado como tempero.',
      'tammer':
        'A Tammer Brands é uma empresa familiar de Tampere, fundada em 1954 como Tammer-Tukku e rebatizada como Tammer Brands Oy em 2019. Ela desenvolve e distribui produtos de consumo para casa, jardim e lazer sob um portfólio de mais de 50 marcas, entre elas a linha de sauna Rento, a marca de churrasco Mustang e a Maku Kitchen Life. Para a Rento, a empresa afirma que os produtos são feitos na Finlândia, em outros países da Europa ou em fábricas auditadas pela amfori BSCI, com o país de fabricação indicado em cada ficha de produto.',
      'finlayson':
        'A Finlayson tem seu início em 1820, quando o escocês James Finlayson montou uma oficina mecânica junto às corredeiras de Tammerkoski, em Tampere. A fiação de algodão que cresceu ao redor tornou-se o maior empregador privado da Finlândia em 1975, com 11 fábricas e 6.500 trabalhadores, e a empresa segue conhecida por nomes familiares como o padrão Elefantti, desenhado por Laina Koskela em 1969, e por ter colocado a capa de edredom no mercado finlandês em 1963. Hoje a Finlayson vende roupa de cama, toalhas, têxteis de cozinha e tapetes, publica sua lista de fábricas e tece na Finlândia seus tapetes Rasypala a partir de lençóis devolvidos pelos clientes.',
      'finnish-flavours':
        'Finnish Flavours é uma marca finlandesa de alimentos administrada a partir de Kerava. Sua linha se concentra no alcaçuz em duas versões, os pedaços Premium Palalaku e o Premium Chocolaku coberto de chocolate, ao lado de geleias de airela, mirtilo e amora-ártica, truta arco-íris finlandesa e carne de rena seca. A marca afirma que suas geleias são feitas na Finlândia inteiramente com frutas silvestres do país, e seus revendedores listados vão de lojas K finlandesas e uma loja em Rovaniemi a importadores nos Estados Unidos, Canadá, Suíça, Reino Unido e Nova Zelândia.',
      'aurora-borealis':
        'Aurora Borealis é uma marca própria da Tammer Brands Oy, empresa familiar finlandesa de marcas e atacado com sede em Tampere, cujas raízes remontam a 1954. A linha abrange peças decorativas, itens do dia a dia, acessórios e bandeiras construídos em torno de motivos da natureza finlandesa: florestas, renas, huskies, a aurora boreal e a bandeira da Finlândia. Entre os produtos vendidos sob esse nome estão copos kuksa de madeira, renas e huskies de pelúcia, canecas, sacolas e baralhos.',
      'fiskars':
        'A Fiskars começou em 1649, quando Peter Thorwöste recebeu autorização para montar um alto-forno e uma ferraria em uma aldeia finlandesa de mesmo nome. A marca é mais conhecida por suas tesouras de cabo laranja, lançadas em 1967 como as primeiras tesouras com cabo de plástico; o modelo Classic ainda é feito na fábrica da empresa em Billnäs, na Finlândia, e cada par é testado à mão. Além das tesouras, a Fiskars vende ferramentas de jardim, machados e facas de cozinha.',
      'arctic-power-berries':
        'Arctic Power Berries é uma marca de pós de frutas silvestres tocada por Anna e Eveliina, duas amigas de infância de Rovaniemi, na Lapônia finlandesa, que começaram o negócio depois de se mudarem para Londres. A linha é de pós de uma única fruta em sachês de 70 g: mirtilo (mirtilo silvestre), airela, espinheiro-marítimo, groselha-preta, cranberry, morango e framboesa, além de uma mistura de frutas. A empresa diz que as frutas silvestres são colhidas à mão na Finlândia, secas com cuidado e moídas, com cerca de 700 g de frutas frescas por trás de cada sachê de 70 g e nada mais adicionado.',
      'golden-crown-levin-iglut':
        'Levin Iglut Golden Crown é um resort familiar de iglus de vidro no monte Utsuvaara, ao lado de Levi, na Lapônia finlandesa. Tauno Mäkelä construiu os quatro primeiros iglus em 2008, e o local tem hoje 27 iglus de vidro, a villa Northern Lights House para seis pessoas e seu próprio Restaurant Utsu, aberto do fim de agosto ao início de abril. Para quem procura presentes, os itens relevantes são os vale-presentes para estadias em iglu e jantares no Utsu, e a Golden Crown Shop na recepção, que vende marcas finlandesas de design e artesanato.',
      'sisu':
        'Sisu é uma marca finlandesa de pastilhas lançada em 1928. A receita foi desenvolvida pelo químico Johan Ponkamo no porão da fábrica de doces Seres, em Turku, e a pastilha é feita sobre uma base de goma arábica com sabor de salmiakki. A marca hoje faz parte do portfólio da Cloetta e abrange pastilhas de salmiakki, mentol e alcaçuz, versões sem açúcar e com xilitol e, desde 2022, também sacos de balas.',
      'kultakuume-com':
        'Kultakuume é um negócio familiar em Saariselkä, na Lapônia finlandesa, que diz atuar na região desde 2008 e alugar cabanas desde 2009. A empresa vende dias guiados de garimpo de ouro em sua própria concessão, onde os visitantes aprendem a bateia manual, acompanham a lavagem mecanizada e ficam com todo o ouro que encontrarem. Além dos passeios, aluga as cabanas de madeira Kultakelo em Kaunispää e vende um conjunto de 18 impressões em tela com temas de garimpo de ouro, cada uma de 100 x 100 cm.',
      'muurla':
        'Muurla é uma empresa finlandesa de design cuja história começou em uma fábrica de vidro em Muurla, no sudoeste da Finlândia, onde a loja da fábrica abriu na primavera de 1974. Hoje é conhecida por canecas e louças esmaltadas, artigos de vidro e tábuas de servir em lâmina de bétula, e por sua coleção licenciada dos Mumins. A Muurla diz que todos os seus produtos são desenhados na Finlândia, enquanto o país de fabricação varia por produto: os itens de lâmina de bétula são feitos na Finlândia, a maior parte dos esmaltados na Europa, e o vidro na Europa e na Ásia.',
      'novita':
        'A Novita é uma empresa finlandesa de fios fundada em 1928 por Ernst Gylfe, que aprendeu a fiação de lã penteada em Bradford, na Inglaterra, antes de iniciar a produção em Helsinki. O negócio segue sob propriedade familiar na quarta geração e mantém sua fiação em Koria, Kouvola, desde 1974, onde diz produzir cerca de um milhão de quilos de fio por ano. Seu produto mais conhecido é o fio para meias 7 Veljestä, fiado a partir de lã que a empresa informa comprar principalmente na Europa, sobretudo na Inglaterra.',
      'mikebon':
        'A Mikebon Oy é uma empresa familiar de estamparia e bordado têxtil fundada em 1994 e sediada em Petikko, Vantaa. Ela cuida internamente do design, da execução gráfica, da produção e da logística, e afirma no próprio site que a produção acontece na Finlândia. Seus principais clientes são lojas de souvenires e presentes, e ela também mantém uma loja online para consumidores cujas linhas incluem camisetas e moletons com temas da Lapônia, da Finlândia e dos Mumins.',
      'aromageddon':
        'Aromageddon é uma linha de aromas para sauna da Aromageddon Oy, empresa registrada em Helsinki, que situa a origem da ideia em uma sessão de sauna no verão de 2024. A linha tem seis aromas de 15 ml a 7,90 euros cada, mais três kits de presente, e os temas vêm de bebidas e doces em vez de floresta ou bétula: uísque, cerveja, menta gelada, bala de hortelã-pimenta, canela e cacau com menta. A empresa publica no próprio site uma ficha de dados de segurança CLP para cada aroma, e as versões com tema de bebida trazem a nota de sabor sem álcool.',
      'leijona':
        'Leijona é uma marca finlandesa de pastilhas da Cloetta, mais conhecida pela Leijona Tervalakritsi, uma pastilha de alcaçuz com cobertura de açúcar e sabor de alcatrão. Foi desenvolvida pelo farmacêutico Yrjö Jalander, fundador da empresa de doces Merijal, de Oulu, e chegou ao mercado em 1933. Além das caixas de pastilhas de 32 g, a linha atual inclui sacos de balas de 180 g, e a marca é gerida pela Cloetta Suomi Oy, de Turku.',
    },
  },
  ja: {
    eyebrow: 'ブランド',
    founded: (y) => `${y} 年創業`,
    officialSite: (n) => `${n} の公式サイト`,
    productsH2: (n) => `この店の ${n}`,
    indexH1: '取り扱いブランド',
    indexIntro:
      'この店のものを誰がどこで作っているか。各紹介はブランド自身が公表している内容にもとづき、公式サイトへリンクしています。',
    indexCount: (n) => `商品 ${n} 点`,
    profile: {
      'aarikka':
        'Aarikkaは1954年にKaija AarikkaとErkki Ruokonenが創業したフィンランドのデザインハウスで、木製ビーズとジュエリーで知られ、2017年からMartinex Oyが所有している。同ブランドはデザインと、木製ジュエリーおよび木製ホーム用品の手作業による組み立てをフィンランドで行うとしているが、全製品がフィンランド製のシリーズだとは称していない。衣料品には製品ごとにフィンランド国外の製造国が明記されており、原材料の一部は海外から調達されている。',
      'foodin':
        'FoodinはユヴァスキュラのVaajakoskiを拠点とするフィンランドの家族経営オーガニック食品会社で、輸入だけでなく製造も行っていると自ら説明している。ローチョコレート製品は同社自身のVaajakoski工場で石臼挽きされ、手作業で仕上げられており、カカオはペルーのアマゾンで栽培されたクリオロ種の豆を使用している。同じ工場は同社のプロテインバーの生産拠点としても挙げられている。',
      'kuivalihakundi':
        'Kuivalihakundi（Dried Buddy Oy）はフィンランドのジャーキーメーカーで、TuusulaのJokelaにある自社の認可食肉施設で肉の乾燥、カット、包装を行っている。約1,500平方メートルの施設で、2023年末に移転した。製造場所はブランド自身のページと自治体の公式な食品施設決定の両方で裏付けられている。ブランド自身の表示によれば牛肉はEU域内で飼育・と畜されており、原料肉そのものがフィンランド産であることは確認されていない。',
      'halti':
        'Haltiは1976年にJuhani Hyokyvaaraが創業したフィンランドのアウトドアブランドで、デザインはSipooの本社で行われている。同ブランドは自社サイトで、生産が複数の国に分散していると述べている。技術的なスポーツウェアは中国、ベトナム、バングラデシュ、加えてイタリア、ウクライナ、リトアニアの欧州サプライヤーである。Halti自身の説明では、フィンランドで作られているのは靴下とニット帽だけであり、したがって同ブランドはフィンランド製ではなく、フィンランドでデザインされたブランドと表現すべきである。',
      'north-outdoor':
        'North OutdoorはPyka Oyが運営するフィンランドのメリノウール衣料ブランドで、2021年にオウルのRusko地区に開設した編み工場で最もよく知られている。Yleはこれをフィンランド最大のウールセーター工場と報じた。同ブランドは生産を複数の国に分けており、その分担を単一の原産地ではなく製品カテゴリー別に説明している。ただし、その分担についてブランドが公表している英語の説明は内部で矛盾しているため、カテゴリー別の内訳を確定した事実として繰り返すべきではない。',
      'marttiini':
        'Marttiiniは1928年、鍛冶職人のJanne Marttiiniがロヴァニエミにプーッコ工房を開いたことに始まるフィンランドのナイフブランドである。現在のカタログはハンティングナイフやフィレナイフから、キッチンナイフ、折りたたみナイフ、伝統的なプーッコまで幅広く、柄はカーリーバーチまたはトナカイの角、刃は革のシースに収められる。幅広の刃のLapinleukuと、ブランドを輸出市場へ導いたフィレナイフが、最も見分けやすい形である。',
      'kupilka':
        'Kupilkaは北カレリアのKontiolahtiで家族経営企業Plasthill Oyが運営するフィンランドのアウトドア食器ブランドである。カップ、皿、カトラリーは独自のKareline天然繊維コンポジット（およそ半分が北欧の針葉樹セルロース、半分が食品グレードのポリオレフィン）から成形され、認証された再生可能電力を使ってPyytivaaraの拠点で自社生産されている。食器の原産地はブランドによって十分に文書化されているが、より広いカタログ、特にナイフとファイヤースチールは外部サプライヤーに依存している。',
      'nordicbuddies':
        'Nordicbuddiesはヘルシンキを拠点とするフィンランドのデザイン会社（登記名Oy Bisly Ltd）で、ムーミン、長くつ下のピッピ、Mauri Kunnasの公式ライセンシーとして、靴下、シャツ、キャップ、バッグなどのアクセサリーを販売している。デザイン作業はヘルシンキで行われるが、ブランド自身のAbout Usページは製造を主に欧州とユーラシアに置き、フィンランドでの生産は一部のみとしており、綿は中国の安徽省と河南省としている。小売業者が申告する原産地データは製品レベルで中国を示しているため、同ブランドはフィンランド製ではなく、フィンランドでデザインされたブランドと表現すべきである。',
      'marimekko':
        'Marimekkoは1951年にフィンランドで創業し、現在もヘルシンキで自社のテキスタイルプリント工場を運営しており、年間100万メートルを超える生地をプリントしている。メートル単位で販売される生地はすべてここでプリントされる。完成品そのものはパートナーサプライヤーのネットワークが縫製しており、Marimekkoは製造国としてフィンランド、バルト諸国、ポルトガル、中国、タイを挙げている。2025年には製品の54パーセントがEUおよびその他の欧州諸国で作られたため、個々の商品を確認せずにMarimekko製品がフィンランド製だと決めつけることはできない。',
      'rento':
        'Rentoはタンペレの家族経営企業Tammer Brands Oyが所有する、フィンランドでデザインされたサウナ用品シリーズである。同ブランドはフィンランドでデザインを行い、Design from Finlandマークを広く付けているが、生産はフィンランド、その他の欧州諸国、およびAmfori BSCIの監査を受けた工場に分かれており、原産国はブランド単位ではなく製品ごとに決まる。Rentoとして販売される複数の商品はフィンランド国外で作られているため、原産地は製品ごとに確認する必要がある。',
      'lapuan-kankurit':
        'Lapuan Kankuritはフィンランドの織物会社で、主力の工場はLapuaにあり、そのルーツは1917年にさかのぼる。同社自身の説明では製品の95%をLapuaで織っており、残りはリトアニアのカウナスにある一部出資の工場と、欧州の下請け業者が製造している。原材料はすべてフィンランド国外を原産とし、亜麻はフランス、オランダ、ベルギーから、モヘアは南アフリカからである。',
      'iittala':
        'Iittalaは1881年にIittala村に創業したイッタラガラス工場を核とするフィンランドのデザインブランドで、現在はFiskars Groupの一部である。親会社はハメーンリンナの拠点をフィンランドで今も操業している唯一のガラス工場と説明し、約200人を雇用しているとしている。Iittalaは自社サイトで、Alvar Aaltoのベースとウルティマ・トゥーレ（Ultima Thule）のガラスがそこで宙吹きされていると述べている。一方、陶器は海外の委託製造業者が作っているため、フィンランド原産という主張はガラス製品にのみ当てはまる。',
      'arctic-warriors':
        'Arctic Warriorsは2014年に創業した小規模なフィンランドの自然製品会社で、ラップランドのロヴァニエミ近郊のNarkaus村に登記されている。ラップランドのハーブとベリーから作るベリー・ハーブパウダーやグリセリンベースのハーブエリキシルを販売しており、原料は地元の小規模生産者や採取者から調達している。自社の製品ページは原産地をフィンランドと記載しているが、生産地や包装地は明記していない。',
      'makia':
        'Makiaは2001年に創業したヘルシンキ拠点の衣料会社で、フィンランドでデザインし、海外で製造している。自社ページでは主な生産国をトルコとし、ジャケットと大半のアクセサリーは中国、靴下はポルトガルとトルコ、ウール製アクセサリーの一部はフィンランド製としている。ただし、ブランド自身のページどうしで国のリスト全体が食い違っているため、カテゴリー別の正確な原産地の内訳を検証済みとして述べることはできない。',
      'pentik':
        'Pentikは1971年にPosioで始まったフィンランドのホームウェアブランドで、現在も同地でセラミック工場と隣接するキャンドル工房を運営している。ただし工場が全製品をカバーしているわけではない。ブランド自身のサステナビリティ報告によれば、2022年にフィンランドで作られたのは製品の約4分の1で、残りは欧州とアジアの他地域から調達されている。Pentikは製品に製造国を強調していないと述べている。',
      'arabia':
        'ArabiaはヘルシンキのArabianranta地区に根ざしたフィンランドの陶磁器・食器ブランドで、現在はFiskars Groupが所有している。ヘルシンキの陶器工場は2016年春に生産を停止し、Fiskarsは自社のブランドページで、Arabia製品は現在、主にタイとルーマニアの長期契約製造業者から来ていると述べている。デザインと製品開発は今もフィンランドで行われており、ヘルシンキのArabia地区は美術館、店舗、デザインセンターとして続いている。',
      'fazer':
        'Fazerは1891年にヘルシンキで創業したフィンランドの食品会社で、Karl Fazerのミルクチョコレート、Geisha、Marianneで最もよく知られている。菓子以外にも、グループは複数の国でベーカリー、製粉、レストラン事業を営んでいる。生産体制は現在変化しつつあり、ラハティに新しいチョコレート工場が建設中で、2026年夏にはFazerがスウェーデンの菓子工場を買収した。',
      'moomin':
        'Moomin Characters Oy Ltdは、Tove Janssonのムーミンのキャラクターの権利を所有・管理するヘルシンキの家族経営会社である。ムーミンは1945年の書籍『小さなトロールと大きな洪水』で初めて登場した。同社は数十年前に自社での商品製造をやめており、ムーミン製品として販売されるすべての商品はライセンシーによるもので、そのネットワークは世界で800社を超える。ギフト分野で最も広く知られているのはArabiaの陶製ムーミンマグで、1990年に始まり、現在では100を超えるデザインがある。',
      'wild-about-lapland':
        'Wild About Lapland はロヴァニエミを拠点とするアクティビティ事業者で、オフィスは Rovakatu 24 にあります。すべてのツアーは参加者8名までに制限され、プログラムは通年で運営されています。冬はオーロラツアー、スノーモービルサファリ、トナカイとハスキーの訪問、夏はカヌーとハイキングです。創業者でメインガイドの Theo Turner は元英国海兵隊コマンドーでアウトドアインストラクターであり、同社は Sustainable Travel Finland ラベルを取得しています。',
      'meritalo':
        'Meritalo は1995年に Susanna と Olavi Lindstedt が創業したフィンランドの家族経営のベリー加工会社で、二人はヘルシンキから南西フィンランド・サロ地域のユロンキュラへ移り住みました。同社によれば、製品はすべて現地の自社施設で作られ、フィンランドの生産者から購入しフィンランドの森で摘まれた100%フィンランド産のベリーと果物を使っています。製品はジャムとゼリー、ジュース、白樺樹液が中心で、310 g のシーバックソーンジャムのほか、いちご、リンゴンベリー、りんごの製品があります。',
      'nordqvist':
        'Nordqvist は1979年創業のフィンランドの紅茶会社で、フレーバーティーとリーフティーを売るヘルシンキの店として始まり、のちに輸入と卸売へ広がりました。紅茶の着香と包装は、2018年に開設されたヌルミヤルヴィの3,000平方メートルの自社工場で行われています。製品には Keisarin Morsian や Tiikerin Päiväuni といった長く続くブレンドのほか、ティーバッグ、リーフ、缶入りで売られるムーミンをテーマにした紅茶シリーズがあります。',
      'puhdistamo':
        'Puhdistamo は2009年創業のフィンランドのウェルネスブランドで、ビタミンやミネラルなどのサプリメントに加え、エナジードリンク、コンブチャ、プロテインとローチョコレートのバー、スーパーフードを販売しています。同社はフィンランドのレンパーラに自社工場を持ち、サプリメントの大半をそこで製造しており、1年間で8,000万カプセル以上を生産したと報告しています。工場は FSSC 22000 の食品安全認証を取得しており、同社は、飲料の甘味料にアスパルテーム、アセスルファムK、スクラロースではなくステビアまたはオーガニックのサトウキビ糖を使っているとしています。',
      'emendo':
        'Emendo Oy はヴァーサを拠点とするフィンランドのサウナ・ウェルネス企業で、自社サイトでは1986年創業としています。製品はサウナとロウリュの香り、サウナハニー、リネンコットンのサウナテキスタイル、柄杓、石けん、スキンケア用品で、Emendo と KOLO Sauna の2つの名前で販売されています。同社によれば、香り製品、サウナハニー、顔・体・足のケア用品はフィンランドで製造しており、ムーミンのサウナ用品は Moomin Characters のライセンスに基づき、Tove Jansson のオリジナルの絵をもとにしています。',
      'moomin-arabia':
        'Moomin Arabia は、1873年創業で現在は Fiskars Group に属するフィンランドの陶磁器ブランド Arabia のムーミンシリーズです。最初のムーミンの食器は1950年代に Tove Jansson のイラストで登場し、広く集められているマグカップのシリーズは1990年代に Kaj Franck の Teema の形を使って始まりました。デザインはフィンランド・エスポーの本社で行われており、一方で Fiskars Group は、Arabia の製品が主にタイとルーマニアの委託製造先で作られているとしています。',
      'kaino-drinks':
        'KAINO Drinks は、フィンランド・タンペレを拠点とする食品会社 Poikain Parhaat Oy のノンアルコール炭酸飲料のシリーズです。トウヒの新芽の飲料はフィンランド産のトウヒの新芽からタンペレで手作りされ、アルコール分0.0%、ヴィーガン対応で、FI-EKO-201 のオーガニック認証を受けています。ラインナップはトウヒの新芽、ルバーブとローズ、クロスグリの葉で、0.75リットルと0.2リットルのボトルで販売されています。',
      'omega7':
        'Omega7 はフィンランドのシーバックソーンオイルのサプリメントブランドで、最初の製品は1997年に市場に出ました。SBA24 ダブルシーバックソーンオイルは果実の油と種子の油を組み合わせたもので、トルニオの自社工場で溶剤を使わない方法により抽出されています。製造元の Aromtech Oy は、トゥルク大学とトゥルク大学病院の研究者や医師と臨床研究を行っており、ラップランドのテルヴォラでオーガニックのシーバックソーン栽培の試験を進めています。',
      'kaapa-mushrooms':
        'KÄÄPÄ Mushrooms は2018年に Eric Puro、Otso Mursula、Seppo Riikonen が創業したフィンランドの機能性きのこの生産者です。本社と生産施設は南フィンランドのカルヤロヒヤにあり、きのこは FSC および PEFC 認証のフィンランドの森から取れた白樺の培地で育てられ、同社独自の NordRelease 超音波法と精製した湧き水で抽出されます。同社は FSSC 22000 の食品安全認証を取得し、抽出物は菌糸を回した穀物ではなく子実体から作っており、KÄÄPÄ Forest 部門を通じて森でのチャーガ栽培のネットワークを運営しています。',
      'halva':
        'Halva は1931年に、ギリシャからフィンランドへ移ってきた Jean と Michael Karavokyros の兄弟が創業したフィンランドの家族経営の菓子会社です。リコリスとサルミアッキの菓子でよく知られており、同社によれば、キャンディ工場と包装工場はヘルシンキのピタヤンマキにあります。事業は現在3代目が担っており、社名の由来となったごまペーストのハルヴァも今も製品に残っています。',
      'kilpissafarit':
        'Kilpissafarit はキルピスヤルヴィのプログラムサービス会社で、1995年に国境警備隊員の Hannu Rauhala が創業し、現在は息子の Jussi Rauhala が運営しています。カシヴァルシの原野でスノーモービルサファリ、スノーシューとハイキングのツアー、オーロラ観賞、釣りのツアーをガイドしており、フィンランドの最高地点ハルティへ向かうスノーモービルルートもあります。同じ拠点では、自分たちで出かける人のためにスノーモービル、電動ファットバイク、スノーシュー、カヌー、カヤックのレンタルも行っています。',
      'kaavi-porcini':
        'Kaavi Porcini は、トフマヤルヴィの自社工場で野生のきのこを乾燥させるフィンランド企業 Kaavin Herkkutattitehdas Oy のブランドです。きのこは北サヴォと北カレリアの森で採取され、摘んだその日に乾燥されます。品目はポルチーニ、アンズタケ、ミキイロウスタケ、クロラッパタケのほか、キッティラで採れたチャーガと、調味料として使うポルチーニパウダーがあります。',
      'tammer':
        'Tammer Brands はタンペレの家族経営企業で、1954年に Tammer-Tukku として創業し、2019年に Tammer Brands Oy へ社名を変更しました。住まい、庭、レジャー向けの消費者向け製品を50を超えるブランドのポートフォリオで開発・販売しており、その中にはサウナ用品の Rento、グリル製品の Mustang、Maku Kitchen Life があります。Rento について同社は、製品はフィンランド、ヨーロッパの他の国、または amfori BSCI の監査を受けた工場で作られており、製造国は各製品ページに記載しているとしています。',
      'finlayson':
        'Finlayson の始まりは1820年、スコットランド出身の James Finlayson がタンペレのタンメルコスキの急流のそばに機械工房を開いたことにさかのぼります。その周りに育った綿工場は1975年までにフィンランド最大の民間雇用主となり、工場11か所、従業員6,500人を数えました。同社は、Laina Koskela が1969年にデザインした Elefantti の柄のようによく知られた製品や、1963年にフィンランド市場へ掛け布団カバーを持ち込んだことで今も知られています。現在の Finlayson はベッドリネン、タオル、キッチンテキスタイル、ラグを販売し、工場のリストを公開し、Rasypala のラグを顧客から返却されたシーツを使ってフィンランドで織っています。',
      'finnish-flavours':
        'Finnish Flavours はケラヴァから運営されているフィンランドの食品ブランドです。中心はリコリスで、Premium Palalaku のピースとチョコレートをかけた Premium Chocolaku の2つのラインがあり、そのほかリンゴンベリー、ブルーベリー、クラウドベリーのジャム、フィンランド産のニジマス、乾燥トナカイ肉があります。同ブランドによれば、ジャムはすべて国産のベリーだけを使ってフィンランドで作られています。掲載されている販売先は、フィンランドの K ストアやロヴァニエミの店から、アメリカ、カナダ、スイス、イギリス、ニュージーランドの輸入業者まで及びます。',
      'aurora-borealis':
        'Aurora Borealis は、タンペレに本社を置き1954年にさかのぼる家族経営のフィンランドのブランド・卸売企業 Tammer Brands Oy の自社ブランドです。製品は、森、トナカイ、ハスキー、オーロラ、フィンランド国旗といったフィンランドの自然のモチーフを軸にした装飾品、日用品、雑貨、旗です。この名前で扱われている品目には、木製のククサ、トナカイやハスキーのぬいぐるみ、マグカップ、トートバッグ、トランプがあります。',
      'fiskars':
        'Fiskars は1649年、Peter Thorwöste が同じ名前のフィンランドの村に高炉と鍛冶場を設ける許可を得たことに始まります。ブランドとしてよく知られているのはオレンジ色の柄のはさみで、1967年にプラスチックの柄を持つ初のはさみとして発売されました。Classic モデルは今もフィンランドのビルネス工場で作られ、すべて手作業で検査されています。はさみのほか、Fiskars は園芸用具、斧、キッチンナイフを販売しています。',
      'arctic-power-berries':
        'Arctic Power Berries は、フィンランド・ラップランドのロヴァニエミ出身の幼なじみ Anna と Eveliina が、ロンドンへ移ったのちに始めたベリーパウダーのブランドです。製品は70gパウチの単一ベリーのパウダーで、ブルーベリー（ビルベリー）、リンゴンベリー、シーバックソーン、クロスグリ、クランベリー、いちご、ラズベリーと、ミックスベリーのブレンドがあります。同社によれば、野生のベリーはフィンランドで手摘みされ、穏やかに乾燥させて挽いており、70gのパウチ1つあたり生のベリー約700g分で、ほかには何も加えていません。',
      'golden-crown-levin-iglut':
        'Levin Iglut Golden Crown は、フィンランド・ラップランドのレヴィに隣接するウツヴァーラの丘にある家族経営のガラスイグルーのリゾートです。Tauno Mäkelä が2008年に最初の4棟のイグルーを建て、現在はガラスイグルー27棟、6人用のヴィラ Northern Lights House、そして自社の Restaurant Utsu があり、8月下旬から4月上旬まで営業しています。ギフトを探す人にとって関係があるのは、イグルー宿泊と Utsu のディナーのギフトカード、そしてフィンランドのデザインとクラフトのブランドを扱うレセプションの Golden Crown Shop です。',
      'sisu':
        'Sisu は1928年に発売されたフィンランドのパスティーユのブランドです。レシピは化学者の Johan Ponkamo がトゥルクの菓子工場 Seres の地下室で考え出したもので、パスティーユはアラビアゴムをベースにサルミアッキの味をつけたものです。ブランドは現在 Cloetta の傘下にあり、サルミアッキ、メントール、リコリスのパスティーユ、シュガーレスとキシリトールの製品、2022年からはキャンディの袋入り製品も扱っています。',
      'kultakuume-com':
        'Kultakuume はフィンランド・ラップランドのサーリセルカにある家族経営の事業で、2008年からこの地域で営業し、2009年からコテージを貸し出してきたとしています。自社の採掘権区域でガイド付きの砂金採りの一日を販売しており、訪れた人は手作業のパンニングを教わり、機械による洗鉱を見学し、見つけた金は持ち帰れます。ツアーのほか、カウニスパーの Kultakelo ログコテージを貸し出し、砂金採りをテーマにした各100×100 cm のキャンバスプリント18点のセットも販売しています。',
      'muurla':
        'Muurla はフィンランドのデザイン企業で、その歩みは南西フィンランドのムールラにあるガラス工場から始まり、工場の直営店は1974年春に開店しました。今日はホーローのマグや食器、ガラス製品、白樺の突き板のサービングボード、そしてライセンスによるムーミンのコレクションで知られています。Muurla によれば、製品はすべてフィンランドでデザインされていますが、製造国は製品によって異なり、白樺の突き板の製品はフィンランド、ホーロー製品の大半はヨーロッパ、ガラスはヨーロッパとアジアの両方で作られています。',
      'novita':
        'Novita は1928年に Ernst Gylfe が創業したフィンランドの毛糸会社で、Gylfe はイングランドのブラッドフォードで梳毛紡績を学んだのちヘルシンキで生産を始めました。事業は今も家族経営で4代目にあたり、1974年からコウヴォラのコリアで紡績工場を運営しており、同社によれば年間およそ100万キロの毛糸を生産しています。最もよく知られている製品はソックヤーンの 7 Veljestä で、原料の羊毛は主にヨーロッパ、とりわけイングランドから調達していると同社は報告しています。',
      'mikebon':
        'Mikebon Oy は1994年に創業した家族経営のテキスタイルプリント・刺繍会社で、ヴァンターのペティッコを拠点としています。デザイン、グラフィックの制作、生産、物流を自社で行っており、自社サイトでは生産はフィンランドで行っているとしています。主な取引先はみやげ物とギフトの小売店で、消費者向けのウェブショップも運営しており、その品ぞろえにはラップランド、フィンランド、ムーミンをテーマにしたシャツやパーカーがあります。',
      'aromageddon':
        'Aromageddon はヘルシンキで登記された Aromageddon Oy のサウナ用フレグランスのシリーズで、同社は着想を2024年夏のサウナのひとときにさかのぼるとしています。ラインナップは15 mlの香り6種類が各7.90ユーロ、それにギフトセット3種類で、テーマは森や白樺ではなく飲み物と菓子から取られています。ウイスキー、ビール、アイスミント、ペパーミントキャンディ、シナモン、ミントココアです。同社は自社サイトですべての香りについて CLP の安全データシートを公開しており、飲み物をテーマにした種類はアルコールを含まずに風味の印象を持たせています。',
      'leijona':
        'Leijona は Cloetta が所有するフィンランドのパスティーユのブランドで、砂糖でコーティングしタールの風味をつけたリコリスのパスティーユ Leijona Tervalakritsi でよく知られています。開発したのはオウルの菓子会社 Merijal の創業者で薬剤師の Yrjö Jalander で、製品は1933年に市場に出ました。現在のラインナップには32 gのパスティーユの箱に加えて180 gのキャンディ袋があり、ブランドはトゥルクの Cloetta Suomi Oy が運営しています。',
    },
  },
  'zh-CN': {
    eyebrow: '品牌',
    founded: (y) => `创立于 ${y} 年`,
    officialSite: (n) => `${n} 官方网站`,
    productsH2: (n) => `本店的${n}商品`,
    indexH1: '我们的品牌',
    indexIntro:
      '这家店里的东西由谁制作、在哪里制作。每篇介绍都依据品牌自己公布的信息写成,并链接到其官方网站。',
    indexCount: (n) => `${n} 件商品`,
    profile: {
      'aarikka':
        'Aarikka 是芬兰设计公司，1954 年由 Kaija Aarikka 和 Erkki Ruokonen 创立，以木珠和首饰闻名，2017 年起由 Martinex Oy 拥有。品牌把设计以及木质首饰和木质家居产品的手工组装归于芬兰，但并未把自己表述为完全在芬兰制造的产品系列。其服装按单件产品明确标注了芬兰以外的制造国，部分原材料也从国外采购。',
      'foodin':
        'Foodin 是一家芬兰家族所有的有机食品公司，位于于韦斯屈莱的 Vaajakoski，公司称自己从事制造，而不只是进口。其生巧克力系列在公司自有的 Vaajakoski 工厂石磨并手工完成，可可来自秘鲁亚马逊地区种植的 Criollo 豆。同一工厂也被列为公司蛋白棒的生产地点。',
      'kuivalihakundi':
        'Kuivalihakundi（Dried Buddy Oy）是芬兰肉干制造商，在图苏拉 Jokela 自有的核准肉类加工厂完成肉品的干燥、切割和包装；该设施约 1,500 平方米，公司于 2023 年底迁入。制造地点既有品牌自己的网页佐证，也有市政当局关于食品经营场所的正式决定佐证。品牌自己的标签写明牛肉在欧盟境内饲养和屠宰，因此原料肉本身未确认为芬兰产。',
      'halti':
        'Halti 是芬兰户外品牌，1976 年由 Juhani Hyokyvaara 创立，设计在其 Sipoo 总部完成。品牌在自家网站上说明，生产分散在多个国家：技术运动服装来自中国、越南和孟加拉国，另有意大利、乌克兰和立陶宛的欧洲供应商。按 Halti 自己的说法，只有袜子和针织帽在芬兰制造，因此该品牌应描述为芬兰设计，而非芬兰制造。',
      'north-outdoor':
        'North Outdoor 是由 Pyka Oy 经营的芬兰美利奴羊毛服装品牌，最为人知的是 2021 年在奥卢 Rusko 区开设的针织厂，Yle 报道称其为芬兰最大的羊毛衫工厂。品牌把生产分散到多个国家，并按产品类别而非单一原产地来描述这种分工。其自己公布的英文分工说明前后不一致，因此不应把各类别的具体分工当作已确定的事实复述。',
      'marttiini':
        'Marttiini 是芬兰刀具品牌，始于 1928 年，当时铁匠 Janne Marttiini 在罗瓦涅米开设了 puukko 刀作坊。如今的产品目录从猎刀、剔鱼刀到厨刀、折刀和传统 puukko 刀，刀柄用卷曲桦木或驯鹿角，刀身配皮鞘。宽刃的 Lapinleuku 和把品牌带入出口市场的剔鱼刀是其最易辨认的造型。',
      'kupilka':
        'Kupilka 是芬兰户外餐具品牌，由北卡累利阿 Kontiolahti 的家族公司 Plasthill Oy 经营。其杯子、盘子和餐具用自有的 Kareline 天然纤维复合材料模压而成，材料约一半是北欧针叶木纤维素、一半是食品级聚烯烃，在 Pyytivaara 厂区以认证可再生电力自行生产。餐具的原产地由品牌充分记录，但更广的产品线（尤其是刀具和打火棒）依赖外部供应商。',
      'nordicbuddies':
        'Nordicbuddies 是总部位于赫尔辛基的芬兰设计公司（注册名为 Oy Bisly Ltd），也是姆明、长袜子皮皮和 Mauri Kunnas 的官方被许可方，销售袜子、衬衫、帽子、包袋等配饰。设计工作在赫尔辛基完成，但品牌自己的 About Us 页面把制造主要放在欧洲和欧亚地区，只有一部分生产在芬兰，其棉花来自中国安徽和河南地区。零售商申报的原产地数据在单品层面指向中国，因此该品牌应描述为芬兰设计，而非芬兰制造。',
      'marimekko':
        'Marimekko 于 1951 年在芬兰创立，至今在赫尔辛基经营自有的纺织印花厂，每年印制超过一百万米面料，包括所有按米出售的面料。成品本身由合作供应商网络缝制，Marimekko 列出的制造国包括芬兰、波罗的海国家、葡萄牙、中国和泰国。2025 年有 54% 的产品在欧盟及其他欧洲国家生产，因此在未核对具体单品之前，不能假定某件 Marimekko 产品是在芬兰制造的。',
      'rento':
        'Rento 是芬兰设计的桑拿用品系列，由坦佩雷的家族公司 Tammer Brands Oy 拥有。品牌在芬兰设计，并广泛使用 Design from Finland 标志，但生产分散在芬兰、其他欧洲国家以及通过 Amfori BSCI 审核的工厂，原产国按产品而非按品牌确定。以 Rento 名义销售的若干产品在芬兰以外制造，因此原产地必须逐件产品核对。',
      'lapuan-kankurit':
        'Lapuan Kankurit 是芬兰织造公司，主厂在拉普阿，源头可追溯到 1917 年。按其自己的说法，95% 的产品在拉普阿织造，其余在立陶宛考纳斯一家参股工厂以及欧洲分包商处制造。所有原材料都来自芬兰以外：亚麻来自法国、荷兰和比利时，马海毛来自南非。',
      'iittala':
        'Iittala 是围绕 Iittala 玻璃厂建立的芬兰设计品牌，该厂 1881 年创立于 Iittala 村，现属 Fiskars Group。其母公司称海门林纳的厂区是芬兰唯一仍在运营的玻璃厂，约有 200 名员工；Iittala 在自家网站上说明，Alvar Aalto 花瓶和 Ultima Thule 玻璃器皿在那里由人工吹制。不过其陶瓷制品由国外的代工厂生产，因此芬兰原产的说法仅适用于玻璃制品。',
      'arctic-warriors':
        'Arctic Warriors 是一家小型芬兰天然产品公司，注册地在拉普兰罗瓦涅米附近的 Narkaus 村，成立于 2014 年。公司销售浆果和草本粉末以及甘油基草本酏剂，原料是来自当地小农和采集者的拉普兰草本与浆果。其自己的产品页面把原产地标为芬兰，但未说明生产或包装地点。',
      'makia':
        'Makia 是总部位于赫尔辛基的服装公司，成立于 2001 年，在芬兰设计、在国外制造。其自己的网页把土耳其列为主要生产国，夹克和大多数配饰来自中国，袜子来自葡萄牙和土耳其，另有一小部分羊毛配饰在芬兰制造。不过品牌自己的网页在完整国家清单上互相矛盾，因此无法把各类别的确切原产地分工当作已核实的信息陈述。',
      'pentik':
        'Pentik 是芬兰家居用品品牌，1971 年始于 Posio，至今在那里经营一家陶瓷厂和相邻的蜡烛作坊。不过该厂并不覆盖全部产品线：按品牌自己的可持续发展报告，2022 年约四分之一的产品在芬兰制造，其余从欧洲和亚洲其他地方采购。Pentik 曾表示，它不会在产品上突出标示制造国。',
      'arabia':
        'Arabia 是芬兰陶瓷和餐具品牌，根植于赫尔辛基的 Arabianranta 区，如今由 Fiskars Group 拥有。其赫尔辛基陶瓷厂已于 2016 年春季停产，Fiskars 在自家品牌页面上说明，Arabia 产品现在来自长期代工厂，主要在泰国和罗马尼亚。设计和产品开发仍在芬兰进行，赫尔辛基的 Arabia 街区继续作为博物馆、商店和设计中心运营。',
      'fazer':
        'Fazer 是芬兰食品公司，1891 年在赫尔辛基创立，以 Karl Fazer 牛奶巧克力、Geisha 和 Marianne 最为人知。除糖果外，集团还在多个国家经营烘焙、面粉厂和餐饮业务。其生产布局目前正在变化：拉赫蒂正在建设一座新的巧克力工厂，2026 年夏天 Fazer 收购了瑞典的糖果工厂。',
      'moomin':
        'Moomin Characters Oy Ltd 是位于赫尔辛基的家族公司，拥有并管理 Tove Jansson 笔下姆明角色的权利；这些角色首次出现在 1945 年的《姆明和大洪水》一书中。公司数十年前就不再自行生产商品：以姆明产品名义出售的每一件物品都来自被许可方，这一网络在全球有 800 多家。在礼品方面最易辨认的产品线是 Arabia 的姆明陶瓷马克杯，该系列始于 1990 年，如今已有一百多种设计。',
      'wild-about-lapland':
        'Wild About Lapland 是一家位于罗瓦涅米的活动运营商，办公地点在 Rovakatu 24。每次行程的参与人数上限为八人，项目全年运行：冬季有北极光之旅、雪地摩托狩猎之旅以及驯鹿和哈士奇拜访，夏季有独木舟和徒步。创始人兼首席向导 Theo Turner 曾是英国皇家海军陆战队突击队员和户外教练，公司持有 Sustainable Travel Finland 标章。',
      'meritalo':
        'Meritalo 是一家芬兰家族浆果加工企业，由 Susanna 和 Olavi Lindstedt 于 1995 年创立，两人从赫尔辛基迁到芬兰西南部 Salo 地区的 Ylonkyla。公司表示，其所有产品都在当地自有厂房制作，使用 100% 芬兰浆果和水果，原料购自芬兰种植者并采自芬兰森林。产品线以果酱和果冻、果汁和桦树汁为主，包括一款 310 克沙棘果酱，以及草莓、越橘和苹果产品。',
      'nordqvist':
        'Nordqvist 是一家芬兰茶叶公司，成立于 1979 年，起初是赫尔辛基一家销售调味茶和散叶茶的商店，后来转向进口和批发。其茶叶在公司位于 Nurmijärvi 的自有工厂调味和包装，这座 3000 平方米的工厂于 2018 年启用。产品线包括 Keisarin Morsian 和 Tiikerin Päiväuni 等长期在售的拼配茶，以及以姆明为主题的茶系列，有袋泡、散叶和铁罐装。',
      'puhdistamo':
        'Puhdistamo 是一家芬兰健康品牌，成立于 2009 年，销售维生素、矿物质和其他膳食补充剂，以及能量饮料、康普茶、蛋白棒和生可可棒、超级食品。公司在芬兰 Lempäälä 经营自有工厂，大部分补充剂在此制造，公司称一年内生产超过 8000 万粒胶囊。该厂持有 FSSC 22000 食品安全认证，公司表示其饮料使用甜叶菊或有机蔗糖增甜，而非阿斯巴甜、安赛蜜或三氯蔗糖。',
      'emendo':
        'Emendo Oy 是一家位于 Vaasa 的芬兰桑拿和健康用品公司，公司在自有网站上表示成立于 1986 年。产品涵盖桑拿和 loyly 香氛、桑拿蜂蜜、亚麻棉桑拿纺织品、水勺、肥皂和护肤品，以 Emendo 和 KOLO Sauna 两个名称销售。公司称其香氛、桑拿蜂蜜以及面部、身体和足部护理产品在芬兰制造，其姆明桑拿用品获 Moomin Characters 授权，基于托韦·扬松的原始画作。',
      'moomin-arabia':
        'Moomin Arabia 是芬兰陶瓷品牌 Arabia 的姆明系列，Arabia 成立于 1873 年，如今属于 Fiskars Group。首批姆明餐具出现在 1950 年代，插画由托韦·扬松绘制，广受收藏的马克杯系列则在 1990 年代开始，采用 Kaj Franck 设计的 Teema 杯型。设计工作在公司位于芬兰埃斯波的总部完成，而 Fiskars Group 表示 Arabia 产品主要由泰国和罗马尼亚的代工厂生产。',
      'kaino-drinks':
        'KAINO Drinks 是 Poikain Parhaat Oy 推出的无酒精气泡饮料系列，这家食品公司位于芬兰坦佩雷。云杉嫩芽饮料在坦佩雷手工制作，使用芬兰云杉嫩芽，饮料酒精度为 0.0%，为纯素并获 FI-EKO-201 有机认证。产品线包括云杉嫩芽、大黄与玫瑰、黑加仑叶，有 0.75 升和 0.2 升瓶装。',
      'omega7':
        'Omega7 是芬兰沙棘油补充剂品牌，首批产品于 1997 年上市。其 SBA24 双重沙棘油结合了果肉油和籽油，在公司位于 Tornio 的工厂以无溶剂工艺萃取。生产商 Aromtech Oy 与图尔库大学和图尔库大学医院的研究人员及医生开展过临床研究，并在拉普兰的 Tervola 运行有机沙棘种植试点。',
      'kaapa-mushrooms':
        'KÄÄPÄ Mushrooms 是一家芬兰功能性蘑菇生产商，由 Eric Puro、Otso Mursula 和 Seppo Riikonen 于 2018 年创立。总部和生产设施位于芬兰南部的 Karjalohja，蘑菇在取自 FSC 和 PEFC 认证芬兰森林的桦木基质上培育，并以公司自有的 NordRelease 超声波方法用净化泉水萃取。公司持有 FSSC 22000 食品安全认证，其提取物取自子实体而非菌丝谷物，并通过 KÄÄPÄ Forest 部门经营森林桦褐孔菌培育网络。',
      'halva':
        'Halva 是一家芬兰家族糖果公司，1931 年由从希腊迁居芬兰的兄弟 Jean 和 Michael Karavokyros 创立。它最为人熟知的是甘草糖和咸甘草糖，公司表示其糖果工厂和包装厂位于赫尔辛基的 Pitajanmaki。企业现由第三代经营，为公司命名的芝麻酱哈尔瓦仍在产品线中。',
      'kilpissafarit':
        'Kilpissafarit 是 Kilpisjarvi 的一家项目服务公司，1995 年由边防军人 Hannu Rauhala 创立，现由其子 Jussi Rauhala 经营。公司在 Kasivarsi 荒野带领雪地摩托狩猎之旅、雪鞋和徒步行程、北极光出行和钓鱼行程，包括通往芬兰最高点 Halti 的雪地摩托路线。同一基地也出租雪地摩托、电动胖胎自行车、雪鞋、独木舟和皮划艇，供自行出行的人使用。',
      'kaavi-porcini':
        'Kaavi Porcini 是 Kaavin Herkkutattitehdas Oy 的品牌，这家芬兰公司在自有的 Tohmajärvi 工厂烘干野生林地蘑菇。蘑菇采自北萨沃和北卡累利阿的森林，并在采摘当天烘干。产品线包括牛肝菌、鸡油菌、灰喇叭菌和黑喇叭菌，还有采自 Kittilä 的桦褐孔菌，以及用作调味的牛肝菌粉。',
      'tammer':
        'Tammer Brands 是一家来自坦佩雷的家族企业，1954 年以 Tammer-Tukku 之名创立，2019 年更名为 Tammer Brands Oy。公司开发和分销家居、园艺和休闲类消费品，旗下有 50 多个品牌，其中包括 Rento 桑拿系列、Mustang 烧烤品牌和 Maku Kitchen Life。关于 Rento，公司表示产品在芬兰、欧洲其他地区或经 amfori BSCI 审核的工厂生产，每张产品卡上都标注制造国。',
      'finlayson':
        'Finlayson 的起点可追溯到 1820 年，当时苏格兰人 James Finlayson 在坦佩雷的 Tammerkoski 急流旁建立了一间机械作坊。围绕它发展起来的棉纺厂到 1975 年成为芬兰最大的私营雇主，拥有 11 家工厂和 6500 名员工，公司至今仍以 Laina Koskela 在 1969 年设计的 Elefantti 图案等家喻户晓的产品，以及 1963 年把被套推向芬兰市场而为人所知。如今 Finlayson 销售床品、毛巾、厨房纺织品和地毯，公开其工厂名单，并在芬兰用顾客回收的床单织造 Rasypala 地毯。',
      'finnish-flavours':
        'Finnish Flavours 是一个从 Kerava 运营的芬兰食品品牌。产品以两条甘草糖产品线为核心，即 Premium Palalaku 块状糖和巧克力包衣的 Premium Chocolaku，此外还有越橘、蓝莓和云莓果酱、芬兰虹鳟以及驯鹿肉干。该品牌表示其果酱在芬兰制作，完全使用本国浆果，其列出的零售商从芬兰的 K 超市和罗瓦涅米的一家商店，到美国、加拿大、瑞士、英国和新西兰的进口商。',
      'aurora-borealis':
        'Aurora Borealis 是 Tammer Brands Oy 的自有品牌，后者是一家总部位于坦佩雷的芬兰家族品牌和批发公司，源头可追溯到 1954 年。产品涵盖装饰品、日用品、配饰和旗帜，围绕芬兰自然主题：森林、驯鹿、哈士奇、北极光和芬兰国旗。以该名称销售的产品包括木质 kuksa 杯、驯鹿和哈士奇毛绒玩具、马克杯、手提袋和扑克牌。',
      'fiskars':
        'Fiskars 始于 1649 年，当时 Peter Thorwöste 获准在一个同名的芬兰村庄建立高炉和铁匠铺。该品牌最为人熟知的是橙色手柄剪刀，它在 1967 年推出，是首款采用塑料手柄的剪刀；Classic 型号至今仍在公司位于芬兰的 Billnäs 工厂生产，每一把都经手工检验。除剪刀外，Fiskars 还销售园艺工具、斧头和厨刀。',
      'arctic-power-berries':
        'Arctic Power Berries 是由 Anna 和 Eveliina 经营的浆果粉品牌，两人是来自芬兰拉普兰罗瓦涅米的儿时好友，移居伦敦后创办了这家企业。产品为 70 克装的单一浆果粉：蓝莓（欧洲越橘）、越橘、沙棘、黑加仑、蔓越莓、草莓和树莓，另有一款混合浆果配方。公司表示野生浆果在芬兰手工采摘，经温和干燥并研磨，每 70 克一袋约需 700 克新鲜浆果，不添加其他成分。',
      'golden-crown-levin-iglut':
        'Levin Iglut Golden Crown 是一家家族经营的玻璃冰屋度假村，位于芬兰拉普兰 Levi 旁的 Utsuvaara 山丘上。Tauno Mäkelä 于 2008 年建成最初的四座冰屋，如今园区有 27 座玻璃冰屋、可住六人的 Northern Lights House 别墅和自营的 Restaurant Utsu，营业期为 8 月下旬至 4 月初。对送礼者而言，相关的是冰屋住宿和 Utsu 晚餐的礼品卡，以及前台的 Golden Crown Shop，那里出售芬兰设计和手工艺品牌。',
      'sisu':
        'Sisu 是 1928 年推出的芬兰润喉糖品牌。配方由化学家 Johan Ponkamo 在图尔库 Seres 糖果厂的地下室研制，糖片以阿拉伯胶为基底，带咸甘草风味。该品牌现属 Cloetta 旗下，产品涵盖咸甘草、薄荷和甘草润喉糖、无糖和木糖醇版本，2022 年起还有袋装糖果。',
      'kultakuume-com':
        'Kultakuume 是芬兰拉普兰 Saariselkä 的一家家族企业，该公司称自 2008 年起在当地经营，并自 2009 年起出租小屋。它销售在自有采矿权地块上的向导式淘金日，游客会学习手工淘洗、观看机械洗选，并可保留自己找到的黄金。除行程外，公司还出租 Kaunispää 上的 Kultakelo 原木小屋，并销售一套 18 幅淘金主题的画布印刷品，每幅 100 x 100 厘米。',
      'muurla':
        'Muurla 是一家芬兰设计公司，其故事始于芬兰西南部 Muurla 的一家玻璃厂，工厂商店于 1974 年春季开业。如今它以搪瓷马克杯和餐具、玻璃器皿、桦木单板餐板，以及授权的姆明系列而为人所知。Muurla 表示其所有产品均在芬兰设计，而制造国因产品而异：桦木单板产品在芬兰制造，多数搪瓷制品在欧洲，玻璃制品在欧洲和亚洲。',
      'novita':
        'Novita 是一家芬兰纱线公司，1928 年由 Ernst Gylfe 创立，他先在英格兰 Bradford 学习精纺羊毛纺纱，之后在赫尔辛基开始生产。企业至今仍为家族所有，已传至第四代，自 1974 年起在 Kouvola 的 Koria 经营纺纱厂，公司称年产约一百万公斤纱线。其最知名的产品是 7 Veljestä 袜子纱，公司称其羊毛主要采购自欧洲，以英格兰为主。',
      'mikebon':
        'Mikebon Oy 是一家家族经营的纺织印花和刺绣公司，1994 年创立，位于 Vantaa 的 Petikko。公司自行负责设计、图形执行、生产和物流，并在自有网站上表示生产在芬兰进行。其主要客户是纪念品和礼品零售商，同时也经营面向消费者的网店，产品包括拉普兰、芬兰和姆明主题的 T 恤和连帽衫。',
      'aromageddon':
        'Aromageddon 是 Aromageddon Oy 推出的桑拿香氛系列，该公司在赫尔辛基注册，并把这个想法的起点定在 2024 年夏天的一次桑拿。产品线包括六款 15 毫升香氛，每款 7.90 欧元，另有三款礼盒，主题来自饮品和糖果而非森林或桦树：威士忌、啤酒、冰薄荷、薄荷糖、肉桂和薄荷可可。公司在自有网站上为每款香氛公布 CLP 安全数据表，饮品主题的版本带有该风味但不含酒精。',
      'leijona':
        'Leijona 是 Cloetta 旗下的芬兰润喉糖品牌，最为人熟知的是 Leijona Tervalakritsi，一种带焦油风味的糖衣甘草润喉糖。它由药剂师 Yrjö Jalander 研制，他是奥卢糖果公司 Merijal 的创始人，产品于 1933 年上市。除 32 克装润喉糖盒外，当前产品线还包括 180 克袋装糖果，该品牌由位于图尔库的 Cloetta Suomi Oy 运营。',
    },
  },
  ko: {
    eyebrow: '브랜드',
    founded: (y) => `${y}년 설립`,
    officialSite: (n) => `${n} 공식 사이트`,
    productsH2: (n) => `이 상점의 ${n}`,
    indexH1: '취급 브랜드',
    indexIntro:
      '이 상점의 물건을 누가 어디서 만드는가. 각 소개는 브랜드가 스스로 공개한 내용을 바탕으로 쓰였고 공식 사이트로 연결됩니다.',
    indexCount: (n) => `상품 ${n}개`,
    profile: {
      'aarikka':
        'Aarikka는 1954년 Kaija Aarikka와 Erkki Ruokonen이 설립한 핀란드 디자인 하우스로, 나무 비즈와 주얼리로 알려져 있으며 2017년부터 Martinex Oy가 소유하고 있습니다. 브랜드는 디자인과 나무 주얼리 및 목재 홈 제품의 수작업 조립을 핀란드에서 한다고 밝히지만, 제품군 전체가 핀란드에서 제조된다고 내세우지는 않습니다. 의류에는 핀란드 밖의 제조국이 제품별로 명시되어 있고, 일부 원자재는 해외에서 조달됩니다.',
      'foodin':
        'Foodin은 위베스퀼레(Jyväskylä)의 바야코스키(Vaajakoski)에 본사를 둔 가족 소유 핀란드 유기농 식품 회사로, 수입만 하는 것이 아니라 제조도 한다고 스스로 설명합니다. 로 초콜릿 제품군은 회사 자체 바야코스키 공장에서 돌로 갈아 손으로 마무리하며, 카카오는 페루 아마존에서 재배된 크리올로(Criollo) 원두를 씁니다. 같은 공장은 이 회사 단백질 바의 생산지로도 명시되어 있습니다.',
      'kuivalihakundi':
        'Kuivalihakundi(Dried Buddy Oy)는 투술라(Tuusula)의 요켈라(Jokela)에 있는 자사 승인 육류 가공장에서 고기를 건조하고 자르고 포장하는 핀란드 육포 제조사로, 2023년 말에 약 1,500 m2 규모의 이 시설로 옮겼습니다. 제조 장소는 브랜드 자체 페이지와 지자체의 공식 식품취급장 결정 양쪽으로 뒷받침됩니다. 브랜드 자체 표기에 따르면 소고기는 EU에서 사육되고 도축되므로, 원료육 자체가 핀란드산이라고 확인되지는 않습니다.',
      'halti':
        'Halti는 1976년 Juhani Hyokyvaara가 설립한 핀란드 아웃도어 브랜드로, 디자인은 시포(Sipoo) 본사에서 이루어집니다. 브랜드는 자사 사이트에서 생산이 여러 나라에 나뉘어 있다고 밝힙니다: 기능성 스포츠웨어는 중국, 베트남, 방글라데시에서 만들고, 여기에 이탈리아, 우크라이나, 리투아니아의 유럽 공급업체가 더해집니다. Halti 자신의 설명에 따르면 핀란드에서 만들어지는 것은 양말과 비니뿐이므로, 이 브랜드는 핀란드 제조가 아니라 핀란드 디자인으로 설명해야 합니다.',
      'north-outdoor':
        'North Outdoor는 Pyka Oy가 운영하는 핀란드 메리노 울 의류 브랜드로, 2021년 오울루(Oulu)의 루스코(Rusko) 지구에 문을 연 편직 공장으로 가장 잘 알려져 있으며, Yle은 이 공장을 핀란드 최대의 울 스웨터 공장으로 보도했습니다. 브랜드는 생산을 여러 나라에 나누고 있으며, 원산지를 하나로 밝히는 대신 제품 카테고리별로 그 분담을 설명합니다. 다만 그 분담에 관한 브랜드 자체 영문 설명은 내용이 서로 어긋나므로, 카테고리별 구분을 확정된 사실로 옮겨서는 안 됩니다.',
      'marttiini':
        'Marttiini는 1928년 대장장이 Janne Marttiini가 로바니에미에 푸코(puukko) 공방을 열면서 시작된 핀란드 나이프 브랜드입니다. 오늘날 제품군은 사냥용 나이프와 필렛 나이프부터 주방용 나이프, 접이식 나이프, 전통 푸코까지 이어지며, 손잡이는 무늬자작나무나 순록 뿔로 만들고 칼날은 가죽 칼집에 담아 제공합니다. 날이 넓은 라핀레우쿠(Lapinleuku)와 브랜드를 수출 시장으로 이끈 필렛 나이프가 가장 알아보기 쉬운 형태입니다.',
      'kupilka':
        'Kupilka는 북카렐리아 콘티올라흐티(Kontiolahti)에 있는 가족 회사 Plasthill Oy가 운영하는 핀란드 아웃도어 식기 브랜드입니다. 컵, 접시, 커틀러리는 북유럽산 침엽수 셀룰로스 약 절반과 식품용 폴리올레핀 약 절반으로 이루어진 자체 Kareline 천연섬유 복합재로 성형되며, 인증 재생에너지 전력을 쓰는 Pyytivaara 공장에서 자체 생산됩니다. 식기의 원산지는 브랜드가 잘 문서화해 두었지만, 더 넓은 제품군(특히 나이프와 파이어 스틸)은 외부 공급업체에 의존합니다.',
      'nordicbuddies':
        'Nordicbuddies는 헬싱키에 자리한 핀란드 디자인 회사(등록명 Oy Bisly Ltd)이자 무민, Pippi Longstocking, Mauri Kunnas의 공식 라이선시로, 양말, 셔츠, 모자, 가방 등 액세서리를 판매합니다. 디자인 작업은 헬싱키에서 하지만, 브랜드 자체 About Us 페이지는 제조가 주로 유럽과 유라시아에서 이루어지고 핀란드 생산은 일부뿐이며 면화는 중국 안후이성과 허난성에서 온다고 밝힙니다. 소매점이 신고한 원산지 자료는 제품 단위에서 중국을 가리키므로, 이 브랜드는 핀란드 제조가 아니라 핀란드 디자인으로 설명해야 합니다.',
      'marimekko':
        'Marimekko는 1951년 핀란드에서 설립되었고 지금도 헬싱키에서 자체 텍스타일 프린팅 공장을 운영하며, 이곳에서 연간 100만 미터가 넘는 원단을 인쇄합니다. 미터 단위로 판매되는 원단은 모두 여기서 인쇄됩니다. 완제품 자체는 협력 공급업체 네트워크가 봉제하며, Marimekko는 제조국으로 핀란드, 발트 국가들, 포르투갈, 중국, 태국을 꼽습니다. 2025년에는 제품의 54퍼센트가 EU 및 그 밖의 유럽 국가에서 만들어졌으므로, 개별 제품을 확인하지 않고 Marimekko 제품이 핀란드에서 만들어졌다고 단정할 수는 없습니다.',
      'rento':
        'Rento는 탐페레(Tampere)의 가족 회사 Tammer Brands Oy가 소유한, 핀란드에서 디자인된 사우나 용품군입니다. 브랜드는 핀란드에서 디자인하고 Design from Finland 마크를 폭넓게 달고 있지만, 생산은 핀란드, 다른 유럽 국가, 그리고 Amfori BSCI 감사를 받은 공장으로 나뉘며, 원산지는 브랜드 단위가 아니라 제품 단위로 정해집니다. Rento로 판매되는 여러 제품이 핀란드 밖에서 만들어지므로, 원산지는 제품마다 확인해야 합니다.',
      'lapuan-kankurit':
        'Lapuan Kankurit은 주력 공장이 라푸아(Lapua)에 있고 뿌리가 1917년까지 거슬러 올라가는 핀란드 직물 회사입니다. 자체 설명에 따르면 제품의 95%를 라푸아에서 직조하고, 나머지는 리투아니아 카우나스에 있는 일부 지분 보유 공장과 유럽 하청업체가 만듭니다. 원자재는 모두 핀란드 밖에서 옵니다: 아마는 프랑스, 네덜란드, 벨기에에서, 모헤어는 남아프리카공화국에서 옵니다.',
      'iittala':
        'Iittala는 1881년 Iittala 마을에 세워졌고 현재 Fiskars Group에 속한 Iittala 유리 공장을 중심으로 한 핀란드 디자인 브랜드입니다. 모회사는 하멘린나(Hämeenlinna) 공장을 핀란드에서 아직 가동되는 유일한 유리 공장이라고 설명하며 약 200명이 일한다고 밝히고, Iittala는 자사 사이트에서 Alvar Aalto 화병과 Ultima Thule 유리가 그곳에서 입으로 불어 만들어진다고 밝힙니다. 다만 도자기는 해외 위탁 제조사가 만들므로, 핀란드 원산지 주장은 유리 제품에만 해당합니다.',
      'arctic-warriors':
        'Arctic Warriors는 2014년에 설립된 소규모 핀란드 천연 제품 회사로, 라플란드 로바니에미 인근 나르카우스(Narkaus) 마을에 등록되어 있습니다. 지역 소농과 채집인에게서 조달한 라플란드의 허브와 베리로 만든 베리 및 허브 분말과 글리세롤 기반 허브 엘릭서를 판매합니다. 자체 제품 페이지는 원산지를 핀란드로 표시하지만, 생산지나 포장지는 밝히지 않습니다.',
      'makia':
        'Makia는 2001년에 설립된 헬싱키 기반 의류 회사로, 핀란드에서 디자인하고 해외에서 제조합니다. 자체 페이지는 주요 생산국으로 튀르키예를 꼽으며, 재킷과 액세서리 대부분은 중국에서, 양말은 포르투갈과 튀르키예에서, 모직 액세서리의 일부는 핀란드에서 만든다고 밝힙니다. 다만 브랜드 자체 페이지들이 전체 국가 목록에서 서로 어긋나므로, 카테고리별 원산지 구분을 검증된 것으로 제시할 수는 없습니다.',
      'pentik':
        'Pentik은 1971년 포시오(Posio)에서 시작된 핀란드 홈웨어 브랜드로, 지금도 그곳에서 도자기 공장과 이에 딸린 양초 공방을 운영합니다. 다만 이 공장이 전체 제품군을 감당하지는 않습니다: 브랜드 자체 지속가능성 보고에 따르면 2022년에 제품의 약 4분의 1이 핀란드에서 만들어졌고, 나머지는 유럽과 아시아의 다른 지역에서 조달되었습니다. Pentik은 제품에 제조국을 부각하지 않는다고 밝힌 바 있습니다.',
      'arabia':
        'Arabia는 헬싱키의 아라비안란타(Arabianranta) 지역에 뿌리를 둔 핀란드 도자기 및 식기 브랜드로, 현재는 Fiskars Group이 소유하고 있습니다. 헬싱키 도자기 공장은 2016년 봄에 생산을 멈췄고, Fiskars는 자사 브랜드 페이지에서 Arabia 제품이 이제 주로 태국과 루마니아의 장기 위탁 제조사에서 나온다고 밝힙니다. 디자인과 제품 개발은 여전히 핀란드에서 이루어지며, 헬싱키의 Arabia 구역은 박물관과 매장, 디자인 센터로 이어지고 있습니다.',
      'fazer':
        'Fazer는 1891년 헬싱키에서 설립된 핀란드 식품 회사로, Karl Fazer 밀크 초콜릿과 Geisha, Marianne로 가장 잘 알려져 있습니다. 제과 외에도 그룹은 여러 나라에서 제빵, 제분, 레스토랑 사업을 운영합니다. 생산 거점은 현재 옮겨지는 중입니다: 라흐티(Lahti)에 새 초콜릿 공장이 지어지고 있고, 2026년 여름에 Fazer는 스웨덴의 제과 공장들을 인수했습니다.',
      'moomin':
        'Moomin Characters Oy Ltd는 Tove Jansson의 무민 캐릭터 권리를 소유하고 관리하는 헬싱키의 가족 회사이며, 이 캐릭터들은 1945년 책 『무민 가족과 대홍수』(The Moomins and the Great Flood)에서 처음 등장했습니다. 회사는 수십 년 전에 직접 상품을 만드는 일을 그만두었습니다: 무민 제품으로 판매되는 모든 품목은 라이선시가 만들며, 그 네트워크는 전 세계 800곳이 넘습니다. 선물 쪽에서 가장 잘 알려진 제품군은 Arabia의 무민 도자기 머그로, 1990년에 시작된 이 시리즈는 이제 100가지가 넘는 디자인을 아우릅니다.',
      'wild-about-lapland':
        'Wild About Lapland은 로바니에미에 자리한 액티비티 운영사로, 사무실은 Rovakatu 24에 있습니다. 모든 투어는 참가자 8명으로 제한되며 프로그램은 연중 운영됩니다. 겨울에는 오로라 투어, 스노모빌 사파리, 순록과 허스키 방문이 있고 여름에는 카누와 하이킹이 있습니다. 창업자이자 수석 가이드인 Theo Turner는 영국 왕립 해병대 코만도 출신의 아웃도어 강사이며, 회사는 Sustainable Travel Finland 인증을 보유하고 있습니다.',
      'meritalo':
        'Meritalo는 1995년 Susanna Lindstedt와 Olavi Lindstedt가 설립한 핀란드 가족 경영 베리 가공 회사입니다. 두 사람은 헬싱키에서 남서핀란드 살로 지역의 윌뢴퀼레(Ylönkylä)로 이주했습니다. 회사는 모든 제품을 그곳 자사 시설에서 만들며, 핀란드 재배 농가에서 구입하고 핀란드 숲에서 채집한 100% 핀란드산 베리와 과일을 사용한다고 밝히고 있습니다. 제품군은 잼과 젤리, 주스와 자작나무 수액을 중심으로 하며, 딸기와 링곤베리, 사과 제품과 함께 310 g 산자나무 잼이 포함됩니다.',
      'nordqvist':
        'Nordqvist는 1979년에 설립된 핀란드 차 회사로, 헬싱키에서 가향차와 잎차를 파는 상점으로 시작해 나중에 수입과 도매로 옮겨 갔습니다. 차의 가향과 포장은 2018년 문을 연 누르미예르비(Nurmijärvi)의 자사 공장 3,000제곱미터 규모 시설에서 이루어집니다. 제품군은 Keisarin Morsian과 Tiikerin Päiväuni 같은 오래된 블렌드와 함께 티백, 잎차, 틴으로 판매되는 무민 테마 차 라인을 다룹니다.',
      'puhdistamo':
        'Puhdistamo는 2009년에 설립된 핀란드 웰니스 브랜드로, 비타민과 미네랄 등 보충제와 함께 에너지 음료, 콤부차, 프로틴 바와 로 초콜릿 바, 슈퍼푸드를 판매합니다. 회사는 핀란드 렘패앨래(Lempäälä)에 자체 공장을 운영하며 보충제 대부분을 그곳에서 만들고, 한 해에 캡슐 8천만 개 이상을 생산했다고 전합니다. 이 공장은 FSSC 22000 식품안전 인증을 보유하고 있으며, 회사는 자사 음료가 아스파탐, 아세설팜칼륨, 수크랄로스 대신 스테비아나 유기농 사탕수수당으로 감미된다고 밝히고 있습니다.',
      'emendo':
        'Emendo Oy는 바사(Vaasa)에 본사를 둔 핀란드 사우나·웰니스 회사로, 자사 사이트에서 1986년에 설립되었다고 밝히고 있습니다. 제품군은 사우나와 뢰윌리 향, 사우나 꿀, 리넨 혼방 사우나 텍스타일, 국자, 비누, 스킨케어 제품을 다루며 Emendo와 KOLO Sauna 두 이름으로 판매됩니다. 회사는 향과 사우나 꿀, 얼굴·바디·발 관리 제품을 핀란드에서 제조한다고 말하며, 무민 사우나 제품은 Moomin Characters의 라이선스를 받아 Tove Jansson의 원화를 바탕으로 만들어집니다.',
      'moomin-arabia':
        'Moomin Arabia는 1873년에 설립되어 오늘날 Fiskars Group에 속한 핀란드 도자기 브랜드 Arabia의 무민 제품군입니다. 첫 무민 식기는 1950년대에 Tove Jansson의 일러스트와 함께 나왔고, 널리 수집되는 머그 시리즈는 1990년대에 Kaj Franck의 Teema 형태를 사용해 시작되었습니다. 디자인 작업은 핀란드 에스포(Espoo)의 본사에서 이루어지며, Fiskars Group은 Arabia 제품이 주로 태국과 루마니아의 위탁 제조사에서 만들어진다고 밝히고 있습니다.',
      'kaino-drinks':
        'KAINO Drinks는 핀란드 탐페레(Tampere)에 있는 식품 회사 Poikain Parhaat Oy의 무알코올 스파클링 음료 제품군입니다. 가문비나무 새순 음료는 핀란드산 가문비나무 새순으로 탐페레에서 손으로 만들어지며, 음료는 알코올 0.0%에 비건이고 FI-EKO-201 유기농 인증을 받았습니다. 제품군은 가문비나무 새순, 루바브와 장미, 블랙커런트 잎으로 이루어지며 0.75리터와 0.2리터 병으로 판매됩니다.',
      'omega7':
        'Omega7은 핀란드 산자나무 오일 보충제 브랜드로, 첫 제품이 1997년에 시장에 나왔습니다. SBA24 더블 산자나무 오일은 열매 오일과 씨 오일을 합친 제품이며, 토르니오(Tornio)의 자사 공장에서 용매를 쓰지 않는 공정으로 추출됩니다. 제조사인 Aromtech Oy는 투르쿠 대학교와 투르쿠 대학병원의 연구자, 의사들과 임상 연구를 진행해 왔고, 라플란드 테르볼라(Tervola)에서 유기농 산자나무 재배 시범 사업을 운영하고 있습니다.',
      'kaapa-mushrooms':
        'KÄÄPÄ Mushrooms는 2018년 Eric Puro, Otso Mursula, Seppo Riikonen이 설립한 핀란드 기능성 버섯 생산자입니다. 본사와 생산 시설은 남부 핀란드 카르얄로흐야(Karjalohja)에 있으며, 이곳에서 FSC와 PEFC 인증을 받은 핀란드 숲의 자작나무 배지에 버섯을 키우고 정제한 샘물을 쓰는 자체 NordRelease 초음파 방식으로 추출합니다. 회사는 FSSC 22000 식품안전 인증을 보유하고 있고, 균사가 자란 곡물이 아니라 자실체로 추출물을 만들며, KÄÄPÄ Forest 부문을 통해 숲 차가버섯 재배 네트워크를 운영합니다.',
      'halva':
        'Halva는 그리스에서 핀란드로 이주한 형제 Jean Karavokyros와 Michael Karavokyros가 1931년에 설립한 핀란드 가족 제과 회사입니다. 감초와 살미아키 사탕으로 가장 잘 알려져 있으며, 회사는 사탕 공장과 포장 공장이 헬싱키 피태얜매키(Pitäjänmäki)에 있다고 밝히고 있습니다. 사업은 지금 3대째가 운영하고 있고, 회사 이름의 유래가 된 참깨 페이스트 할바도 여전히 제품군에 남아 있습니다.',
      'kilpissafarit':
        'Kilpissafarit는 킬피스예르비(Kilpisjärvi)에 있는 프로그램 서비스 회사로, 1995년 국경수비대원 Hannu Rauhala가 설립했고 지금은 그의 아들 Jussi Rauhala가 운영합니다. 캐시바르시(Käsivarsi) 야생 지역에서 스노모빌 사파리, 스노슈와 하이킹 투어, 오로라 관람과 낚시 여행을 가이드하며, 핀란드에서 가장 높은 지점인 할티(Halti)로 가는 스노모빌 루트도 있습니다. 같은 기지에서 직접 나서는 사람들을 위해 스노모빌, 전기 팻바이크, 스노슈, 카누, 카약을 대여합니다.',
      'kaavi-porcini':
        'Kaavi Porcini는 토흐마예르비(Tohmajärvi)의 자사 공장에서 야생 숲 버섯을 건조하는 핀란드 회사 Kaavin Herkkutattitehdas Oy의 브랜드입니다. 버섯은 북사보와 북카렐리아의 숲에서 채취해 딴 당일에 건조합니다. 제품군은 포르치니, 꾀꼬리버섯, 깔때기꾀꼬리버섯, 뿔나팔버섯과 함께 키틸래(Kittilä)에서 채취한 차가버섯, 조미료로 쓰이는 포르치니 가루를 다룹니다.',
      'tammer':
        'Tammer Brands는 1954년 Tammer-Tukku로 설립되어 2019년 Tammer Brands Oy로 이름을 바꾼 탐페레(Tampere)의 가족 소유 회사입니다. 가정, 정원, 레저용 소비재를 50개가 넘는 브랜드 포트폴리오로 개발하고 유통하며, 그중에는 Rento 사우나 제품군, 그릴 브랜드 Mustang, Maku Kitchen Life가 있습니다. Rento에 대해 회사는 제품이 핀란드나 유럽의 다른 지역, 또는 amfori BSCI 감사를 받은 공장에서 만들어지며 제조 국가는 각 제품 카드에 표기된다고 밝히고 있습니다.',
      'finlayson':
        'Finlayson의 시작은 1820년, 스코틀랜드 사람 James Finlayson이 탐페레의 탐메르코스키(Tammerkoski) 급류 옆에 기계 작업장을 세운 때로 거슬러 올라갑니다. 그 주변에서 자란 면방직 공장은 1975년에 공장 11곳과 노동자 6,500명을 둔 핀란드 최대 민간 고용주가 되었고, 회사는 Laina Koskela가 1969년에 디자인한 Elefantti 패턴 같은 익숙한 이름들과 1963년 핀란드 시장에 이불 커버를 내놓은 일로 지금도 알려져 있습니다. 오늘날 Finlayson은 침구, 타월, 주방 텍스타일, 러그를 판매하고 협력 공장 목록을 공개하며, Rasypala 러그는 고객이 반납한 시트를 사용해 핀란드에서 직조합니다.',
      'finnish-flavours':
        'Finnish Flavours는 케라바(Kerava)에서 운영되는 핀란드 식품 브랜드입니다. 제품군은 Premium Palalaku 조각과 초콜릿을 입힌 Premium Chocolaku 두 라인의 감초를 중심으로 하며, 링곤베리와 블루베리, 클라우드베리 잼, 핀란드산 무지개송어, 말린 순록 고기가 함께 있습니다. 브랜드는 잼이 전부 국내산 베리로 핀란드에서 만들어진다고 밝히고 있으며, 소개된 판매처는 핀란드 K-스토어와 로바니에미의 상점부터 미국, 캐나다, 스위스, 영국, 뉴질랜드의 수입업체까지 이릅니다.',
      'aurora-borealis':
        'Aurora Borealis는 탐페레(Tampere)에 본사를 둔 핀란드 가족 소유 브랜드·도매 회사 Tammer Brands Oy의 자체 브랜드이며, 이 회사의 뿌리는 1954년으로 거슬러 올라갑니다. 제품군은 숲, 순록, 허스키, 오로라, 핀란드 국기 같은 핀란드 자연 모티프를 바탕으로 한 장식품, 일상용품, 액세서리, 깃발을 다룹니다. 이 이름으로 나오는 제품에는 나무 쿡사 컵, 순록과 허스키 봉제 인형, 머그, 토트백, 카드가 있습니다.',
      'fiskars':
        'Fiskars는 1649년 Peter Thorwöste가 같은 이름의 핀란드 마을에 용광로와 대장간을 세울 허가를 받으면서 시작되었습니다. 브랜드는 1967년 플라스틱 손잡이를 단 최초의 가위로 출시된 주황색 손잡이 가위로 가장 잘 알려져 있으며, Classic 모델은 지금도 핀란드 빌내스(Billnäs) 공장에서 만들어지고 모든 제품을 손으로 검사합니다. 가위와 함께 Fiskars는 원예 도구, 도끼, 주방칼을 판매합니다.',
      'arctic-power-berries':
        'Arctic Power Berries는 핀란드 라플란드 로바니에미 출신의 어린 시절 친구인 Anna와 Eveliina가 런던으로 이주한 뒤 시작한 베리 분말 브랜드입니다. 제품군은 70 g 파우치에 담긴 단일 베리 분말로, 블루베리(빌베리), 링곤베리, 산자나무, 블랙커런트, 크랜베리, 딸기, 라즈베리와 믹스 베리 블렌드가 있습니다. 회사는 야생 베리를 핀란드에서 손으로 따고 부드럽게 건조해 갈며, 70 g 파우치 하나에 생베리 약 700 g이 들어가고 다른 것은 넣지 않는다고 밝히고 있습니다.',
      'golden-crown-levin-iglut':
        'Levin Iglut Golden Crown은 핀란드 라플란드 레비 옆 우추바라(Utsuvaara) 산에 있는 가족 운영 유리 이글루 리조트입니다. Tauno Mäkelä가 2008년에 첫 이글루 네 채를 지었고, 지금은 유리 이글루 27채와 6인용 Northern Lights House 빌라, 자체 레스토랑 Utsu를 두고 8월 말부터 4월 초까지 문을 엽니다. 선물을 사는 사람에게 해당하는 품목은 이글루 숙박과 Utsu 저녁 식사 기프트 카드, 그리고 핀란드 디자인과 공예 브랜드를 취급하는 리셉션의 Golden Crown Shop입니다.',
      'sisu':
        'Sisu는 1928년에 나온 핀란드 파스틸 브랜드입니다. 레시피는 화학자 Johan Ponkamo가 투르쿠에 있던 Seres 제과 공장 지하에서 고안했고, 파스틸은 아라비아검을 기반으로 살미아키 맛을 냅니다. 브랜드는 이제 Cloetta의 포트폴리오에 속하며 살미아키, 멘톨, 감초 파스틸과 무설탕 및 자일리톨 제품, 2022년부터는 캔디 봉지 제품도 다룹니다.',
      'kultakuume-com':
        'Kultakuume는 핀란드 라플란드 사리셀캐(Saariselkä)에 있는 가족 운영 사업체로, 이 지역에서 2008년부터 영업했고 2009년부터 오두막을 임대해 왔다고 밝히고 있습니다. 자사 채굴권 구역에서 가이드가 함께하는 사금 채취 체험을 판매하며, 방문객은 손 팬닝을 배우고 기계식 세척을 지켜보며 찾아낸 금은 가질 수 있습니다. 체험과 함께 카우니스패(Kaunispää)의 Kultakelo 통나무 오두막을 임대하고, 사금 채취를 주제로 한 100 x 100 cm 캔버스 프린트 18점 세트를 판매합니다.',
      'muurla':
        'Muurla는 남서핀란드 무를라(Muurla)의 유리 공장에서 이야기가 시작된 핀란드 디자인 회사로, 공장 매장은 1974년 봄에 문을 열었습니다. 오늘날에는 에나멜 머그와 식기, 유리 제품, 자작나무 베니어 서빙 보드, 그리고 라이선스를 받은 무민 컬렉션으로 알려져 있습니다. Muurla는 모든 제품이 핀란드에서 디자인된다고 말하며, 제조 국가는 제품에 따라 다릅니다. 자작나무 베니어 제품은 핀란드에서, 에나멜 제품은 대부분 유럽에서, 유리는 유럽과 아시아 양쪽에서 만들어집니다.',
      'novita':
        'Novita는 1928년 Ernst Gylfe가 설립한 핀란드 실 회사로, 그는 잉글랜드 브래드퍼드에서 소모방적을 배운 뒤 헬싱키에서 생산을 시작했습니다. 사업은 지금도 4대째 가족 소유이며 1974년부터 코우볼라 코리아(Koria)에서 방적 공장을 운영하고, 그곳에서 연간 약 100만 킬로의 실을 생산한다고 밝히고 있습니다. 가장 잘 알려진 제품은 7 Veljestä 양말실로, 회사는 양모를 주로 유럽, 그중에서도 대부분 잉글랜드에서 조달한다고 전합니다.',
      'mikebon':
        'Mikebon Oy는 1994년에 설립되어 반타(Vantaa) 페티코(Petikko)에 자리한 가족 운영 텍스타일 프린팅·자수 회사입니다. 디자인, 그래픽 작업, 생산, 물류를 직접 처리하며, 자사 사이트에서 생산이 핀란드에서 이루어진다고 밝히고 있습니다. 주요 고객은 기념품과 선물 소매점이고, 라플란드와 핀란드, 무민 테마의 셔츠와 후디를 포함한 제품군을 갖춘 소비자용 온라인 상점도 운영합니다.',
      'aromageddon':
        'Aromageddon은 헬싱키에 등록된 회사 Aromageddon Oy의 사우나 향 제품군으로, 회사는 그 아이디어가 2024년 여름의 사우나에서 나왔다고 말합니다. 라인은 각 7.90유로인 15 ml 향 여섯 가지와 기프트 세트 세 가지로 이루어지며, 테마는 숲이나 자작나무가 아니라 음료와 과자에서 왔습니다. 위스키, 맥주, 아이스 민트, 페퍼민트 캔디, 시나몬, 민트 코코아입니다. 회사는 모든 향의 CLP 안전보건자료를 자사 사이트에 공개하며, 음료를 테마로 한 제품은 알코올 없이 그 맛의 향만 담고 있습니다.',
      'leijona':
        'Leijona는 Cloetta가 소유한 핀란드 파스틸 브랜드로, 타르로 맛을 낸 설탕 코팅 감초 파스틸 Leijona Tervalakritsi로 가장 잘 알려져 있습니다. 오울루의 제과 회사 Merijal을 세운 약사 Yrjö Jalander가 개발했고 1933년에 시장에 나왔습니다. 32 g 파스틸 상자와 함께 현재 제품군에는 180 g 캔디 봉지가 있으며, 브랜드는 투르쿠에서 Cloetta Suomi Oy가 운영합니다.',
    },
  },
}
